/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20161012-4","meetingId":"h28-c-settlement","date":"2016年10月12日","dateIso":"2016-10-12","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、平成２７年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、平成２７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１４３ページの予防接種費、それから１４６ページの乳児健康診査、それから１５０ページの資源回収事業についてお伺いいたします。１０月から定期接種になったＢ型肝炎ワクチンについてお伺いいたします。なぜＢ型肝炎ワクチンが定期接種になったのか、簡単にご説明をお願いいたします。","respondent":"舟木保健予防課長","answer":"１０月から定期接種化されたＢ型肝炎ワクチンについてご説明いたします。Ｂ型肝炎につきましては、国のほうで広く接種が望ましいワクチンということで定められておりまして、検討が進められていました。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"確認","question":"これは医療機関も区民もとてもわかりにくいと思いますし、間違えないように、具体的には区としてどのような対策をとられているのでしょうか。定期接種と任意接種の区別もそうですけれども、６カ月以降の赤ちゃんに関しては接種にお金がかかる人とかからない人が出てくるので、その辺はしっかりとした広報というのが必要だと思いますけれども、改めて確認させてください。","respondent":"舟木保健予防課長","answer":"お問い合わせがあれば、こちらのほうでもきちんと対応しているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"それで、Ｂ型肝炎ワクチンのことで、報道によると、Ｂ型肝炎ワクチンをつくっている化血研が、また厚生労働省から業務改善命令を受けていて、日本脳炎のワクチンもここがつくっているのですけれども、供給がとまってしまっているという状況です。この化血研が製造するＢ型肝炎ワクチンの供給にも不安があるということで、品川区としてはどう捉えているのか、対応をお考えなのか、お聞かせください。","respondent":"舟木保健予防課長","answer":"ただ、流通の調整とか、国は全体のワクチンの総数は足りているということなので、こちらでは現場の声を聞き取りまして、それを集めて、東京都あるいは国のほうに上げて、意見を言っているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"確認","question":"続きまして、１４６ページの乳児健康診査について、新生児聴覚検査についてお伺いしたいと思います。子どもの聴覚障害は、出生１,０００人あたりで１人から２人と報告されていまして、ほかの先天性の病気よりも出現率が高くなっています。現在、品川区では、区民の出産に関して出産場所や施設についてのデータなどをお持ちでしょうか、確認させてください。","respondent":"太田品川保健センター所長","answer":"出産場所については、４カ月健診および、すくすく赤ちゃん訪問で確認しております。この間も、６月から７月にかけて４カ月健診を受診した方に対して、出産場所についてのアンケート調査を行っておりまして、区内での出産が三、四割ということがわかっております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"区内で３割から４割ということですけれども、全出生の半分も区内で行われていないという状況だと、新生児聴覚検査は品川区だけで対応できる問題ではないということだと思います。新生児聴覚検査の公的な実施は、東京都全体とか日本全体で課題になると思われるのですけれども、品川区から都のほうに強く働きかけを行っていただきたいと思うのですけれども、こういったことのお考えをお聞かせください。","respondent":"川島健康課長","answer":"今、委員ご指摘のとおり、特別区だけということではなくて、まず都内全域でできるように、保健衛生部長会においての検討が今始まったところですので、我々もそちらで積極的に意見を発信するとともに、その推移を見守って。","voiceIndex":12,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"現在、母子手帳の記載だと、８割以上の健診受診者は聴覚検査を受けているとなっているそうです。４カ月健診時に問診で子どもの聴力チェックを行っているということはわかっていますけれど、軽度難聴はこの程度の検査では見逃される可能性があるということで、新生児聴覚検査が行われなかった子どもに対して、現在、品川区ではどのように対応されているのか教えていただければと思います。","respondent":"太田品川保健センター所長","answer":"もし入院中に検査を希望しなかったという方につきましては、生後２カ月までであれば、東芝病院のほうで、ＯＡＥの検査ですが、行ってくださるということを確認しております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"今、品川区の１歳未満の聴覚障害児の数と、その療育支援についてどのようなことを行っているのかをお聞かせください。この間の親に寄り添って精神的負担を和らげて、正確な知識を提供して子育て全般を支えるしっかりとした支援が必要だと思うのですけれども、品川区は現在どのような体制で聴覚障害児の支援を行っているのか、その概要をお聞かせください。","respondent":"中山障害者福祉課長","answer":"補聴器については、ある一定の年齢がいかないとなかなか、つけた後の可否というのもわからないので、生まれたばかりのお子さんに対しての支援というところでは、現在できていないところです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"聴覚障害児へのしっかりとした公的な支援体制を、数をちゃんと聞いていなかったのですが、それも後でお答えいただければと思います。それと、ちょっともう時間がなくなってしまうので、１歳児未満の数だけ後で教えていただければと思います。やはり地域ごとに大分やり方に違いが出てきているのかと思うのですけれど、その状況について一言お聞かせください。","respondent":"太田品川保健センター所長、小林品川区清掃事務所長","answer":"新生児聴覚スクリーニングで、精密検査が必要となる方は０.４％ということですので、品川区では年間３人から７人いらっしゃるということになると思います。しかしながら、近年、住戸の建替え等によって、集積所の確保が大変困難になってきておりまして、結果的に、やむを得ず、各戸に近いようなグループごとの収集等をせざるを得ない状況になっておりますが、これにつきましては。","voiceIndex":20,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"資源ごみのことは、今、地域によって大分そういう意味ではばらつきが出てきていると思うので、資源ステーション、そしてまた各戸回収でやるという、どちらにしろしっかりとした体制でやっていただきたいと思います。ちょっと時間がないので、また今度聞こうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"国と地方自治体の公費負担の部分については、そのうち１５兆８,５２５億円ということでありました。こうした状況を受けて、財務省の財政制度等審議会で医療費の抑制策も提案されるという全国的な事態というところであります。そこで、「私の散歩道」の改訂、またウォーキングマップアプリが、どの程度、区民の皆さんの健康づくりに貢献しているか教えてください。","respondent":"川島健康課長","answer":"今、委員からご紹介いただきました「私の散歩道」を改訂いたしまして、現在、平成２８年度、６４８冊購入いただきました。それから、あわせましてウォーキングマップのアプリも公開しておりますが、こちらも大変好評でして、７,８３３件のダウンロードをしていただいております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"これは全国的な数ですけれど、いわゆる健康に対する無関心層が６割とか７割という中で、３８万人の区民がいる中で７,８００人、こうした取組みについては多いほうということで、今、ご答弁がありましたけれども、さらに推進をお願いしたいと思いますが、まさに「私の散歩道」、それからウォーキングマップアプリ、こうしたものを連動させて、厚生労働省としても医療費抑制につながるとして推奨されている。","respondent":"川島健康課長","answer":"あわせて、ウォーキングイベントなどをやっても、１日例えば１万歩を歩いたりなどという途方もない歩数を、景品というか特典欲しさに歩く方がいるなどというところをどうするかというところの課題もあるようなお話も聞いたのですけれども。","voiceIndex":27,"id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"今ご答弁の中でいろいろ出てきた、筑波大学だったり久野教授の名前だったり、私もかつて繰り返し一般質問等で、視察させていただいたところを引用して提案させていただいたところです。私は今、４１歳なのですが本当にショッキングな疲労度の結果が出る。次にいきます。こういう傾向が見られるということでありますが、品川区としてのこうした数字がわかるものでしょうか、教えてください。","respondent":"山崎商業・ものづくり課長","answer":"それで、中小企業支援の特性としまして、２０人以下の小規模事業者の方々を対象にする事業が非常に多くて、大手の企業でありましたら、いろいろ育児関係の法的なもので義務化で対応しているような状況があります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"私もこれを見まして、佐賀県、宮崎県、山口県の知事の方が妊婦ジャケットを着て、庁舎内やまちを歩いて家事をする動画が９月末から公開され、既にもう再生が１２万回を超えたということで、このキャンペーンで妊婦体験をした男性の９６.７％の方が、男性も家事や育児をするべきだと思ったと回答されているほか、家事や育児をすると仕事にも効率的であるとの結果、この辺については。","respondent":"山崎商業・ものづくり課長","answer":"そうした中小企業に向けて、出産補助制度などを通じながら、先ほど例示された、トップの経営者の方みずからその必要性を感じて社員の方にＰＲしていくように、経営者の方々とやりとりをしながら、強力に意識啓発に努めている、あるいは努めてまいりたいと考えているものです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"いずれにしても、そういう理解ということです。次に、産業経済費全般というところでありますが、総合戦略の策定に際しても活用されたとは思っておりますが、地域経済分析システム、いわゆるＲＥＳＡＳを、産業経済振興としてどのように活用されているか教えてください。","respondent":"柏原企画調整課長","answer":"民間のほうにも一部、開放しているというところがありますので、そういったところまで、所管のほうが周知してもらいながら活用していくといった状況があります。","voiceIndex":33,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に１点確認で、出産・子育て応援事業というところで、今まさに厚生委員会で、補正予算で先日審議されて、全会一致で可決された、病院を活用しての産後ケアということでありますが、今回、自己負担額が１万円ということで、まずはモデルの取組みとして、来年度以降、本格実施ということでされておりますが、この自己負担の部分、さまざま先行してやっている、都心部で言うとこのぐらいなのかと思う中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"中塚委員","kind":"提案","question":"１５５ページの商店街活性化事業費と、１５４ページの若者・女性就業支援事業について、店舗・商店リニューアル工事への支援と、商店街のイベント告知チラシ、就業支援のＰＲについてそれぞれ伺いたいと思います。個人の店舗に対してリニューアル工事への助成制度をぜひ実施していただきたいと思いますけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"そうした制度の活用とともに、それから住宅と店舗が併用しているような場合は、まちづくり所管の住宅部門と連携しながら、そうした最適な補助制度であり融資の利用というようなことをもって対応してまいりたいと考えているものです。","voiceIndex":37,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば県レベルでは高知県、市区町村では１１自治体で、２３区では荒川区と江東区、検討中は約２０自治体ということです。どこでも地域の活性化につながり、住民にも来訪者にも、また景気対策としても、結果として税収アップにもつながる事業です。こうした、実施している自治体について、品川区でも調査・把握していただきたいと思うのですけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"それから２０１５年の緊急の交付金につきましては、品川区としましては、プレミアム商品券の発行という手法で、消費喚起と商店街支援ということで選択して実施してきたです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味では、積極的な誘導という視点が必要だと思いますので、改めて実施についてお考えを伺いたいと思います。何とかしてほしいとの相談がありました。こうした事例があるのか、またこの声は届いているのか確認したいのと、やはり主として補助事業の告知チラシですけれども、ある程度の面積案分を決めて、次回の告知などを認めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"冒頭の関係につきましては、区としましても、商店街につきましては、地域の身近なインフラであり、活力を醸成するもとになるものという認識のもと、しっかりとした支援メニューを考えてまいりたいです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"商店街の方にお話を伺うと、ぜひ、イベントに来ていただいた方を次回のリピーターにつなげたい。それが１つと、東京都に対して改善してほしいと要望しているのか、そこを確認させていただきたいと思います。ぜひ東京都に要望していただきたいのと、緊急対策として、都が減らす分を、例えば区の一般財源の上乗せで、緊急に改善することができないかと。こうしたことはできないのか、伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今後もそうした視点で、東京都とのやりとりと、区の制度の見直しは、継続的に続けてまいりたいと考えているところです。","voiceIndex":43,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"もって東京都が認めないということが、とてもけしからん話だとも思いますので、品川区としても要望しているということなので、ぜひ強く要望していただきたいのと、一方で緊急対策として、その分を区として、案分で減る分を一般財源の上乗せとして緊急対策することができないのかと、その点を改めて求めたいと思うのですけれども、ご答弁いただきたいと思います。","respondent":"山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"区としては、補助金の二重の支出もなかなか難しい問題もありますので、ちょっと検討課題にして、いろいろ東京都とやりとりをしてまいりたいとは考えているところです。おっしゃられたとおり、いろんな形でＰＲしまして、少しでも多くの方に不安なくご利用いただけるような形で、いろいろ工夫してまいりたいと考えています。","voiceIndex":45,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"私はぜひ、例えば正規雇用につながった体験例を紹介するパンフレットや、ご両親向けの事業説明会や相談会、何か希望が感じられるような工夫がとても大事ではないかと思いますので、ぜひご検討いただけたらと思いますけれど、いかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"例えばホームページで紹介するとか、そういったことも含めていろいろ検討してまいりたいと思います。","voiceIndex":48,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"質問する順番は変わると思いますが、よろしくお願いいたします。この８１５件の内訳について教えてください。道路などで発見された場合は無料で行っていると思います。ペットが亡くなってしまって依頼すると、一律で２,６００円、料金等かかってくると把握しておりますが、道路などで発見された場合の引き取り料はどこが補填しているのか伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"その取扱いなのですけれども、道路等の場合、道路管理者の負担となりますが、国道については国道管理事務所でみずから収集して対応しています。","voiceIndex":51,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほどお答えしていただいた内訳にあります、道路上や公園などで発見した場合に、ちょっと詳しく教えていただきたいのですが、どのように対応されているのか伺いたいと思います。それは、最近は動物を虐待するニュースというのはあまり見られなくなってきていると思いますが、そうした動物たちは今までいたのでしょうか、伺います。","respondent":"小林品川区清掃事務所長","answer":"中には、飼い猫が道路で変死したような場合に、熱心な飼い主はそれを捜して、「何かそういうのがありませんか」というお問い合わせが時々あるものですから、色・大きさのほか、首輪等の識別するものがあれば、それも含めて全て記録して対応し。","voiceIndex":53,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"続きまして、１５０ページのボトルキャップ回収運動について伺いたいと思います。その理由について伺いたいと思います。この回収運動についてですが、品川区のホームページには、「区は、率先して環境活動に取り組むため」という、いろいろ文章があるのですけれども、このボトルキャップは何に使われていくのか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"そちらのボトルキャップを色分けにしたものをリサイクルプラント、運送業者などに持っていっていただきまして、そちらに関してはリサイクル業者が、例えば、プラスチック溶剤の製品に利用しております。","voiceIndex":55,"id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"それで、１年半前からそういったワクチン代として寄附されていなかったということを受けて、いろんな学校や会社、団体というのが、そういったボトルキャップの回収を中止しているということでありました。今後についてですが、品川区の平成２８年度の予算では見当たらなかったのですが、そのことについて今後どのように行われていくのか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"平成２８年度予算が計上されていないと申しますのは、実はこのボトルキャップ回収運動につきまして、先ほど申し上げたように、ボックスの回収代となっておりまして、今現在、必要なボックスについては全部賄えております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"理解できました。次に、１４５ページの公衆便所費について伺いたいと思います。ちょっと、公衆便所と言いづらいので、公衆トイレと呼ばせていただきますけれども、まず品川区内には３６カ所に公衆トイレがあると思います。この公衆トイレの清掃管理について、どのような方が清掃して、またどのぐらいのペースでトイレを掃除されているのか伺いたいと思います。","respondent":"溝口公園課長","answer":"区内の公衆トイレについてのご質問に答えします。区内には３６カ所トイレがありまして、清掃につきましては、毎日、最低でも１回の清掃、また大井町駅など駅周辺につきましては１日２回の清掃を行っているものです。","voiceIndex":59,"id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"今、毎日清掃されているとお聞きしましたけれども、もしよければ、清掃される時間帯、例えば朝やってもうそれ以上やらないとか、朝・夕方、２回やるとか、そういうのがわかりましたら教えていただきたいと思います。そこで、少し費用はかかると思いますが、消臭剤や、またトイレボールの活用をお願いしたいと思うのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"ですから、まずは清掃をしっかりやっていく。は利用者のマナーの向上に努めていくといったことをやることによって、誰もが利用しやすいトイレ環境をつくっていくというふうに考えているものです。","voiceIndex":61,"id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"ちょっと私からも最後に公衆トイレについて言わせていただきますが、誰もが１日に何度でも行く場所であると思います。最後ですが、１４９ページの環境調査測定費の航空機騒音調査について伺いたいと思います。５８万２,１２０円の内訳について伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"航空機騒音調査につきましては、平成２７年度には、どのあたりが一番、測定地点としていいのかどうか、業者委託して測定地点の調査を行いました。","voiceIndex":63,"id":"exchange-028"},{"speaker":"松永委員","kind":"確認","question":"場所を確認しただけということでよろしいのですか。それで、このような形で金額が出ておりますけれども、調査結果で、例えば調査する場所等、もう決まったのか、それとも箇所数も決まったのか教えてください。今後、本年度予算でも６６０万円とついているので、もしかしたら、もうそういった場所は決められたのか、あわせて伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"したがいまして、来年度の予算につきましても、どのあたりがいいのか、一応考えてはおりますけれども、例えば庁舎の地点がいいとか、そのようなことを考えておりますので、一応調査はしております。","voiceIndex":65,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"観光アクションプラン推進事業についてお伺いいたします。特にオリンピック・パラリンピックに向けての大きな事業は、いきなり行うよりは、早目に段階的に行うべきと考えております。例えば、１５年前、２００１年に、東海道４００年祭という一大イベントがありました。再びあのような、品川区全域のおみこしを集結した一大パレードを企画するべきかと思われますが、区のご見解はいかがでしょうか。","respondent":"鈴木文化観光課長","answer":"ご質問にありました４００年祭のような、区全体を挙げたパレードのようなイベントですが、機運醸成に向けて非常に効果があるのではないかという考えがありまして、区としてもただいま具体的なプログラムの検討に入ったところです。","voiceIndex":68,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"例えば１５年前は旧東海道でパレードを行いましたけれども、同じ「道」ということで、次は私も非常に期待する、３年後に開通予定の２６号線、まさに懸案だった品川区の東西の交通ライン、品川東西回路を記念して同時に行うことなどもあってよいかと思いますので、こうしたこともぜひとも検討に入れていただいて、事業を前向きに進めていただきたいと考えております。この２点、お伺いいたします。","respondent":"立木産業活性化担当課長","answer":"各創業支援施設に入居している方の区民率なのですけれども、こちらはちょっと統計をとっておりませんので今はわかりかねますが、退去後の区内定着率に関しましては、例えば武蔵小山創業支援センターを退去した方が、これまで２１人いた中では１２人の方が区内定着ということで。","voiceIndex":70,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"区への地域貢献をしていただく。それで、例えばこの施設に入居する段階、入居中の段階、そして退去後の段階の３段階で考えていただいて、入居する際は品川区民だったら優先的に入居させる。区内産業との連携、そして地域に貢献していただく活動を行っていただくなどの縛りというか、そうしたことをやっていただくような仕組みづくりが必要だと考えておりますけれども、この点を品川区はどうお考えでしょうか。","respondent":"立木産業活性化担当課長","answer":"そういった中では、今後もそういった部分、いろいろバランスをとりながら、しっかりと基準等、それから優遇措置についても、固定ということではなく、いろいろ柔軟に検討は、これからもデータをとりながら進めてまいりたいと考えております。","voiceIndex":72,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"広町、西大井あたりは製造業だったのですけれども、一番最新の施設、ＳＨＩＰに至っては、ＩＴやサービス業の方向けにつくられていると感じておりますけれども、今後もそうした時代に合わせた施設を展開していくのかどうかという点と、やはりもうそろそろ、いつまでも製造業というのではないだろうということで、一番旧い施設、広町や、次に旧い西大井などの施設を、また今の時代に合った。","respondent":"立木産業活性化担当課長","answer":"そういったところをしっかり見きわめながら、今後の施設運営の検討をしてまいりたいと思います。","voiceIndex":74,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひともそれぞれの時代に合わせた、施設づくり、産業・ものづくりを進めていっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"最初に、１４３ページの予防費の予防接種費から伺います。それで、予防接種法の改正にのっとった副反応を防ぐための予診は実際にどのように行われているのか、把握していらっしゃるのでしょうか、教えてください。それから副反応の可能性については、どのような情報提供が保護者になされているのでしょうか。","respondent":"舟木保健予防課長","answer":"予防接種について、２カ月の方が受けることということで説明ということで、『予防接種と子どもの健康』の中にも該当するページに、ワクチンの有効性とか、なぜ必要なのかとか、副反応についてとか、そういうことが書いてありますので。","voiceIndex":78,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"問診票と、この小冊子も大変詳しく書かれているということは拝見してわかりました。そこまでの情報も、今おっしゃったアプリなどを見るとわかるのでしょうか。何かもう少し丁寧な予診というのがあってもいいのかなと思ったのですが、その辺はいかがでしょうか。","respondent":"舟木保健予防課長","answer":"そのような形でさらに周知するとともに、新しく始まった際には、そういう点を含めて、やっていただく先生方にも周知させていただいているところです。","voiceIndex":80,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"それで、ＨＰＶの問診票に、２カ月のお子さん向けではないのでいただかなかったのですけれど、例えばパン酵母アレルギーについて書かれているのでしょうか。探すのが難しかったのは、私が検索が下手だからと言われたらそれまでなのですけれども、その辺の情報提供はどうなのでしょうか。","respondent":"舟木保健予防課長","answer":"そのような形であれば、「医師とよく相談した上で」とか、そのような形で記載されております。","voiceIndex":82,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"いろいろ対策されていることがわかりました。アレルギーについては、２０１５年１２月にアレルギー疾患対策基本法が施行されて、それに先立つ１２月２日には厚生労働省健康局長から通知が来ています。予防接種の現場でも、一層のアレルギーについての認識を持つべきと思うのですけれども、法施行後、何か強化したところとか、そういうことがあれば教えてください。","respondent":"舟木保健予防課長","answer":"この法の施行後、強化したかどうかは定かではありませんが、常日頃より、予防接種を実施するにあたっては、接種を受ける方あるいはその保護者に対して、予防接種の有効性と安全性、あと副反応について、受けられる方の理解をあらかじめ得るよう周知工夫等はしているところで。","voiceIndex":84,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"私はやはり本来、保護者のほうがちゃんと、不安に思ったら、わからないことがあったら、積極的に情報を求めるべきだと思っています。年１０カ所というのはどういう趣旨なのでしょうか。例えば２０１５年度の予算立ては１,２００万円弱あったわけですから、広げるという方向であれば、もう一カ所つけるということも考えられたのではないかと思うのですが、その辺はいかがでしょう。","respondent":"和田河川下水道課長、舟木保健予防課長","answer":"それから区有施設のタンクの予算が減っているではないかというお話、それから１０件というのはどういうことかということなのですけれども、実は区有施設への雨水利用タンクの設置につきましては平成１８年度からやっておりまして。区はこれまでも、予防接種の有効性・安全性、あと副反応等については、注意事項等について周知しておりますが、引き続き、受けられる方、あと保護者が正しい知識を持って。","voiceIndex":86,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"それで、３月の予算特別委員会でも質問しているのですが、「子連れで相談に来る人向けに託児ができないか」という質問に対して、「中小企業センターに託児室があるが、人の手当てが課題」ということで、研究課題というご答弁でした。その後のご検討をいただけたでしょうか。子どもを預けたい人だけ予約制にして、そのときだけ人の手当てをするということは考えられないでしょうか。お答えください。","respondent":"立木産業活性化担当課長","answer":"利用団体のほうにも、託児室があるというようなことで、ご利用の案内等はさせていただいているのですけれども、そういったことで、また引き続き、あそこの相談だけでなく、いろいろな部分で検討してまいりたいと考えています。","voiceIndex":89,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ検討を進めてください。それから、託児室なのですけれども、ホームページの施設案内に出ていないのですけれども、ぜひその辺の広報もお願いしたいと思います。要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私からは、成果報告書１４９ページ、水質調査についてお伺いいたします。この水質調査、１１カ所と記載してありますけれども、これは具体的に場所と水質調査、さまざまな調査をしていると思うのですけれども、どういう調査をしているのかお知らせください。","respondent":"三ツ橋環境課長","answer":"水質調査につきましては１１地点ですけれども、目黒川関係が６地点、また立会川関係が５地点です。目黒川の６地点ですが、市場橋、居木橋、そして昭和橋、そして新東海橋、東品川橋、八潮二丁目となっています。","voiceIndex":93,"id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"意見","question":"この水質調査によって、汚染されている、されていないといったような調査だと思うのですけれども、今後、４年後に向けて、東京オリンピック・パラリンピックがあります。これは当然、東京湾、そして京浜運河につながる河川だと思うのですけれども、より水質改善とか、これは都との連携も今後あると思うのですけれども、その辺の水質の改善といったことも今後調査として取り組んでいくのかお知らせください。","respondent":"和田河川下水道課長","answer":"これだけだと抜本的な水質改善にはなりませんので、基本的にはやはり目黒川の上流側の合流改善を東京都に強く求めていくことしかできないわけなのですけれども、濱野区長が会長をしております下水道促進連盟で、毎年、合流改善の推進について強く要望しておりますので。","voiceIndex":95,"id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういう意味で、ある程度、今でも生き物がいるという中で、本当に区長にこれからも要望していただきまして、東京オリンピック・パラリンピック、４年後に向けて、京浜運河、それだけではないですけれども、舟運事業、これはまた別の話になると思うのですけれども、舟運に関して、それにはやはり来訪される方の、水質、透明度、そこまで透明になるとは私も言えませんけれども。","respondent":"三ツ橋環境課長","answer":"こちらは吹きつけアスベストに関してのみです。一方、除去助成につきましては、解体に伴う除去の助成をしております。","voiceIndex":97,"id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"意見","question":"このアスベスト対策助成事業を拝見しますと、助成金額、それぞれアスベスト調査の上限が２５万円、アスベスト除去が３００万円上限になっています。助成の件数が先着順となっておりますけれども、調査５件、除去が３件。本年の４月１日から来年度の１月１０日までが申込期間になっておりますけれども、今現在どの程度申し込みがあるのかお知らせください。","respondent":"三ツ橋環境課長","answer":"今現在のアスベスト調査助成、また除去助成の申請件数ですけれども、除去助成につきましては１件ございまして、調査助成につきましてはまだ来ておりません。","voiceIndex":99,"id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これは区内の一戸建ての住宅も含めてということですよね。ここの環境指導相談費の中の環境相談の中で、アスベスト相談が９５件あります。これは建築業者が主だと思うのですが、そういった９５件の中に業者も含まれているのかお知らせください。","respondent":"三ツ橋環境課長","answer":"しかしながら、委員ご指摘のとおり、業者からのご相談もございまして、例えば業者が、実際に自分たちが調査に当たる場合はどのような業者がいいのか、ご相談もあります。","voiceIndex":101,"id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これは工事の職人も、住宅の中の壁内に断熱材というのがあるのですけれども、そこが一部クラックが入って剥がれてしまうと、やはり粉じんが入りまして、結構、アレルギーを持っておられる方はひどく腫れてしまったり、今現在もそういうのがあります。そういった相談というのはありませんか。","respondent":"三ツ橋環境課長、川島健康課長","answer":"アスベストに関しましては、数十年後に中皮腫や肺がんになる可能性がありますので、そちらのご相談につきましては、実際に東京都であったり、また公害補償関係であったりになってあります。平成２５年度が４件、平成２６年度が３件、平成２７年度は０件でした。それから申請も、年に１件、２件あるかないかというような少ない状態になってあります。","voiceIndex":103,"id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今、私が申し上げたのは断熱材、グラスウールという素材があります。それはまた今後、環境課と、当然、建築部門も入ると思うのですが、保健センターを絡めて連携して、今後また取り組んでいただきたいと思います。続きまして１４５ページ、そ族昆虫防除対策費についてお伺いいたします。本年のジカ熱などの感染症の対策に向けた蚊の防除について、この取組みをお知らせいただきたいと思います。","respondent":"井浦生活衛生課長","answer":"ジカ熱に対する蚊の防除事業です。平成２７年度から実施してございまして、平成２６年度にデング熱が都内で発生したということを踏まえまして、品川区としまして、蚊が発生しないような対策を講じているものです。","voiceIndex":106,"id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今、巡回予定数が年間、当然、冬の期間は、冬の期間もあるのかな、４巡回。実施状況が５月から１０月ということなので、まだ１０月の半ば前なので、まだ実施しているということでよろしいのでしょうか。","respondent":"井浦生活衛生課長","answer":"５月から１０月にかけまして、区内の３万４,０００カ所を４回回るという計画です。現在、最終回で巡視しています。","voiceIndex":108,"id":"exchange-049"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうしますと、これは区内全域の公道ということで解釈してよろしいのでしょうか。","respondent":"井浦生活衛生課長","answer":"区内全域の公道でございまして、区道、都道、国道について行っているところです。","voiceIndex":110,"id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは実は品川区が一生懸命、こういう目的で対策を講じてやっているということで、伝わっているところ、伝わっていないところ、もっとこれは報道を絡めたいろいろ取組みを啓発していただいたほうが、必ずこれは区のよろしいことだと思うので、ぜひそれをやっていただきたいと思います。来年度もこの取組みはやっていくのでしょうか。その辺の今後の予定についてお知らせいただきたいと思います。","respondent":"井浦生活衛生課長","answer":"こちらの防除の取組みにつきましては、まず啓発ということで広報紙、さらにホームページにもトレンドな内容でアップしてございまして、引き続きＰＲ、広報に努めてまいりたいと考えています。","voiceIndex":112,"id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは散布ではないですか。やっていただいている方は、区の職員の方と解釈してよろしいのでしょうか。お知らせください。","respondent":"井浦生活衛生課長","answer":"事業受託で実施してございまして、委託の経費が年間８４６万７,０００円余です。","voiceIndex":114,"id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"私からは３点お伺いいたします。１５６ページ、プレミアム付区内共通商品券発行助成についてお伺いいたします。がん検診の肺がん予防についてですが、この６月の一般質問でも取り上げましたが、「肺がん予防の取組みとして、禁煙外来マップの作成をする」というご答弁がありましたので、作成状況およびどういう仕様なのかということをお伺いしたいと思います。","respondent":"川島健康課長","answer":"禁煙外来マップのお尋ねです。こちら、今はもう最終校正も終わりまして、もうそろそろ印刷に入れるということで、１１月ぐらいにはお配りできるだろうということで、まず２,０００部の配布の予定です。","voiceIndex":117,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問","question":"６２カ所あるということです。禁煙外来マップが活用されて、しっかりと禁煙が進むといいかなと考えていますが、このマップの活用のされ方、禁煙外来に行ったとか、また禁煙に成功したとか、この結果というのはどのように把握されるのでしょうか。","respondent":"川島健康課長","answer":"結果の把握のほうは、私ども、そこまで追っていくような段階にはまだないのですけれども、これから少し、何か区でできる支援があるかないかというところも含めて検討するということ、それから国保医療年金課におきましても。","voiceIndex":119,"id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"公衆便所についてお伺いいたします。平成２８年度の『しながわの公園』によりますと、公衆便所３６、公園便所１０６、児童遊園便所２０、１６２カ所となっております。そこをちょっと確認したいのですけれども、今後の品川区の公衆便所のあり方についてのお考え、方向性をお伺いしたいと思います。","respondent":"溝口公園課長","answer":"そういった中で、数多くありますので、一挙に改修する、または新しくするというのは、なかなか難しいところでありますが、観光の視点、または今後、オリンピックが開催されますので、そこまでのアクセスルートといったところも含めて。","voiceIndex":121,"id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、１つ公園の中で言われているのが、新浜川公園、浜川砲台ができたところの公園の近くの住民の方が、風向きや天気によっては非常にやはり、においがきついということで、位置を変えてもらいたいという声が非常に出ておりまして、ここは花海道の整備と、またポンプの整備も進んでいるところですけれども、今後、公園の整備等含めて、ここの改修が進められるのかということを確認します。","respondent":"溝口公園課長","answer":"今後もさまざまな先行的な事例、または公的整備、また利用者の声といったものを総合的に判断しながら、税外収入という観点もありますので、どういう形で今後トイレを維持管理していくのかというのをしっかり検討していきたいと考えているものです。","voiceIndex":123,"id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"来たくなるトイレという観点で整備を進めていただきたいと思います。そして商品券についてお伺いいたします。今回、チラシには、「今回は」と書いてありまして、「今回から変わります」ではなくて「今回は」という表示になっているので、もしかしたらこれは今回だけなのか、また戻ることもあるのか、ちょっと含みがあると思ったので確認させていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"それで、プレミアム商品券は少し加熱ぎみになっておりまして、いろいろ、直接販売方法ですと列ができたりというようなことを回避するために今回採用したもので、事前申込みの今回の方式を、またいろいろ改善で変えていくことはありますが、基本的にはこの申込制を維持したいと。","voiceIndex":125,"id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"公平性も保たれてきているかと思います。今後は、これは商店街活性化のための商品券ですけれども、例えば角度をつけた、子育て世帯に優先ですとか、多子世帯優先ですとか、高齢者優先ですとか、さまざま、今回、販売方法が変わったということで、いろんな取組みが考えられるかと思いますので、今後そのようなこともぜひご検討いただきたいということを要望して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１４４ページの成人歯科健診、そして３５歳からの健康診査に関連して２０歳からの健康診査も伺います。それと女性の健康診査について、それぞれ絡めて伺いたいと思います。４０歳から５歳刻みで７０歳まで行われているのが成人歯科健診ですけれども、私も議員になってからずっと年齢拡大を求め続けてきました。「具体的に検討」とは、中身は何か、どんな検討がされているのか伺います。","respondent":"川島健康課長","answer":"今までは確かに４０歳以上、リスクが急に高まるというところに重点的にという答弁をさせていただいていたのですが、どういうふうに考え方が変わったのかというところに関しましては、まず１つは２０歳からの健診を導入したということ。","voiceIndex":130,"id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"提案","question":"それで、通知を送る対象なのですが、こういったところもまだ検討の中身には入ってきていないということなのですかね。ぜひそこで提案させていただきたいのですけれども、二十歳からの健康診査は、健康診断の機会のない人が対象です。そして、改めて、２０歳の健康診査と一緒に成人歯科健診も２０歳からということを求めますけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"具体的な検討の中身につきましては、これからというところですが、年齢を引き下げる検討に入ったという段階になります。ですので、細かな、どの年齢を対象にするのかなどという話になってきますと、これからの検討になるです。","voiceIndex":132,"id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"年齢を拡大していく、開始年齢を引き下げていくということですけれども、今までのように５歳刻みなどではなく、毎年診断が受けられるようにしていただきたいと思いますけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"毎年ということになりますと、その上の年代、今の４０歳以上の方の年代の健診ともかかわってくるので、なかなか難しいのではないかです。","voiceIndex":134,"id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私も、４０歳からの成人歯科健診だったときも、なぜ５歳刻みなのかと。それで、その根拠を伺うと、国が１０歳刻みなので、区は５歳刻みで、国よりもよくやっているのだというような答弁をずっとされてきているのですけれども、やはり各年代で口腔内のステージが違いますので、ぜひ毎年やっていただきたい。そして、開始年齢の引き下げをした際に、同時に毎年の健診をぜひお願いしたいのです。","respondent":"川島健康課長","answer":"現在、成人歯科健診、４０歳以上、５歳刻みということですが、今、委員がおっしゃったとおり、１０歳刻みの補助金しか出ない部分を、区が５歳刻みに持ち出ししてやっているというところで、よくできた制度設計だと考えていますので。","voiceIndex":136,"id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、そこからまた５歳刻みというのは、私は逆戻りではないかと思いますので、ぜひ２０歳から、そして毎年お願いしたいと強く求めたいと思います。そして、次に女性の健康診査です。ですけれど、平成２８年から平成３０年は、１６歳から１９歳の女性区民も２０歳からの健康診査で対応できるようにしていくと書いてあったのですけれども、平成３０年以降はどうなるのか伺います。","respondent":"川島健康課長","answer":"それで、平成３０年度までは激変緩和策ということで、２０歳からとするような予定でおります。それから１９歳以下の方、今年の数字なのですが、今年は１３人ほど受診されております。それから平成２７年度が５１人ということです。１,２３９人中５１人が受診されております。","voiceIndex":138,"id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それから１６歳から１９歳のところでは５１人もいるというところでは、継続させていくべきではないかと思うのです。そうすると、女性の健診を１６歳から継続させていくということは、２０歳からの健康診査も１６歳から始めたらどうかと思うのです。中学を卒業して進学せずに受診の機会のない若者もまだまだいます。ですので、さらに拡大していくということを求めますけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"確かに生活習慣病の弱年齢化と言われていまして、自治体によっては小学生の健診をするようなところも出てきているところは確かではありますが、幾ら何でも１０代の方というのはまだまだというところで、２０歳からの健康診査ということではありますので。","voiceIndex":140,"id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"提案","question":"学校にいれば健診の機会はあるわけです。ぜひそこを改めてお願いしたいと思います。それと、また先日の一般質問のところで、２０歳からの健康診査に麻しん・風しんの抗体検査を加えてはどうかといったことが提案されていました。私もそうするべきだと思うのです。検査コストの面からも難しい」と答弁されているのですけれども、具体的にどういうことなのかを伺いたいと思います。","respondent":"川島健康課長","answer":"それで、具体的には、２０歳からの健康診査のお知らせの中に、「先天性風しん症候群対策として、風しん抗体検査予防接種の費用助成を受けられる場合がありますので、ご相談ください」という文言を入れしています。","voiceIndex":142,"id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういう紹介を入れているのでしたら、一緒に検査ができるというようなことでいいのではないかと思うのです。２０歳からの健康診査に入れるということは、単価が上がるということですけれども、どれぐらい上がってしまうのか伺いたいと思います。","respondent":"川島健康課長","answer":"単価が上がるというか、同時に受診はできるのですけれども、全ての医療機関でできるわけではないということなので、これを２０歳からの健康診査と一緒の検査項目にそもそも加えてしまうということは無理だという話で答弁させていただきましたので、「こういう仕組みがあるので。","voiceIndex":144,"id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"意見","question":"ぜひ、２０歳からの健康診査に来た方が、全ての医療機関で、２０歳の健康診査ができる機関で一緒にできるようにしていくことが、さらなる予防につながっていくと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":146,"id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、１４４ページ、健康診査、１５１ページ、清掃費、それから１５６ページのバンコクビジネスサポートセンターについてお伺いしたいと思います。こういったことを品川区でも、これまでも要望が出ていたと思うのですけれども、現在の検討状況について教えてください。今年はまだ年度途中、過去３年程度で結構ですので、火災の件数と原因、対策について簡単に教えてください。","respondent":"川島健康課長、小林品川区清掃事務所長、立木産業活性化担当課長","answer":"視力というのが大変重要な感覚になると私どもも認識しておりますので、どのような形でやるのがいいのか。その対策ですが、原因が主にガスコンロのスプレー缶でございまして、これを収集時に圧縮することによって発火の原因になっているのが一番多いものですから。今までは例えばタイのＭＥＴＡＬＥＸへの展示ですとか、そういったものに区がまとまって行くというような形でやっていたものですけれども。","voiceIndex":148,"id":"exchange-068"},{"speaker":"あべ委員","kind":"質問・要望","question":"区民の方が「かわいそうではないか」というような声が出ないような職場環境にしていただきたいと思いますので、それについての意識、お考えをお伺いしたいと思います。今の形で続いていくことがいいのか、一定の役割は果たしたのかもしれませんけれども、このまま区が公金を出すやり方としては、私はちょっとイレギュラーな時期が続いているのではないかと思いますが、いかがでしょうか。","respondent":"立木産業活性化担当課長、小林品川区清掃事務所長","answer":"タイのサポートセンターですけれども、先ほど申し上げましたとおり、これから、ＪＥＴＲＯで用意しているメニューの利用助成など、汎用的なメニューを増やして、より柔軟に海外進出のサポートをしていくという方向では、撤退も含めて。労働環境につきましては、安全衛生委員会で現場の声を取り入れながら進めてまいります。","voiceIndex":152,"id":"exchange-069"},{"speaker":"あべ委員","kind":"意見","question":"啓発をホームページに書いても、見たい人しか見ないですし、推進員の方々は頑張っていらっしゃいますけれども、やはり、ごみを出すのは全員なのです。区民全体から出てくるわけで、なかなか推進員の方がアプローチできる範囲というのは、極めて限られていると私は思います。もっと強く、これはアピールしてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"１５５ページの中小企業対策費の中の融資あっ旋のところです。それと、１５７ページはビジネス・カタリストについて伺うのですけれど、融資あっ旋は、毎年、予算書では、今回、平成２７年度予算書で、信用保証料の補助が２億６,７００万円。でもって決算書のほうですと１億５,２００万円ということで、乖離が。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、例えばこの時期ですと年末にかけて、通常は融資需要が増えてくるような関係もあったりしまして、年度内に景気が急に悪くなるようなことへの備えも含めて、予算立てをしているというようなことです。","voiceIndex":157,"id":"exchange-071"},{"speaker":"渡部委員","kind":"質問","question":"２割ぐらいは紹介状が発行されても実行されないということなのかと思うのですが、やはりそれは、いわゆる会社の企業体力の問題等があって、なかなか実行できないのか、紹介数と実行数の約２割の乖離というのは、どういうふうに見たらいいのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"一定程度、融資ですので、審査という過程があります。そうした中で、ちょっと残念ながら融資制度を活用できないという数字もありますが、ここの乖離の一番大きな部分は、品川区であっ旋を銀行に出します。","voiceIndex":159,"id":"exchange-072"},{"speaker":"渡部委員","kind":"質問","question":"安心いたしました。前にちょっとご質問させていただいた借換え等の需要に関しましても、こういうときは借り換えられますよというのも書かれていますし、これ１冊あれば、本当に便利だなと。融資のご相談があるのだったら、これを見て考えてください」と言うだけでも、結構いい形に仕上がっていると思ったのですが、何かその辺、ほかに参考された資料等があったのか、どうなのかと、あわせてお願いします。","respondent":"山崎商業・ものづくり課長","answer":"こうしたことも２３区の中では品川区だけです。そういう意味で、敏感にいろんな情報をキャッチして、企業の皆様に使っていただく制度であり続けるためにしっかり努力してまいりたいと考えております。","voiceIndex":161,"id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"今ありました０.１％引き下げですよね。本当に、使いやすい制度を維持していただいて、これからも中小企業の発展、また事業の承継、さまざまな事業が行われていますけれども、継続に寄与いただければと思いますので、よろしくお願いいたします。ビジネス・カタリストについて伺っていくのですけれど、これも事務事業概要等を見ますと、９８名の登録があります。","respondent":"立木産業活性化担当課長","answer":"登録に際しましては、区の職員とカタリストマネージャーが面接の上、適しているかどうかということで登録いただいております。","voiceIndex":163,"id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"ビジネス・カタリストの方々が大勢いらっしゃって、カタリストマネージャーが面接してということで、それを活用されたい企業の方々も、当然、カタリストマネージャーと相談された上で、こういう適任の方がいますよということで派遣等されると思うのですが、意外と、件数が多いか少ないかというのはちょっと難しいのですけれども、事務事業概要を拾いますと、４６件、１６５回というところ。","respondent":"立木産業活性化担当課長","answer":"こちらの利用の経緯なのですけれども、企業がセミナー等で、この方のアドバイスを受けたいとか、そのようなことでお知りになる場合と、あと逆に区のほうに相談がありまして、困っていることを相談をいただいた中で。","voiceIndex":165,"id":"exchange-075"},{"speaker":"渡部委員","kind":"質問","question":"このカタリストが入ることによって、その企業が相当活性化された、また新商品等も開発されたというような事例も伺っています。例えば、先ほど融資あっ旋の質問をさせていただいたのですけれども、外回りをされている銀行の方々は、その会社がどういう会社でどういう経営をなさっているか、意外とよく知っていらっしゃるわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-076"},{"speaker":"あくつ委員","kind":"確認","question":"１４７ページ、難病対策費、１５３ページ、中小企業ＢＣＰ作成支援事業、時間があれば１５４ページ、観光アクションプラン推進事業についてお伺いいたします。難病対策費、何度も質問してまいりましたＭＴＢＩ、軽度外傷性脳損傷について、本年３月に、これを周知・防止するための啓発リーフレットを作成していただきました。誠にありがとうございました。幾つか今までの確認をします。","respondent":"舟木保健予防課長","answer":"ＭＴＢＩのリーフレットについてのご質問です。こちらのリーフレットにつきましては、軽度外傷性脳損傷というのが最近認識された疾患概念だということで、いろいろな症状を呈するということで、なかなか診断が難しいような疾患です。","voiceIndex":169,"id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今から４年前に、鈴木真澄議長の際に、全会一致で請願を採択していただいて、国への意見書も速やかに出していただいてという経緯もあります。品川区は、患者会の要望で、２３区で初めて教育機関への周知ということも文言に入って、皆さんの見識の高さに敬意を表するものであります。この後の展開について、何か教育機関でお考えのことがあれば教えてください。","respondent":"有馬学務課長","answer":"５月の校長連絡会におきまして、ＭＴＢＩのリーフレットの作成の趣旨を説明いたしまして、このリーフレットを保護者にも周知していくということの説明会ということで行いました。","voiceIndex":171,"id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これからスポーツ外傷であるとか、通学路での事故が非常に多いということから、教育機関への周知ということを患者会の方が求められていましたし、これを配られた方は、私もお話を伺いましたけれども、「そういうスポーツ指導員の方に周知するということが、やはり大事だ」ということはお母様たちもおっしゃっていましたので、ぜひ進めていっていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"このことは、いろいろ災害への備えは大事だという認識は、各企業あるいは経営者の方々、持っておりますが、何かに備えるというようなことよりも、やはり現実的な日々の経営などに企業の方々は奔走されているような状況もありまして、ただ、そうは申しましても。","voiceIndex":173,"id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問","question":"今ご答弁にもありましたが、内閣府の今年３月のＢＣＰの実態調査、大企業では６０.４％が策定済みであり、初めて６割を超えており、策定中というのを加えると８割近くになっている。先ほど、反省はされているというお言葉がありましたが、周知はどのように行われてきたのか、この２点をお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"本件、この事業によって、東日本大震災の後に創立した制度で、その当時はやはり利用いただけた企業が、たくさんといいますか、中でも集中したのですけれども、今年に入って熊本地震などもありまして、今年度については、今、策定中の企業が３事業者おりまして。","voiceIndex":175,"id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それが、ちょうど東京に戻ってきたというところで、限定１０人にだけそれを見せてあげようということで、私も大好きなものですから声をかけていただきまして、私も見てまいりました。歴史館とか、そういうところと連携するという話は伺ってはいるのですけれども、ここはぜひ、坂本龍馬が大好きと聞いている文化観光課長にお伺いしたいと思うのですが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"なので、ご提案のことも含めまして、何か品川をＰＲできるいいイベントができないかということで検討したいと考えております。","voiceIndex":177,"id":"exchange-081"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本当に宝庫なわけです。この前、日野の市議会議員と話をしていて、新選組の本場ですけれども、本当に品川区はうらやましいですねと。本当に何でもありますねということでおっしゃっていました。ぜひ各市区町村と連携しながら、この資源を活かしていただく。検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"この拡大の理由と、それから２０歳から３９歳ということなのですが、２０歳前の状況はどういうふうな形になっているのでしょうかということ。そういう意味では、このバスターミナルを使っての観光プランというのが、大崎駅との協働も考えながら何かできないかということでお考えをお聞きしたいと思います。そういうものが理解できるような仕組みも必要ではないかと思いますが、いかがでしょうか。","respondent":"川島健康課長、山崎商業・ものづくり課長、稲田都市開発課長","answer":"こちら、４歳年齢を拡大した理由ですが、今まで２０歳から３５歳という、これは５歳刻みを意識しての設定なのですけれども、５歳刻みでなく。今、国際化の対応につきましては、商連も含めまして今年度事業で委託事業としていろいろ検討する中で。今後におきましても、観光部門、それから商業部門とも連携しながら、大崎のまち、それから区の発展に向けて取り組んでいきたいと思います。","voiceIndex":181,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"２０歳からということで、機会が増えるということは非常に大切だと考えています。もっと長くやっていただきたい思いはあるのですけれども、そういう一生の中での歯科という形の観点で、何か１つの柱ができないかと思っているのですが、そのお考えはいかがでしょうか。ちょっと、担当がどこになるのか、私もどこが一番適しているのかわからないのですが、お考えをお聞きしたいと思います。もったいないです。","respondent":"川島健康課長、鈴木文化観光課長、河内協働・国際担当課長","answer":"一定以上の方がかかりつけ医を持っている状況もあるということでありますので。今年度、設置いたしました観光振興協議会のショートトリップの部会のほうで。その中では、お互いの文化を知るために、禁忌事項と申しまして、指のさし方、それから頭のなで方、それから身近なところではお手洗いのやり方など。","voiceIndex":185,"id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問","question":"１４４ページ、こころの健康づくり事業、自殺予防とひきこもり対策です。１４２ページの医師会助成費についてお伺いします。自殺予防の取組みですけれども、９月１０日から自殺予防週間の取組みがあったと思いますけれども、自殺は事故が起きたときには注目されていますけれども、決して風化してはいけないと思っています。","respondent":"舟木保健予防課長","answer":"品川区は、自殺対策に取り組みまして、今現在ありましたように、９月が自殺の予防月間ということで、東京都と一緒になりまして、３月とあわせて予防月間ということで啓発を重点的にやっているところです。","voiceIndex":190,"id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区の実態というのはどうなっているのですか。ぜひ品川区の実態をわかる範囲で教えていただきたいと思います。そのうち無職者、仕事をしていない人の割合が５９.５％と、６割。次いで、経済・生活問題、１６.６％。年１回の講演会だけではなくて、学習会、そして交流会など、職員研修もパンフレットを配るだけではなく、もっと力を入れてやっていただきたいと思いますが、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"品川区の自殺の現状と予防対策ということにつきましては、相談事業の中で、ゲートキーパー研修というものを年に３回、保健所で実施しているのですが、その中で必ず少し時間をいただきまして、お話しすると同時に、あと映画上映会のときにも。","voiceIndex":192,"id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり、まちで隣近所で困っている人がいたり、相談に乗れるような状況になるぐらい関心を高めていただきたい。ＷＨＯの報告では、９５％の方が、うつ病、アルコール依存とか統合失調症など、何らかの精神疾患を持っていらっしゃる。ぜひ相談機能の充実と、また継続的に相談が受けられること、充実してほしいと思います。悩みを抱えた人が集える常設の居場所を求めますが、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"周りの方が少しでも自殺の方に気が付いて相談につなげるというような形で、ゲートキーパー研修を取り組んでいるところですが、そちらにつきましては、対象については職員と、あと学校職員というところは大体決まっているのですが、その後はまた要望に応じて。","voiceIndex":194,"id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"常設の居場所づくりはどうでしょうか。ご遺族や残された人に対する支援はどうなっているでしょうか。日野市や多摩市などでは、自死遺族で、「わかちあいの会」といったことが開催されているというのを聞きました。品川区でもぜひＮＰＯ法人の方々などをお呼びして講演会を開くなどをきっかけとして、その後のつながりづくりを支援していただきたいと思いますが、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"事業につきましては、各保健センターと協力しながら実施しているような状況です。自死遺族の支援につきましては、区としましては、そういうご相談がありましたら、「わかちあいの会」とか、そういうところをご紹介するというような形で現在はしているところです。","voiceIndex":196,"id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問・要望","question":"相談の場所があってもハードルが高くてなかなか伺えないというところで、早期に第三者にかかわることが大事と言われていますので、ぜひ相談に、行動に移っていけるような工夫というか、相談につなげていただきたいと思うのですが、この点、ぜひ工夫していただきたいと思いますが、いかがでしょうか。休日診療の要望が来ていますけれども、テレビでも、救急医療体制、パンク寸前といった報道もされました。","respondent":"川島健康課長","answer":"それからシルバーウイークというのは、たしか４年に１回、暦がよい年が来るということなので、その前の年に検討させていただきたいという、その都度検討ということでお答えいたします。","voiceIndex":198,"id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問・要望","question":"長く維持していただきたい休日診療の制度ですので、医師会の先生たちとよく話し合って、ぜひ充実をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-090"},{"speaker":"渡辺委員","kind":"質問","question":"ページ数はあれなのですが、健康センターのことを伺います。成果報告書で、収入、利用料収入とある中で、先だっても厚生委員会等で部分的に視察に行ったときに、いろいろな掲示物や内容・施設の充実を肌で感じたものですから、それとあわせて、かなり地域の声も評判よく聞いています。１つのあらわれとして、利用料、利用者が増えている。ここ数年の収入の推移等を教えてください。","respondent":"川島健康課長","answer":"平成２４年度からお伝えいたします。平成２４年度が１億９,３８７万２,１３０円。それから平成２５年度も１億９,０００万円余。それから平成２６年度が２億円を超えております。それから、平成２７年度も２億１,０００万円という、毎年上昇しているという状況です。","voiceIndex":202,"id":"exchange-091"},{"speaker":"渡辺委員","kind":"提案","question":"そういう中で、利用者の顔ぶれに注目すると、ふだん公共サービスを実感が薄いと言われるようなサラリーマン層であるとか、年代で言えば、やはり３０代、４０代、５０代の方をよく見受けます。そういった提案にしたいと思うのですが、その辺の考え方をひとつ伺いたいと思います。それは利用料のところ。地域のエリアバランスに拠点の拡充が必要ではないかという、この辺の３点を伺いたいと思います。","respondent":"川島健康課長","answer":"それから拠点化というか、拠点を増やすというようなお話ですが、私どもも少し問題だと思っているところというか、気になっていたところというのが、やはり品川と荏原の格差というか、広さが違うのがまず１つなのですけれども、できれば同じような条件のところということで。","voiceIndex":204,"id":"exchange-092"},{"speaker":"渡辺委員","kind":"提案","question":"世代が若いということもあって、やはりアプリですとか、あるいは会員登録の中で本人了解のもと、うまく仕組みができればという思いで、これは要望にしておきます。続きまして１５０ページ、環境啓発のところを伺います。観光のところを伺います。それで、提案者がおもしろいと思って提案できるような募集の仕方をすれば、いい企画も出てくるのではないか。新規企画のつくり方についてと２点お知らせください。","respondent":"三ツ橋環境課長","answer":"なかなか、今、現状ですが、いろいろな場所でエコバッグは使われておりまして、区の段階が、今の段階でエコバッグをつくればいいのか、それとも区商連と協働しながら実施していけばいいのか、そのあたりは考えていきたいと考えています。","voiceIndex":206,"id":"exchange-093"},{"speaker":"渡辺委員","kind":"質問","question":"目にして、いいなと思ったのは、やはり「わ！最後に、観光の点で質問します。「この人、おもしろいな、こういうジャンルなのだな」とわかるようなことを、行政が観光協会等と連携しながらとか、やったらどうかと思うので、伺いたいと思います。最後に、観光全般でくくって、チャレンジの精神という観点で伺えればと思います。そういった意味で、チャレンジ精神という観光の意識について伺えればと思います。","respondent":"鈴木文化観光課長","answer":"それから２点目の、観光に関するチャレンジの考え方ですが、ご指摘のとおり、観光、新たなものを始めたり発掘するとき、どうしてもチャレンジの気持ちでリスクのことも考えて対応が必要というのは認識しております。","voiceIndex":208,"id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"私からは１４５ページ、そ族昆虫防除対策費。それから１５６ページ、商店街国際化推進事業。これは免税店のことについてということでお聞きしたいと思います。初めに、１４５ページのそ族昆虫防除対策費ですが、まず、そ族、この事業で、対策費の中で、そもそもになりますけれども、ネズミの防除ということも区が行っていこうとしている理由について、まずお伺いします。この２点をまず最初にお伺いします。","respondent":"井浦生活衛生課長","answer":"こちらは年間の相談件数の中でも、ネズミについての被害相談が多うあります。そのような中で、生活衛生の適正を確保するという趣旨でご相談に応じている。あるいは、ピッタンコという、トリモチのようなネズミとりもサンプルとして提供するという事業を行っているところです。","voiceIndex":211,"id":"exchange-095"},{"speaker":"塚本委員","kind":"質問","question":"具体的に、そういった相談の中で、主にあれでしょうか。やはり、みずからの生活圏に、一区民の方々が生活圏の中でネズミを何とかしてほしいと。そういったものを未然に防ぐために、解体に際してネズミの対策、駆除みたいなことというのは、そ族の防除対策費の中でやる範疇となり得るかどうかもお伺いします。","respondent":"井浦生活衛生課長","answer":"防除の直接的なツールとしては、ネズミの毒餌ですとか、あるいはネズミとりをサンプルとしてご案内するというための経費として見積もっているところです。","voiceIndex":213,"id":"exchange-096"},{"speaker":"塚本委員","kind":"質問・要望","question":"今お伺いしたご答弁ですけれども、ぜひ今後の検討課題というか要望というところにもなりますけれども、もう少し踏み込んだ形で、ネズミの発生を防ぐというか、また出てきているものを何とか駆除するというところについても、できれば対応していけるような形で取り組んでいただきたいと思いますので、その点の、この事業のある種の対象の拡大、範囲の拡大みたいな話になりますけれども。","respondent":"井浦生活衛生課長","answer":"ネズミは２番目に位置していますが、ネズミの出入り口をコンクリートで塞ぐ等々で防げるということもありますので、家屋解体等で出現するということも認識していますので、実態を見ながら防除の方法については研究していきたいと考えています。","voiceIndex":215,"id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"そういった議論の中で、品川区としてもこれは「検討している」というような答弁をこの間されているかと思いますけれども、現状どういった形に、今、この免税店の導入といいますか、これについてどのような状況になっているのかということをお聞きするのが１つと、それから品川区のほうに、個人経営の方でも結構ですけれども、免税店をちょっとやってみたいのだけど。","respondent":"山崎商業・ものづくり課長","answer":"それぞれの商店街の中の各個店の中では、既にそれぞれの個店の特性で、そうした免税の対応を行っているところもあります。","voiceIndex":217,"id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"今、やはり岡山方式を１つの参考にされている。これは行政視察でも見に行っているというようなことも伺っていますけれども、そうすると、そういう大店舗が１つの取次ぎの事務というのか、そういうものの中心になって、一括してやっていただくというようなことが前提になるかと思うのです。どういうところを課題として思っているのかどうかということをお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"いろいろ１００以上ある商店街の中で、いろんな商店街の抱える事情もありますので、それぞれの個々の特性と意向を確認しながら、よい方向で検討を進めたいとは思っております。","voiceIndex":219,"id":"exchange-099"},{"speaker":"高橋（し）委員","kind":"質問","question":"これは無料と。市内の女性を５０人ぐらい登録し、時間でお仕事をする。これは東京などでもしているのですが、それはビルの中とか、そういうところですが、これは空き店舗を活用して、補助金３,０００万円を使ってやっているということなのですが、このスキームについてご存じでしたら、それについてのお考えと、それから今現在、区の空き店舗の活用支援事業の実績についてお伺いいたします。","respondent":"山崎商業・ものづくり課長","answer":"子育てに関連した施設ということで、類似性があるものにつきましては、昭和通り商店街で、品川宿おばちゃんちの２号店というようなことで、こちらは小規模保育ルームということで、認可外保育施設として一時預かりの、そうした保育需要の部分と。","voiceIndex":222,"id":"exchange-100"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"奈良県の葛城市の場合は、ワーキングスペースという、それをつくることによって、子育て世代のお仕事にも、何というのですか、利するということなのですが、これについて、今、少し類似のあれがありましたけれども、このような形で就労支援の側面からぜひ検討していただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"何はともあれ、補助金がある間だけ回るようなスキームというのは、私ども補助の趣旨からも反しますので、いろんな意味で、商業・ものづくり課で所管する、中小企業の経営支援だとか経営相談、こうしたビジネスモデルの構築ですとか、そういったような面でも。","voiceIndex":224,"id":"exchange-101"},{"speaker":"高橋（し）委員","kind":"質問","question":"例えば商業・ものづくり課のほうの支援ではなくても保育系の支援だとか、そういった、縦割りではなくて横串といいますか、そういった形で行政がフォローしていくということができるのではないかと思いますが、そういった点についてはいかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"商店街支援のほうで３年を経過して、いわゆる家賃補助が切れる段階で、保育所管ともいろいろ連携する形で、本件事業が、きっちり収支がとれるような形のスキームとして、行政が支援を行う支援割合も含めて相談しながら、しっかり今。","voiceIndex":226,"id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、おばちゃんちなどは、そういった行政間の連携の成功の例ではないかと思います。ぜひ、総合窓口的なところ、これは商業・ものづくり課になるのでしょうか。では、時間があれなのですが、小規模の商店街のお話なのですが、大規模なものはかなり有名であれなのですが、小規模の商店街の支援については、あまり大きく目立たないのですが、大切な事業だと思うのですが、その事業についての実績をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"こうしたものを例えばフォローする専門家の派遣なり、人的な支援といいますか、そうしたものを、より細かな支援が必要だと考えて、こうした点で支援をこれまでも充実してきているような状況です。","voiceIndex":228,"id":"exchange-103"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"初めに、航空機の騒音調査ですけれど、午前中の答弁で、調査は場所を確認したということですが、その後の答弁で、まだ決まっていないようなご答弁があったのかと思うので、その点、もう一度お答えをいただければと思います。超音波検査の導入も求める声があると聞きましたが、その点についても現状と今後について教えていただければと思います。","respondent":"三ツ橋環境課長、川島健康課長","answer":"今回につきましては、あくまでも候補地の場所を確認しております。国が実際にどのような考え方なのか、そのあたり等を考えながら複合的に考えていきたいと思いますので、その点でまだ決まっていないと申し上げました。区としても、指針にないものを続けるというのがどうかというところで、地区医師会と８月に打ち合わせをした際に、その旨を伝えましたところ、なかなか即答できないというところで、専門の先生の意見も分かれるということで。","voiceIndex":232,"id":"exchange-104"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと、第三庁舎の１階にあるリボンですが、庁舎のところにリサイクルショップがある必要性があるのかなと、非常に私は思いまして、公共施設の中に、例えば保育園が非常に今足りない中で、私は以前から区役所内に保育所ということを求めているわけでありますが、都庁もこの１０月から「とちょう保育園」というものを開設され、国でも議員会館のところに保育所が設置されている中で、ぜひ。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長、柏原企画調整課長","answer":"航空機の調査地点ですが、こちらにつきましては、国の調査地点など、また区の調査地点など、連携していきながら考えていきたいと考えています。その行政上の必要性は今も続いているかとは思うのですが、ちょうど現行の体制、１０年の節目にあたりまして、昨今。発想といいますか、考え方としましては、我々も建物の有効活用、それからニーズといったところを考えたときに、そういった保育園であったりとか。","voiceIndex":235,"id":"exchange-105"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"マイスター店ですが、決算１,２００万円と出ていましたが、これは何に使われているのかお知らせいただきたいのと、メードイン品川ＰＲ事業ですが、いろいろ認定をされているのかと思いますが、例えば区内の企業を集めて、１つの製品というか商品をつくって、ある意味、本当の意味でのメードイン品川というものをつくって、それを全国、世界に発信できないかなと思いますが、このメードイン品川について。","respondent":"山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"マイスター店等支援事業の、決算額１,２００万円のうち、ほぼ委託料という形で、９００万円余、商連のほうに委託しまして、マイスター店というのは平成１８年度から５年間で選出したお店なのですけれども。これは隣の区でもやっておりますような、例えば１つのものをつくり上げてそれをＰＲするというのを、非常に私どももできればいいなということで、品川ビジネスクラブという財団がありますので。","voiceIndex":239,"id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問","question":"地方ではいろいろ特産物などやられているけれど、なかなか品川区ではそういうものがないので、ぜひこういったマイスター店の方たちと連携して、そういうことを進めていけばいいのではないかと思いますが、その点、どう考えるか教えてください。","respondent":"山崎商業・ものづくり課長","answer":"私ども、本件に関しての庁内の検討なども行う中で、委員がご指摘の品物、それから観光のほうで一番店のお土産というようなものですとか、それから本件事業の調査隊による区民の方々のすてきな品物を売っているものを発掘したり。","voiceIndex":242,"id":"exchange-107"},{"speaker":"若林委員","kind":"質問・要望","question":"もう一点、平成２７年度で言いますと、平成２７年度の４月にプレミアム付商品券が発行されましたけれども、このとき、それまでの１口１万円から５,０００円に、１口分が引き下げられたということで、多くの方がより買い求めやすいように工夫したという目的があったかと思いますので、４月以降、５,０００円に引き下げたことの目的は果たせたのかというのを聞いて。","respondent":"山崎商業・ものづくり課長","answer":"平成２７年度は、プレミアム商品券にとりましては、少し特徴のある年です。ご案内の春におきましては、発行総額８億円に２０％のプレミアムをつける特別な交付金を活用したもので行いました。","voiceIndex":245,"id":"exchange-108"},{"speaker":"若林委員","kind":"質問・要望","question":"一方、地域商業の振興という部分については、売上が上がったと。それは当然、４月については１０億円近いわけですから、そういう声になるわけですが、課題としては、今後、２,０００軒の加盟店の拡大がなかなか進まないというところ。精緻な分析をするというところで、今後、この内容の分析・報告が議会に対してしっかりとなされるのかというところは確認します。","respondent":"山崎商業・ものづくり課長","answer":"それで、今回も事前方式を導入して情報も取得できるようなことから、さらにプレミアム商品券についてはアンケートの結果を今後の本事業に活かしていくような、そうしたＰＤＣＡの取組みをさらに強化してまいりたいと考えているものです。","voiceIndex":247,"id":"exchange-109"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ区民委員会等への報告の場合は、書面にして、しっかりとみんなでまた議論できるようなものをつくって、そういうもので提出していただければと思います。公衆便所については既に議論がありますが、さまざまな要素がありますけれども、時間がありませんので１点だけ。文化観光を推進する立場から、どのような公衆便所、公園便所が望ましいのかお聞かせいただきたいと思います。","respondent":"溝口公園課長、鈴木文化観光課長","answer":"文化観光、観光という面が強いかとは思いますが、誰もが使えるようなトイレが必要だと考えているものです。例えば旧東海道の公園のトイレのように、観光の視点、文化の視点でふさわしい形や形状というのもあると思いますので、所管と連携しながら取り組んでいきたいと考えております。","voiceIndex":251,"id":"exchange-110"},{"speaker":"本多委員","kind":"質問","question":"１４９ページの、環境費、環境対策費、低公害車買換え支援事業、２点目が１５１ページの清掃費について伺います。最初に、環境対策費の低公害車買換え支援事業なのですが、買換えの支援の考え方について聞きます。先ほど渡辺委員からエコバッグの話がありました。普及することが目的で、またそういった運動が必要ではないかという投げかけでした。","respondent":"三ツ橋環境課長","answer":"一方、このハイブリッドカーの音が静かすぎるというものの考え方ですが、国が２０１８年以降考えていくというものですので、区といたしましても、国がどのように考えていくのか、実際に事故などがあってはいけないと思いますので、そちらにつきましても十分な情報をとって。","voiceIndex":256,"id":"exchange-111"},{"speaker":"本多委員","kind":"質問・要望","question":"次の質問に移ります。成果や課題についてお聞かせいただきたいのとあわせまして、今月発行の最新号なのですけれども、「持続可能な未来のために」というところに、「東京湾の最終処分場は、あと５０年で満杯になる。これはどうなのか詳しくお聞かせいただきたいのですが、これはやはり清掃工場でもやっておりますけれども、清掃工場の延命策というのをつくっていますよね。","respondent":"小林品川区清掃事務所長","answer":"２３区も努力しているという状況にあります。それが、今現在、東京都の処分計画から読み取れる最新の状況で、それを達成しますと、将来のことは断言できませんが、５０年以上の使用継続が可能、見えてくるという状況かと考えております。","voiceIndex":258,"id":"exchange-112"},{"speaker":"本多委員","kind":"質問","question":"取組みの成果が出ていると認識しますが、この最終処分場５０年というカウント、算定はどこでされているのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"ただ、現在の年間の処分量と、それから処分可能な容量とを割り返すと、そういった目途、５０年が目途になっていたというのが、当初の処分計画で算定されたものが若干ひとり歩きしていると受けとめております。","voiceIndex":260,"id":"exchange-113"},{"speaker":"本多委員","kind":"質問","question":"ちょっと次の質問に移りますが、先ほども清掃車の火災の状況、質疑がありましたけれども、私は清掃工場の不適正搬入防止策について、清掃一部事務組合が情報発信しているものを参考にしますと、清掃工場ですとか不燃ごみ処理センターに、いろんなそういう火災防止とか、そういったものの必要性から、不適正搬入防止月間、ちょうど今１０月ということなのですけれども、資料を見ていまして。","respondent":"小林品川区清掃事務所長","answer":"この不適正搬入につきましては、１つは可燃ごみとして搬入されているけれども、大きさその他の規格から、そのまま処理をするとプラントを傷めかねないようなもの、あるいはそもそも不燃のものが混入しているもの、そういった搬入を最小限度にしていく。","voiceIndex":262,"id":"exchange-114"},{"speaker":"本多委員","kind":"意見","question":"公園課の樹木の保存事業がありますけれども、これは公園課なのですけれども、保存樹というものがありますけれども、公園課のほうで、平成２７年度には１６カ所、３０６本、定期的な剪定ですとか、枝折れ・落下などの事故に備えて保険等にも入っておりますけれども、落ち葉について清掃事務所との対応、連携がとれないかということを、これまでも声を出してきましたが、現状をお聞かせください。","respondent":"小林品川区清掃事務所長","answer":"保存樹だけに限りませんが、落ち葉等につきましては、所有者の負担と責任で処分するということで、清掃事務所で受けております。もちろん、地域への貢献等を踏まえて、適切に臨時ごみとしての費用負担をいただいて処理しています。","voiceIndex":264,"id":"exchange-115"},{"speaker":"南委員","kind":"質問","question":"１４４ページのがん検診とその他の健診について伺います。各種検診を品川区は実施しておりますけれども、検診をしている目的というのは何でしょうか、改めて伺います。","respondent":"川島健康課長","answer":"検診の目的につきましては、区民の方の健康を守るということ、それで安全安心、それでいつまでも元気に暮らしていけるというのが最終目的になろうかと思います。","voiceIndex":267,"id":"exchange-116"},{"speaker":"南委員","kind":"質問・要望","question":"病気を早期に発見し、早期に治療するということも、健診の意味ということでいいでしょうか。改めて確認したいと思います。それで、しっかり健診を受けてしっかり治すことは重要だと思っているのですけれども、改めて健診の重要性について見解を伺いたいと思います。その中で、改めて受診率について、それぞれのがん検診の受診率を伺いたい、教えていただきたいと思います。","respondent":"川島健康課長","answer":"それから生活習慣病も早期発見が大事であるといった観点から、各種がん検診、それから各種健診を行っているものです。それから、がん検診の受診率の状況につきましては、平成２７年度、胃がん検診は平成２６年度が３.１％だったものがまた３.１％という状況です。","voiceIndex":269,"id":"exchange-117"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、やはりこれをもっと、少なくとも平均には持っていく必要があると思うし、目標値を持つ必要があると思うのです。そういう努力をやはりしていただきたいと思っているのが１つですので、そこを伺いたいのと、あと私、さっきのところで言わなかったけれど、子宮がん検診、乳がん検診は、料金はたしか数百円かかりますよね。有料でしたよね。そのことを確認したいと思います。よろしくお願いします。","respondent":"川島健康課長","answer":"女性のがん検診については受診券管理をしておりますので、該当年度には、受診券が直接ご自宅に届くような形でやっておりますので、こういった取組みを続けていくことで、受診率が少しずつでも向上するということ、もしくは意識が変わって。","voiceIndex":271,"id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"ほかの健診でもぜひそういう体制をとっていただきたいと思っているのですけれども、女性の健診に限っているのはなぜなのかをちょっと改めて聞きたいし、ほかのところでそういう体制をぜひとるべきだということについて、見解をお願いしたいと思います。それで、本当に目を塞いで、真っすぐ５メートルぐらい先まで歩いていくのも非常に不安になる。その点についての見解を伺いたいと思います。","respondent":"川島健康課長","answer":"それで、少しずつ２３区内でも、区の中での生活習慣病健診に位置づけて実施している自治体が増えているということなので、その辺を注視しながら、少し私どもも研究していきたいと考えているところです。","voiceIndex":273,"id":"exchange-119"},{"speaker":"南委員","kind":"質問・要望","question":"それで、検診をすることによって、２％から７％の方々が、いろんな目の病気を持っているということがわかる。ぜひそれはしていただきたいと思います。ですから、そういう認識を持っていらっしゃるのだから、やはり健診に組み入れて、区民の健康を早く発見して早く治療できる、そういうことにしっかりシフトしていただいて、健診に入れていただきたいと思っています。その点だけお願いします。","respondent":"川島健康課長","answer":"先ほど、眼科検診については、緑内障に限った話ではなくて、白内障、緑内障、それから網膜症という形で、糖尿病性のものですとか、そういったものもわかるような検診のことを私ども考えているのですけれども、広く検診の導入ということですので。","voiceIndex":275,"id":"exchange-120"},{"speaker":"たけうち委員","kind":"質問","question":"私、１５４ページの観光アクションプラン推進事業に関連して、それから１５５ページの下から２行目の商店街活性化推進事業、２つお聞きします。監査委員のいろんな指摘もありますので、それについてお聞きしたい。それから商店街のほうは装飾灯の件で、予算が１億１,７００万円余あったのですが、決算では６,６００万円、約６割弱ということなのですが、これについてなぜかということをまず教えてください。","respondent":"鈴木文化観光課長、柏原企画調整課長、山崎商業・ものづくり課長","answer":"今年、それから来年度についても、観光の視点でも歴史館が資源として活用できるような視点で事業を検討しています。民泊の検討状況です。国のほうの動き、国家戦略特区も含めた形で動いておったのですが、ここに来て、旅館業法の改正がまず年度当初にあったということ。結果としましては、実施されたのがそのうちの５つということで、４つの中止事業が発生したというようなことです。","voiceIndex":279,"id":"exchange-121"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。歴史館ですが、非常に大事な品川区の歴史を、１点につかさどるわけではないのですけれども、何かそういう部分で大事になってくるのかと。それで、歴史館もちょうど昭和６０年に開館して３２年になるのですか。一体的にこういうのをどうしていくのかというのを、また検討しなければいけないのかと思うので、何か所感があれば教えていただきたい。","respondent":"鈴木文化観光課長、山崎商業・ものづくり課長","answer":"観光の視点でも、ご指摘のありました大森貝塚や、そのほかのショートトリップのコースというところでも、十分観光のコンテンツになると考えておりますので、今後もしっかりとした維持管理、運営。その結果、ランプ交換をした場合に、そのランプを支柱を取り替えた後で、もう一回つけて使うようなことであれば、支柱の交換をすることは可能だということで、一歩、解釈が前進しておりますので、こういった事例も含めまして。","voiceIndex":283,"id":"exchange-122"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。歴史館のほうはまたぜひよろしくお願いします。それで、今、商店街の装飾灯なのですけれど、そうすると、一歩前進したというのは、東京都も、もうそれでいいよというふうになったということだと思いますけれど、それは区商連とか関係者の方はご存じということでいいのですか。","respondent":"山崎商業・ものづくり課長","answer":"この情報も商店街連合会と共有しまして、商店街にもしっかり周知しつつ、適正に効率的に更新が進むようなことでご支援申し上げたいと考えております。","voiceIndex":286,"id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"それで、設立の目的と、それからメンバー表をいただきましたけれど、例えばテレビ東京等、区内にあるマスコミが参加していないのはなぜかということと、それからこれだけの方々が集まって、観光をこれから議論していくことになると、例えば品川区の戦略や方向性をしっかりと持っていかないといけないと思うのですが、いかがでしょうか、現時点でのお考えをお聞かせください。お願いします。","respondent":"鈴木文化観光課長","answer":"具体的には、プランに基づく観光事業の推進のための情報の共有と調整、また事業推進にかかわる関係機関や団体との連携・調整に関することというような大きな機能を持っているものです。","voiceIndex":289,"id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、品川区内にテレビ東京があるわけですから、そういうところとやはり連携をとって、さまざまな形のものを外に出していくことを企画してはいかがでしょうかということをお伺いするのと、それから次のステップとして、観光振興協議会で何を議論して具体化していくのか、例えばほかの自治体を勉強していくと、よく観光基本計画というのがあります。","respondent":"鈴木文化観光課長","answer":"特に重要性に鑑みまして今年度につきましては、情報発信強化部会という専門部会を立ち上げまして検討していますので、その検討結果も踏まえまして、関係するテレビ局や新聞などへの情報提供やＰＲの仕方についてもしっかりと考えていきたいと考えております。","voiceIndex":291,"id":"exchange-125"},{"speaker":"伊藤委員","kind":"確認","question":"それに基づいてこういう団体ができた。それが品川区にとっても、この方々がトップクラスになるわけだから、しかも費用対効果からすれば、そんなにお金もかからずできるということを考えていくと、やはり次のステップとしては、情報集約をしていって、ある意味、品川区の全てのイベントが、そのホームページを見たらわかるようなことができれば、非常に観光振興に役立つと思うのですが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"特に今年度につきましては、ご指摘のあったような区内の情報について、年間の主な行事と、それから３カ月単位ぐらいの詳細のスケジュールというものをまとめたものを、今年度作成中の観光冊子に入れ込むということで、今、作業していますので。","voiceIndex":293,"id":"exchange-126"},{"speaker":"伊藤委員","kind":"意見","question":"それで、観光振興協議会が参加している企業団体が持っている情報、イベント情報というのは、非常に、何というか、価値があるものだと思うし、あわせて品川区の情報、それから区商連の情報、いろんな団体が集約されて１つのホームページで見られれば、そこからまたお得な情報を取り出すことができれば、これは非常に大きな価値になってくると思うので、今、私が聞いていて思ったのは。","respondent":"鈴木文化観光課長","answer":"情報発信ですが、観光振興協議会の中で、役割としては観光協会が主なものを担うものではありますが、それぞれの団体や事業者の方の取組みの中での、各取組みについてのＰＲ、それから関連する鉄道事業者の方に協力いただくＰＲ、そして区のＰＲと。","voiceIndex":295,"id":"exchange-127"},{"speaker":"伊藤委員","kind":"質問","question":"大切なことは、１つのホームページで全部が見られると言ったらいいのかな。ある程度、具体的なことをこれからお伺いしていきますけれども、例えばほかの自治体では、ゆるキャラというのをつくっていますよね。だから、何を言いたいかというと、品川区のゆるキャラの考え方と、それから品川区のキャッチフレーズを定期的に変えてはいかがでしょうかということをお伺いしたいのですが、いかがでしょうか。","respondent":"鈴木文化観光課長、中元広報広聴課長","answer":"それで、委員のご質問にそのままぴったりかどうかわからないのですが、観光につきましては、やはり区のＰＲのためには、そういうイメージを打ち出すというのが重要だと考えておりまして、実は今、ある会社のキャラクターと連携しながら。しながわ」という言葉の後ろに言葉をつなげて、品川区を自慢したりということで使っていただきたいという思いでつくってありますので、できれば、これを、いましばらく活用し、前後に言葉をつなげて展開していくということで。","voiceIndex":297,"id":"exchange-128"},{"speaker":"伊藤委員","kind":"提案","question":"「わ！イメージを、何というか、品川区の新しいものをどんどんつくり出していくことを考えれば、定期的に検討してみてはいかがでしょうかという指摘だけしますので、よろしくお願いいたします。だから、それを品川区で展開してみたらどうですかということを提案するのです。そういうふうにして、何というか、具体的に品川区をＰＲすることも検討してみてはいかがでしょうか。ご答弁をお願いいたします。","respondent":"鈴木文化観光課長","answer":"ただし、まだ、有名な方に出演をいただくのか、それとも魅力が伝わるような実際の風景を使うのかというのは、これからの検討ですが、確かに有名な方の起用というのは、一定程度、効果がありますので、その手法も含めて。","voiceIndex":300,"id":"exchange-129"},{"speaker":"伊藤委員","kind":"質問","question":"知っている方は知っているのでしょうけれど、あれをぜひ西小山駅に導入していただいて、バレンタインのときもＬＥＤをやると聞いたので、それは１つの観光名所になる可能性があるわけではないですか。これが西小山駅のＬＥＤの中にあって、きれいな映像の中にあれば、ある意味新しい観光スポットができる可能性もあると思うのですが、いかがでしょうか、ご答弁をお願いいたします。","respondent":"鈴木文化観光課長","answer":"ただ、西小山の商店街の皆さんと相談する中で、一応、点灯期間がバレンタインデーからホワイトデーにかかる１カ月以上を想定しておりまして、ご指摘のあったラバーズベンチ、若い方たちにアピールできるという仕掛けを考えながら、一定程度のテーマ、２人のカップル。","voiceIndex":302,"id":"exchange-130"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひ検討をお願いいたします。それから大井町も、ＬＥＤ化するのでもいいのですけれど、できれば来年度から、例えばみずほ銀行やＪＲの協力も得て、それぞれのＰＲをして、お金も出していただくかわり、宣伝するから、もっとたくさん大井町を明るくしていくなり、ＬＥＤ化していくなり、やはり１つ前に出た具体的な施策を検討してみてはいかがでしょうか、最後に答弁をお願いいたします。","respondent":"鈴木文化観光課長","answer":"大井町駅のイルミネーションにつきましても、昨年度、エリアの関係事業者の方等のお話を踏まえまして、今回ちょっと一部、銀行側にエリアを広げたりという工夫をしておりますので、今後もしっかりと進めていきたいと考えております。","voiceIndex":304,"id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"私は、産業経済費全般にわたってお聞きしたいと思います。区の施策に大きくかかわる財政課にお聞きしたいと思います。今の現在、区内の中小企業、産業の経営実態をどのように把握されているのか、お聞きしたいと思います。","respondent":"秋山財政課長","answer":"ただ、その中でも業種によって、先行きが大幅に改善する見込みのある業種もあれば、極端に改善をしているということで、前もお話しさせていただいたように二極化という、業種の中でも二極化がある。","voiceIndex":307,"id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"「どうなのですか」と僕らも聞いて回っています。「どうでしょうか。クリーニング業界、どうですか。こちらの販売、どうですか」。消費がこれだけ落ち込んでいるということは、ほとんど品川区内、中小零細企業、さっき８割という話でした。こういう実態。なぜ今、休廃業や解散が増えているというのをもう一度お聞きしますが、実態としてどう思いますか。それとも実態はわからないということでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"企画部門と連携しまして、やはり先ほど、区内の企業の状況ですとか、そういうところは私どもの商工相談員がしっかり訪問などを通じて状況を確認しているようなこと、それから融資で、１,４００件の企業に年間を通じて、いろいろ相談を経てそのようなことをしています。","voiceIndex":309,"id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"それで、先ほど就職、ちゃんと失業者も減っているというお話でしたが、実際、私はよく調べてほしいのは、勤労者の４割が非正規雇用ということと、所得が低く、そして上がらない正規雇用者層というのがあるのです。私は、区内産業や区内消費者の動向、実態を、やはりきちんと把握すべきだと思うのですが、消費者の動向とか、そういうのは把握しているのでしょうか、その辺についてもお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"それで、やはりいろいろ伸び悩んでいるような、財布のひもが固くなっているような状況にはあって、なかなか商店街もお悩みですけれども、そこをやはり品川区の１つの生活の身近な一部としての商店街が元気よくなっていくために。","voiceIndex":311,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"だって、一番簡単なのは、皆さんに区のほうで、では皆さん、共通商品券、一人一人に配ったら、５００円か１,０００円かわからないけれど、そうしたら皆さん買いに行きます。でも、想定外の黒字が出たら、実質収支の１割ぐらいは、私は低所得者層にやはり還元すべきではないかと思う。だったら、皆さんが大変なら、私たちもやはり、返せるものは返すという姿勢も大事ではないですか。財政課に。","respondent":"秋山財政課長","answer":"想定外の黒字というお話ですけれども、そういうときにこそ、景気が落ちて財政が落ちたときのために基金を積むというのが王道だと考えております。こういうときに使ってしまって、実際に景気が落ちたときに使うものがないという状態を避けるのが財政の仕事だと考えております。","voiceIndex":313,"id":"exchange-135"},{"speaker":"大倉委員","kind":"質問","question":"もう一点、食品ロスのほうで、“もったいない”推進店について伺いたいと思いますが、現在、日本の食品ロスは年間で５００万トンから８００万トンということで、全世界の食料援助量の約２倍ということで、取組みがこれからかなり必要になっていくというところで、今、品川区は“もったいない”推進店を進めております、小盛りメニューやハーフサイズや、少なめに対応している、宴会時などに呼びかけて。","respondent":"山崎商業・ものづくり課長、三ツ橋環境課長","answer":"中小企業ワークライフバランス支援事業です。こちらは、事業のほうは平成１９年度から開始しています。４年後に差し迫りました東京オリンピック・パラリンピックにつきましては、ロンドンオリンピックを超える、環境に配慮したものと考えておりまして、“もったいない”精神、日本の共通語の“もったいない”という精神に基づき。","voiceIndex":316,"id":"exchange-136"},{"speaker":"大倉委員","kind":"質問","question":"イクボス宣言、あと最近では豊島区がされまして、これは今までと違って、産官学、総勢６７団体が豊島イクボス宣言ということで、商工会議所や法人会、商店街、経済団体ら町会連合会、法人会、ＮＰＯ法人、１３団体ともやっております。民間企業など等と書いてありますが、総勢１０１名でやっておりますが、こうしたイクボス宣言、非常に重要かと思います。このイクボス宣言についてお考えを教えてください。","respondent":"山崎商業・ものづくり課長","answer":"中小企業のほうの支援事業も含めまして、やはり組織のリーダーの方、トップの方、経営者の方が、うちの会社はこういう風土でこういくのだということになりますと、やはり小規模の事業者であればあるほど、経営者の考え方というのですか、それが。","voiceIndex":319,"id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後、ＳＨＩＮＡＧＡＷＡ“もったいない”推進店が、今、小さい商店街を主に取組みを進めているところと思いますが、大きい商店街においてのほうが、効果、また周知の効果といったところも大きいのかなと思うところで、そうした今後の先の展開について、お考えを教えていただきたいのと、またほかの自治体の取組みでは、３０・１０運動というのがされておりまして、例えば例で挙がっているのは。","respondent":"米田人事課長、三ツ橋環境課長","answer":"これをより推進していくということでは、今までどおりの行動計画の中で、より目標を設定して、またこれに取り組んでいきたいということで、区の職員向けにはそういうことで取り組んでいるところです。今回の委員ご指摘の３０・１０運動なども考えながら、今後、品川区として一番いいものを考えていきたいと考えています。","voiceIndex":321,"id":"exchange-138"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ、これは対外にも対内にも、住みやすいまち、住み続けたいまち、安心して暮らせるまちというところで、品川区もぜひ宣言も目指して取組みを前に進めていただきたいと思いますので、これはちょっと、ぜひ考えていただければと思って要望します。“もったいない”推進店のほうなのですが、ぜひ今後さらに食品ロスを減らせるように取組みを、さまざまな自治体も見ながら行っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":324,"id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１４８ページの環境対策費のところから、羽田新ルート計画が品川区の環境に及ぼす影響についてお伺いしたいと思います。しかし、その具体的な中身が明らかにされていないと思っています。それから、また航空機から大量のナノ粒子が排出されていることが確認されたというふうに報告で述べられております。この環境省が出している報告書について、区としてどう捉えているかをお聞かせいただきたいと思います。","respondent":"三ツ橋環境課長","answer":"今、委員ご指摘の平成２４年度の船舶・航空機排出大気汚染物質削減に関する検討調査につきましても、やはりまずは品川区としてどの程度のものが実際に現状、ＮＯＸであるとかＰＭ２.５であるとか、把握しておかなければいけないと思いますので。","voiceIndex":326,"id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は国土交通省のほうは、この大気汚染物質に対しては、影響は限定的ということで大したことがないというような説明をしている中で、環境省が、これだけこれから重大になると、こういうことに対して、私は品川区としてもしっかりと認識していただきたいと考えていますけれども、いかがでしょうかということで伺ったので、また改めて伺いたいと思います。そんな中で、東京都が国に対して要望書を出しています。","respondent":"三ツ橋環境課長","answer":"実際に、ＰＭ２.５につきましても、測定の結果ですけれども、今、委員ご指摘のように、実際、環境基準というものが非常に微小ですので、測定の方法なども踏まえながら考えていきたいと考えています。","voiceIndex":328,"id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから次に、騒音についてです。騒音の基準はどうなっているかということなのですけれど。多分、これを超えると品川区の環境課に電話すると指導に来てくれるという状況が、今度は１３２回、１時間に４４機が３時間ですから、そういう形で襲いかかってくるという捉え方になると思うのですけれども、そこのマンションの建設のデシベルとあわせて、そういう捉え方でいいのか、ちょっと伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"したがいまして、今回の特定建設作業が８５デシベルとなっている場合、今回は違うものと考えております。","voiceIndex":330,"id":"exchange-142"},{"speaker":"浅野委員","kind":"質問","question":"そろそろ需要のほうも減ってきたのかなという状況だと思いますが、この件についてはいかがでしょうか。例えば家を取り壊すとか、また転居するとか、そのような場合については、やはり何らかの形で縛りというのでしょうか、簡単に撤去できないような形をとっておかないと、知らない間にどこかで使われているということもあるかと思います。","respondent":"三ツ橋環境課長","answer":"太陽光発電パネルにつきましては、実質、平成２６年度が５４件、家庭用です。平成２７年度が４３件、実際に平成２８年８月末までに８件となっておりまして、若干下がっているのが現状となっております。","voiceIndex":334,"id":"exchange-143"},{"speaker":"浅野委員","kind":"質問・要望","question":"勝手に取り外したりすることができないとか、そういうことについてはどうなのか、後でまた教えてください。温室効果ガスの排出量について質問しますが、今の段階で、２０１３年の結果というものは既に出ているのかどうか。この報告の件ですけれども、毎回、結果が出たら建設委員会にたしか報告されていると思いますけれども、これも結果が出たら早急に報告をお願いしたいと思いますが、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"力を入れている取組みですけれども、地域推進計画、また実行計画につきましても、実行計画は特にしながわエコリンクを昨年度から実施いたしておりますので、品川区の庁内全体に環境への配慮、また環境への意識を高めてまいりたいと思っておりまして、力を入れております。","voiceIndex":336,"id":"exchange-144"},{"speaker":"浅野委員","kind":"質問","question":"最近、報道もされておりますけれども、去年、フランスでＣＯＰ２１が開催されまして、２０２０年以降の国際的な枠組み、パリ協定が採択されました。日本の約束素案は、２０３０年度に２０１３年度比で２６％の削減となっております。長期的目標としては２０５０年までに８０％の削減を目指す。日本の立ち位置がかなり変わってくるのかとも思いますが、この件に関してどう捉えられているのか教えてください。","respondent":"三ツ橋環境課長","answer":"区といたしましても、この閣議決定、またＣＯＰ２２につきまして、非常に重要だと考えていますので、それらを捉えながら、区として、この３計画、今後考えていかなければいけないものを盛り込んでいきたいと考えています。","voiceIndex":338,"id":"exchange-145"},{"speaker":"浅野委員","kind":"質問・要望","question":"品川区においては、これまで環境計画、地球温暖化対策地域推進計画、地球温暖化防止対策実行計画の環境３計画の整合をとっていくというのが今後の課題だと答弁をいただいたことがありますが、具体的に東京都の計画、私の知っている限りでは、２０３０年までに、排出量ですけれども、２０００年度比３０％削減の数字が出ていると思いますが、これに対する品川区の捉え方。","respondent":"三ツ橋環境課長","answer":"しかしながら、品川区といたしましても、実効性のある計画を考えておりまして、委員ご指摘の３計画につきましては、やはり品川区独自の取組み、また削減率、そちらがＣＯ２削減なのか、またエネルギー消費量なのか、そのあたりも考えながら実際につくっていきたいと考えています。","voiceIndex":340,"id":"exchange-146"},{"speaker":"浅野委員","kind":"質問","question":"最後になりますが、１５７ページの外国語版ホームページ作成経費助成について簡単に質問します。このホームページをつくって、外国からのアプローチが実際にあったのかどうか、その例があれば教えてください。何件かあるならば、その状況も教えてください。よろしくお願いします。","respondent":"立木産業活性化担当課長","answer":"こちらのホームページ、つくった結果、アクセスがあったということ、それから問い合わせ、メール等、入っているということは聞いてありますが、ちょっと具体的な数字に関しましては、そこまで手元にございませんので、申し訳ございません。","voiceIndex":342,"id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私は衛生費の中の２項環境費、１４９ページで環境指導相談費、それから１５０ページの資源回収事業、それから３項の清掃費から何点かお聞きしたいと思います。この辺の実態と、今どういうふうになっているのか、まずそれを１点お願いします。ですから私も、予算特別委員会でもこの件を確認させていただいたのですが、町会での資源回収のやり方についてもう一回確認させてください。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長","answer":"環境指導相談費の土壌汚染に関する相談件数ですけれども、中心となるものは不動産業者であるとかディベロッパーなどが確認している件数となっております。実質的な利益としては、回収しました資源について、キロ６円の活動費として助成しています。","voiceIndex":345,"id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問","question":"集団回収、町会でやっていただいて、私の町会でも、前も言ったのですが、やってはいるのですけれど、やはり人的な問題が厳しい状況で、ほとんど新聞紙であっても新聞古紙だと思うのですが、これをどこまで町会のほうに回していくのか。今、一般の区の収集と集団回収をどう切り分けていくのか、そこのやり方をもう一回教えてください。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長","answer":"一方、品川区内の部分につきましては、実際に環境課が相談役となって、いろいろな部分で実際に土壌汚染が出た場合にどうしたらいいのか、そのあたりのことについては取りまとめをしておりまして、庁内の連携はとっております。しかしながら、各地域によって、団体の取組み、それからマンパワーが異なりますので、これについては一律、二者択一ということではなくて、相互の補完関係ということで、地域が取り組める範囲を尊重しつつ。","voiceIndex":348,"id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"質問","question":"両方とも大体わかってきました。土壌汚染に関しては、区の中の部署は連携できると思うのですが、よく昔、クリーニング屋が廃業すると、土壌汚染の問題が出てくるというお話を聞かれて相談も受けたことがあります。こういうときの対応というのは、区のほうとしてどういうふうにやっていらっしゃるのか、その点を教えてください。","respondent":"三ツ橋環境課長","answer":"そちらは調査して、実際に調査をした中で、環境の基準に合っているかどうか、超えている場合につきましては、土壌汚染対策防止法にのっとりまして、また環境確保条例上にのっとりまして、対応してまいります。","voiceIndex":351,"id":"exchange-150"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今、クリーニング屋と思って、忘れていた。ガソリンスタンドがそうでした。もう一点確認したかったのが、１５１ページの、東京二十三区清掃協議会負担金の件です。区からは年間５０万円の支出がありますけれど、清掃協議会の運営は２３区ということは、１,１５０万円の予算を組んでいるということでよろしいのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"ご指摘のとおりです。","voiceIndex":353,"id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一緒に聞けばよかったのですけれど、改めて清掃協議会の今の業務内容について教えてください。","respondent":"小林品川区清掃事務所長","answer":"１つは、一般廃棄物処理業の許可に関する事務。こちらは各区から管理執行ということで仕事を集中執行しているものです。２つ目が浄化槽清掃業の許可に関する事務です。３つ目が、雇上車、雇い上げ車両の関係事務を統一的に行ってあります。","voiceIndex":355,"id":"exchange-152"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の許可事務ですか、これは区の分を向こうでやっているということだったのですが、これは平成１２年に清掃が区に移管したとき、この清掃協議会というのは必要性を大分、あのときにいろいろ検討したと思うのです。","respondent":"小林品川区清掃事務所長","answer":"ご報告いたしました３点について見直していこうという動きは今のところございません。目的が２３区共通で、それを集中して共同処理したほうが効率的であるという点に着目したものです。","voiceIndex":357,"id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1426#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":116605,"voices":359}},{"id":"h28-20161014-4","meetingId":"h28-c-settlement","date":"2016年10月14日","dateIso":"2016-10-14","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２７年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"おはようあります。よろしくお願いします。成果報告書１５９ページ、駅周辺等放置自転車対策事業の放置防止指導啓発について、お伺いをいたします。そのことについて、私道にかかるところですけれども、今現在、区として鉄道事業者に対してどういった取組みをしているのか、お聞かせ願います。","respondent":"桑波田交通安全担当課長","answer":"周辺に区営、民営含めまして５カ所ほど駐輪場がありますので、こういったところのご案内と、放置禁止の告知の掲示は既に終了しています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、駅周辺の区道のところに、数年前、商店街のほうで依頼した、自転車を放置できないようにポールをつけていただいたのですけれども、そこの間にまた自転車を入れてしまうということで、先日、ポールを撤去していただいたのですが、ポールを撤去したことによって、今度は、週末になると自転車がすごく置いてあるという状態で。","respondent":"溝口公園課長","answer":"これにつきましては、今年８月、オリンピックの正式種目に決定するなど、今後、スケートボード競技人口の増加が見込まれるところです。そういったところを受けて、区内でもスケートボードができる公園の整備は前向きに検討していきたいと考えているものです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"意見","question":"ただ、騒音問題とか、昔は様々な問題があったと思うのですけれども、今の若い世代の子たちというのは、環境に対してすごく意識が高くなっているところがありますので、その辺も含めて、今、場所等、どこをお考えになっているのか、わかる範囲でお知らせください。よろしくお願いします。","respondent":"溝口公園課長","answer":"とは言え、マナーの向上、またはそういった適地を含めて、品川区内の公園の中、また、公園の整備時期をにらんで、できるだけ早くスケートボードができるような公園ができるように、今、検討を進めているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"スケートパークと一言で言っても、競技が何種類もあるのですけれども、それも今後、いろいろと調査をしていただいて、４年後、競技場がどこになるかはまだ決まっていないそうですけれども、機運上昇のためにも、また未来ある子供たちのためにも、スケートパークをぜひ検討していただきたいと思います。続きまして、１６８ページ、密集住宅市街地整備促進事業について、お伺いをいたします。","respondent":"古巻防災課長","answer":"感震ブレーカー設置助成事業の内容についてのご質問ですので、防災課よりお答えいたします。感震ブレーカー設置推進事業ですけれども、今年度より設置の助成を開始したところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今現在の、既存住宅の取り付け申込み件数と新築住宅の取り付け申込み件数がわかれば、教えてください。","respondent":"古巻防災課長","answer":"ただ、お申込み１３６件ありますけれども、取り付けに関しましては、現地の確認、それから見積もりを出していただいて、再度正式に申請をいただくという形になってございまして、申請いただいている件数につきましては本日現在で３６件です。","voiceIndex":12,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"新築住宅の場合、区内の業者が新築を請け負うというときであれば、当然区としてもこの助成制度を促していると思うのですけれども、町場でもハウスメーカーが新築住宅に取組んでいるというところで、区として、ハウスメーカー等への告知といいますか、そういった活動はしているのでしょうか、教えてください。","respondent":"古巻防災課長","answer":"周知に関しましては、今現在、区として、ハウスメーカーへ直接周知という形では行っておりませんで、個人の方、新築される方も含めて、地域の方に対しての周知をしているという状況です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今、この設置推進事業の助成制度については、木密地区が限定だと思うのですけれども、今後、区内全区域に対してこういった助成制度をやるのか、やらないのか、教えてください。","respondent":"古巻防災課長","answer":"当面は、やはりこちらの地区の普及を促進したい、ここに注力したいという考えがありますので、現在のところ、エリアを拡大するという考えはございません。","voiceIndex":16,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひこの助成制度をよろしくお願いしたいと思います。木密地域に関連しまして、旗の台四丁目地区のちょうど旗の台小学校の前のところの地区は、本当の木造密集地域で、一軒長屋が密集しており、実際に有事が起きたときに消防車が入っていけない、そういった中で、区としてどういうお考えをしているのか、教えてください。","respondent":"寺嶋木密整備推進課長","answer":"引き続き、地区の皆様と検討、勉強を進めながら、改善に向け、取り組みたいと考えております。","voiceIndex":18,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問","question":"木密地域の感震ブレーカー設置について、先ほど件数を教えていただきましたけれども、現在、旗の台四丁目地区ではどの程度申込み件数があるのか、わかれば教えてください。","respondent":"古巻防災課長","answer":"申し訳ありません。今、手元に地区ごとの件数は持ち合わせておりません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"交通安全啓発ですが、誰もが最近感じていることと思うのですけれども、歩きスマホ、また、自転車スマホの危険性というところで、品川区がどういうふうに対策を進めていただけるかという現状を確認させていただきたいと思っています。あわせて、現在までに品川区の中で歩きスマホ、自転車スマホで起きてしまった事故とかがあるのかどうか、確認をしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"あわせてチラシもつけさせていただいているところです。その後も、そのチラシの活用のキャペーン実施、また、スケアードストレートといったもので、そういった場面を想定した事故再現ということで、区民の方には周知させていただいているところです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"区内では事故がないということですね。よろしいでしょうか。","respondent":"桑波田交通安全担当課長","answer":"区内の事故は、統計がとれておりませんので、あるかどうかは判明しておりません。","voiceIndex":25,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"わかりました。区内でどうなのかということは気になるところなのですが、これはまた何か統計をとれる手段があるのであれば、確認をしていただきたいと思います。こういう具体的なところを区としても出していただきながら、あとは、例えば主要駅などでの街頭キャンペーンですとかもぜひ折々にやっていただきたいなと思いますが、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"対象が幅広い状況にありますので、子供に対しての事故防止、もしくは女性であれば引ったくりだとか性犯罪、こういったものも画面を注視していることによって被害に遭う可能性もありますので、それはそれぞれの所管で、関係機関と連携をとりながら、対策を実施しています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。次に、自転車走行レーンについて、お伺いいたします。平成２７年度、区内調査をされていると思いますので、調査結果と、現状どこまで進んでいるのかということを教えていただきたいと思います。","respondent":"多並道路課長","answer":"今後についてということですけれども、この中から今後の進め方は検討するべきと考えております。これまでの取組みをお話ししますと、区内の自転車レーンの整備実績といたしまして、区で行ったレーンが５.６km、また、警視庁で施工したものが３.１km。","voiceIndex":29,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"調査をして、まだできていないところがあると思いますが、具体的にこれから進んでいくであろう地域はどの地域になりますか。今後これから拡張されるところに関しては、例えば色を塗らないで、走行の指示だけするようなタイプが可能なのかということを教えていただきたいと思います。","respondent":"多並道路課長","answer":"これについて、国や都と連携して、どのように進めていくかということを検討している最中です。区の中で言いますと、大井ふ頭中央海浜公園の周辺が対象地域となっております。八潮地域の自転車レーンの考え方ですけれども、今まで様々なご意見がございました。","voiceIndex":31,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"それでしっかりと整備を進めていただきたいと思います。最後に、家具転倒防止器具取付助成ですが、３０万円の予算に対して決算額が８,０００円ということで、ちょっと進んでいないなと感じるところがあります。１件なのか２件なのかという感じだと思いますけれども、これはどこで周知をされているのか、平成２７年度、平成２８年度も含めて現状をお知らせいただきたいと思います。","respondent":"今井住宅課長","answer":"家具転倒防止器具取付助成の周知ですけれども、戸籍住民課の転入等の窓口でも周知しておりますし、地域活動課と連携いたしまして地域センター等、それから、こちらは高齢者、障害者に向けての購入および取付助成もありますので、高齢者地域支援課とも連携して周知しています。","voiceIndex":33,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"地域センターで周知されているということでしたが、支え愛・ほっとステーションでもぜひ強力に周知していただきたいと思いますが、いかがでしょうか。","respondent":"今井住宅課長","answer":"支え愛・ほっとステーションは特に福祉の分野もありますので、先ほどの所管課と連携しながら対応してまいりたいと考えています。","voiceIndex":35,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"１６７ページ、大井一丁目南第１地区再開発事業について、伺いたいと思います。区は、繰り返し一方的に転出を求めることはありませんとお話ししますが、私がお会いし、お話を伺った方は、どの地域でも、こんな追い出しがなぜ許されるのか、私有財産をなぜ奪えるのかと話しておりました。なぜ追い出されたとの声が権利者より上がるのか、理由を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"私ども、補助金等を出して、地域の方、権利者等と協力して再開発事業を進めている中におきまして、まず、組合設立時の認可は権利者等の３分の２以上の同意がなければ進められないというところで進めてきております。","voiceIndex":38,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"ご答弁では、権利者の方に丁寧に対応しているということでしたけれども、私が伺ったのは、なぜ追い出されたとの声が権利者より上がるのか、この理由を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"組合の事務局がありますが、私どもは権利者の方々に、先ほども言いましたけれども、丁寧に説明をしている、また、権利変換計画縦覧のときにおきましても、意見を申し立てるところもあります。","voiceIndex":40,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"そこで伺いますけれども、大井一丁目南第１地区では、２割を超える約１６人の権利者が同意していないのに、さらには解体工事では１０人もの権利者が同意していないのに、開発計画を進めている。だから追い出されたという声が上がるのだと思いますが、この点、伺いたいと思います。そして、区がたびたび言う一方的ではないというのは、どういう状態のことを指すのか、ここも伺いたいと思います。","respondent":"稲田都市開発課長","answer":"大井一丁目南第１地区の権利変換計画時の同意の関係ですが、２５５名の関係権利者がおりまして、２４２名が同意して、９４.９％の同意率というところで権利変換計画認可時は進めてきております。","voiceIndex":42,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、２割を超える約１６人の地権者が同意していない。解体工事は１０人もの権利者が同意していない。しかし、開発計画は進めていく。このどこが一方的ではないのか、この点を伺いたいと思います。今も全員合意と言いながら、実際は３分の２の合意があれば進められるのだと。結局、全員同意というのは建前なのか、その点も伺いたいと思います。","respondent":"稲田都市開発課長","answer":"都市開発法に従って３分の２以上というところで進めてきているところですが、話を進める中においては、評価額とか評価の内容とか、そういうところで話が折り合わないところもあります。その中で、丁寧に話をしながら進めてきているところです。全員同意、これは本当に基本です。","voiceIndex":44,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"その中で１６人もの権利者が同意していない。しかし、もともと同意していない人がいることを知りながら開発計画を進めたからではないでしょうか、この点を伺いたいと思います。つまり、もともと同意していない人がいるのに進めるため、追い出された、私有財産をなぜ奪うのかという声が上がるのではないでしょうか。この点を伺いたいと思います。この点も改めて伺いたいと思います。","respondent":"稲田都市開発課長","answer":"先ほど来ご答弁させてもらっていますけれども、都市開発法に基づきながら進めてきている。そして、同意をしていない方におきましては、評価、それから丁寧な説明、繰り返しお話をしながら、今までも、大井一丁目南第１地区につきましてお話を続けてきているところです。","voiceIndex":46,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"仕組み上、３分の２の同意で進められるといい、また、その同意している人の権利を守るためといい、これはあまりにも都合のいい話だと思います。先ほどから丁寧に説明をしていると述べていますが、なぜ住民から追い出されたとの声があるのか。これはやはり再開発の仕組みそのものに原因があると思います。この仕組みが、追い出されたという声が上がる一番の原因だと思いますけれども、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"こういう中で意見を出していただいて、適正な判定をいただきながら、それに従って再開発事業を進めているものですので、決して追い出す、追い出されたというようなことにはならないと思います。","voiceIndex":48,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"これは区の答弁です。ここまで進むと、結局再開発組合に入るのか、それとも引っ越すのか、この二者択一しかない。この仕組みに、追い出されたとの声が上がる原因があると思いますけれども、改めて伺いたいと思います。もう１つ、マンションに入ることも引っ越すこともどちらも最後まで徹底して拒み続けると、最後の最後、最終的にはどうなるのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"再開発事業は都市開発法に従いまして進めているです。何度も意見を言う場を設け、また、話し合いの場も設けて進めてきておりますので、一方的に転出を求めているところには立っていないです。拒み続けると最終的にどうなるのかですが、最終的には裁判という形になってくるです。","voiceIndex":50,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"最終的には裁判と言いますけれども、要するに最終的には強制執行があるのだと、コンサルタントから権利者は話を聞いていると私は伺っております。それが、追い出しだ、私有財産をなぜ奪うのかという声が上がる原因だと私は思います。地域コミュニティをつくるといいますが、壊しているだけではないでしょうか。住民コミュニティを壊している自覚があるのか、その点、最後に伺いたいと思います。","respondent":"稲田都市開発課長","answer":"再開発事業というものは、地域のいろいろな課題を解決していって、新たなまちに更新し、地域の発展につなげていくというものです。決してそのようなことではないというところです。","voiceIndex":52,"id":"exchange-024"},{"speaker":"木村委員","kind":"質問","question":"お聞きします。ハード面のバリアフリーと心のバリアフリー、ユニバーサルデザインとが共存できる部分はありますか。あるとすれば、どういうところでしょうか。お願いいたします。","respondent":"多並道路課長","answer":"我々も、この決算にも入っておりますけれども、大井町のバリアフリー事業を進めて、さらなる大井町駅周辺のバリアフリー化を進めるとともに、全体的なバリアフリー構想の中にソフト部門も一緒に入って検討しておりますので、そういう中、また。","voiceIndex":55,"id":"exchange-025"},{"speaker":"木村委員","kind":"意見","question":"大井町駅周辺バリアフリー工事で、障害者や視覚障害者、また高齢者のための道路と歩道との段差が、ゼロ段差、また２センチ段差と分かれていますけれども、なぜ１つのところにゼロ段差と２センチ段差が共存するのか。全てをゼロ段差にすべきと思いますけれども、分ける理由をお聞かせください。","respondent":"多並道路課長","answer":"その中でも広い歩道がある場合には一部を、約１ｍちょっとですけれども、ゼロ段差として、それ以外の場所は２センチ段差とするような工夫もしながら、よりお使いいただきやすい構造を進めているものです。","voiceIndex":57,"id":"exchange-026"},{"speaker":"木村委員","kind":"質問","question":"２センチ段差とゼロ段差は何となく理解できました。ちょっとした段差につまずいてしまうようなこともあろうかと思いますけれども、その周知の仕方はどのようにするのでしょうか。そしてあと、八潮団地の、先ほど新妻委員からもありましたけれども、道幅は変わらないのだけれども、歩道と自転車道をどのようにするのかということをもう一度お聞かせください。","respondent":"多並道路課長","answer":"それとともに、歩道を自転車がなるべく通らないで歩行者の方がご利用していただきやすいように、自転車の走行空間をあわせてつくりまして、あわせて整備したことで、よりお使いいただきやすいような構造ということで検討したものです。","voiceIndex":59,"id":"exchange-027"},{"speaker":"木村委員","kind":"意見","question":"競技場周辺の無電柱化事業は、来場者をスムーズに移動、またはブラウン管を通して、また来訪者の口から口へと世界へ紹介される、とても大きな、また大事な事業となるでしょうけれども、目標は平成３２年になっていると思いますが、計画をお聞かせください。","respondent":"多並道路課長","answer":"それから平成３０年度から平成３１年度の初頭にかけまして道路整備工事ということで、これについては、大田区と接続する道路でもありますので、大田区と品川区で連携しながら今一緒に、そこの工程も含めて工事を進めているところです。","voiceIndex":61,"id":"exchange-028"},{"speaker":"木村委員","kind":"提案","question":"１６５ページの上から１１行目、区民の自主的なまちづくりへの支援、８８万円余からですけれども、本区のホームページには、「住み良いまちづくりをするためには、地域の事情に詳しい皆さんの提案から取り組むことが大切であると考えています。」と紹介されています。区民が抱える生活上の問題とは、どういったことが１番にランクされているのでしょうか。","respondent":"中村都市計画課長","answer":"こういった課題につきましては、地域の皆様方ご自身がお住まいのまちが将来どのようにあるべきか、またどうしていきたいか、こういったものについて区民の皆様からいろいろご意見をお伺いして、そして、それを地域の皆様とともに考えて。","voiceIndex":63,"id":"exchange-029"},{"speaker":"木村委員","kind":"質問・要望","question":"これは要望で、お願いをしたいと思います。公園・児童遊園維持管理費に入ると思いますので質問いたしますけれども、町会役員の相談事は、備えつけたトイレットペーパーが持ち去られるというお話でした。ペーパーケースには鍵がついていることを私も確認をしたのですけれども、頻繁になくなるということでありました。そこで、このことに対してどのように考えているかということをお聞きしたいと思います。","respondent":"溝口公園課長","answer":"清掃につきましては、毎日１回、必ず行っております。そういった中で、トイレットペーパーの持ち去りも確認しております。トイレットペーパーの持ち去りだけでなく、あまりにもひどい器物破損があるものにつきましては、平日の巡回、または夜間の警備の巡回等もしております。","voiceIndex":65,"id":"exchange-030"},{"speaker":"木村委員","kind":"意見","question":"２６６カ所もトイレがあるわけでありますから、いろいろなことが起きようかと思いますけれども、それ以外の公衆トイレとか、また児童遊園などでも持ち去りが起きているのかどうか。それに対して将来的には処罰の適用は考えられるか、または考えているかということをお聞かせください。","respondent":"溝口公園課長","answer":"そのうち、公園・児童遊園合わせまして１２６カ所の公園トイレがあります。そちらの管理をしているものです。悪質なものについては、しっかり警察に被害届等を出しながら、これまでも対応していますし、今後も同じような対応をしていきたいと考えているものです。","voiceIndex":67,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、オリンピックか公園なのですけれども、大井ふ頭中央海浜公園ですが、都立ですけれども、ホッケーの大会が行われるということで、周辺の整備などについて、東京都への要望とか調整はどういう形で品川区としてはやっていくのかということと、それと、レガシーという言葉がオリンピック・パラリンピックにはよく出てきますけれども、せっかく品川区で開催されることなので。","respondent":"今井住宅課長、和田河川下水道課長、多並道路課長、小川オリンピック・パラリンピック準備課長","answer":"特優賃、いわゆる民間の借上型区民住宅についての方針ですけれども、借り上げ期間２０年間の満了後、オーナーと十分協議を進めながら。この工事ですけれども、予算特別委員会で同様のご質問をいただきまして、そのときは道路の埋設物が障害となっているため。オリンピックに向けて大会組織委員会が、一般的な国のバリアフリーの基準よりももう少し高い基準ということで示されておりまして。","voiceIndex":72,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"でも、この藤原の質問が、あそこと言えば、あそことわかるぐらい、もう何代にもわたってあそこの部分の要望をしてきたわけです。５０ミリの降水量でお水があふれてしまうわけですから。オリンピック・パラリンピック準備課長、まだ２０２０年、終わっていない後のレガシーという形でも、そろそろ確実に具体的にもっと考えていただかないといけないと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"和田河川下水道課長、今井住宅課長、小川オリンピック・パラリンピック準備課長","answer":"本件につきましては、平成２３年から工事概要を説明し、今に至っているという状況です。ご質問の借上型区民住宅の管理費ですが、確かにこの部分は返還に伴って低くなっておりますけれども、一方では。まさにオリンピック競技が行われるということで、そういった意味で付加価値もつきますので、区民のためのスポーツ振興拠点となるように。","voiceIndex":77,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"私は、１６０ページの道路橋梁費の中から道路安全施設費、１６２ページの受託事業費から下水道合流改善事業とあわせて、１６１ページの道路新設改良費の中の雨水流出抑制事業、同じく１６４ページの河川総務費の中の雨水流出抑制推進事業、それから１６８ページの都市開発費の中から観光まちづくり整備事業について伺います。","respondent":"多並道路課長","answer":"年間２０カ所ということで、これは実施計画に基づき現在進めているところです。それ以外の交通安全施設につきましては、予算編成等を行うときに、例年の中で、あとは警視庁から直してほしいとか、いろいろなご提案とか改善のご要望があります。","voiceIndex":82,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"要望がそれぞれ出て、それに対応できるという点についてはいいと思うのですけれども、もう少し計画性があってもいいのかなと。どのような関係各所が連携をとって進めようとしているのか、もう少し具体的に、ご要望があったときにお答えできるだけの情報をいただけるといいのですが、お願いします。","respondent":"多並道路課長","answer":"区としましては、実質は平成２７年度から平成３１年度までだと思いましたけれども、進めていく事業になっていますので、その中で、早くできるところはできるだけ短時間でやって、それ以外の例えば道路工事等、整備工事などがあるところについてはその中でやっていくとか。","voiceIndex":84,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ当事者のご要望をよく聞き取った上で、進めていただきたいと思います。次に、合流改善事業、雨水流出抑制事業、雨水流出抑制推進事業、合わせて伺いたいと思います。産経費の質問の中で、河川の水質についての質問に対して、水質の根本解決は合流改善事業であるという旨のご答弁でした。確認なのですが、改めて合流改善事業の意義、趣旨について、端的にお答え願えますか。","respondent":"和田河川下水道課長","answer":"合流改善事業というのは、下水道の中に汚水があるわけなのですけれども、それが急な雨が降った場合、合流ですから、水再生センターで処理できない分をどうしても河川に放流しなければならないという状況に東京都の下水道はあります。","voiceIndex":86,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"現に、東京都下水道局のホームページには、事業の効果的な推進に向けてという記述の中に、区と連携した雨水浸透ますの設置という記述が見られるのですが、治水事業も合流改善に役立つという私の考え方はいかがでしょうか。先ほど東京都下水道局になり代わってとお答えくださったので、ぜひこの質問についても、両方の立場でこのような連携は考えられないか、お答えいただけないでしょうか。","respondent":"和田河川下水道課長","answer":"その規模の事業を我々品川区の河川下水道課の職員が一生懸命頑張ってやっていること自体も、強く連携がとれていると私は認識しているものです。","voiceIndex":88,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"下水道」キャンペーンについての連携はないのでしょうか。もちろん川上の人だって油を流しているに違いないのだから、これは全体で取組まなければいけないのですけれども、例えば観光客が来たときに、事情がよくわからない人はやっぱり川下のほうの区の問題と見て、あの汚い白いぷかぷか浮いているものは何だということになるのではないかと思うのですが、その辺についての連携はいかがでしょうか。","respondent":"和田河川下水道課長","answer":"これは事実です。ただ、「油・断・快適！下水道」キャンペーンのイベントの中に品川区が入っていって、例えば先ほど言いました雨水タンクだとか雨水流出抑制助成のＰＲとかはやっておりますので、そういう意味では連携が図れていると考えています。","voiceIndex":90,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望です。は確認なのですけれども、下水道局は単体ディスポーザーの使用自粛を呼びかけています。多分やっていらっしゃるに違いないと思うのですが、確認させてください。それから、先日聞き忘れたのですけれども、公共施設の雨水タンクは中の水が使われてこそ下水に流れ込む水を減らすことになるので、その点、ちゃんと使われているかの確認をしていらっしゃるのでしょうか。その辺を教えてください。","respondent":"和田河川下水道課長","answer":"区内のディスポーザーの使用については、私は把握しておりません。申し訳ございません。それから、区有タンクの水を使っていただくということは、区有タンクを工事する際にその施設の方々にどのような使用方法があるかということをきちんと説明をして、やっているところです。","voiceIndex":92,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"私にとっては目黒川がすごく身近な川なので、その水質改善は本当に東京都と区民とみんな一丸となって取組む必要があるし、逆に言えば、それができることだと考えています。ぜひ進めていただきたいと思います。残りの質問は、時間がなくなりましたので、機会を改めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-040"},{"speaker":"沢田委員","kind":"確認","question":"１６２ページの商店街電線類地中化事業と、それからオリンピック・パラリンピック施設周辺無電柱化事業でお伺いします。そもそもこの事業ですけれども、どういった経緯で始められて、事業の概要、戸越と北品川だけ行ったと思うのですが、何年かかかりましたが、その距離と、そもそも事業費負担は、都と区と、また地域も若干あったかと思うのですけれども、どうなっていたのかを確認させてください。","respondent":"多並道路課長","answer":"戸越銀座からお話ししますと、平成１８年度から平成２７年度の１０年間で事業を進めてまいりました。距離が１,１８０ｍ、事業費は約３３億円です。","voiceIndex":96,"id":"exchange-041"},{"speaker":"沢田委員","kind":"意見","question":"平成１５年には先ほどお話があったように５０の商店街から聞いたということですけれども、やり終えて、どういった場所が適しているかということもわかったかと思うのですが、今後の考え方についてお聞かせください。","respondent":"多並道路課長","answer":"工事をやる際には、掘らなければいけないのですけれども、ただ、店舗を継続しなければいけないというところがありまして、実際には夜中、２４時間営業のところは大変だったのですが、それ以外のところでも夜中まで営業されている店舗もありまして、営業が終わった後。","voiceIndex":98,"id":"exchange-042"},{"speaker":"沢田委員","kind":"質問・要望","question":"これから先も、商店街の発展と地域の発展のために、しっかりとやっていっていただきたいなと思います。この電気、ガス、水道料は、電灯とか普通の水道だと思うのですけれども、区がこういうことを負担しているという状況について、どういうときに使われているのか、お聞かせください。","respondent":"溝口公園課長","answer":"今回の公園管理費の中の電気、ガス、水道料の内訳です。電気代が４,０００万円ほど、水道代が３,０００万円、残りがガス代になっているものです。使用につきましては、電気については、公園灯がありますので、そちらの電気が主なものになっております。","voiceIndex":100,"id":"exchange-043"},{"speaker":"沢田委員","kind":"意見","question":"そういったときも水道を使っているかと思うのですけれども、公園で電気がとれないということがよくあって、近所の方からお借りしたりとか、そういうこともあるのですけれども、水道は自由に使えているわけですし、電気もある程度、町会の方が使うとか地域の方が使うという場合に限って使えるような、例えば電灯のところに小さいコンセントをつけて、そこに鍵をしておけば、町会とかが使うときに使えるとか。","respondent":"溝口公園課長","answer":"そういったところを含めて、また改修の時期も見極めながら、どういった形で対応できるかを検討していきたいと考えているものです。","voiceIndex":102,"id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"私は、１６１ページ、道路改良費、同じく街路樹等維持管理費、１７０ページ、住宅費、時間があれば、１６０ページの道路空洞修繕について、伺っていきたいと思います。平成２４年第４回定例会の一般質問で、私も、防災上重要となる避難所周辺、病院周辺に隣接する区道の電線類地中化を優先的に実施すべきと求めました。","respondent":"多並道路課長","answer":"そこでやるためには、一番課題になりますのが、変圧器の置き場所が非常に困難になってきます。今、国がそこの研究に取組んでいるということですので、我々としてもそこを注視して、今後どのような整備ができるかというのをその中で見て、検討していこうという方向性です。","voiceIndex":105,"id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"研究の部分については国でもしっかり、当然財源的にもお願いしたいのですが、東京都としてこういう方向性が示されております。都の動き、また国の研究も含めて、避難所周辺、また、病院周辺に隣接する区道について優先的にやっていくということを積極的に今後も検討していただきたいと思いますけれども、改めてその方向性の確認と、それから都に求めるべき点が何かあれば、改めて伺いたいと思います。","respondent":"多並道路課長","answer":"国の今の動向をしっかり受けとめていくというのは１つですけれども、やはり東京都が無電柱化推進計画ということで定めて、特にオリンピック会場周辺で進めているのが今の流れです。","voiceIndex":107,"id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"１６１ページ、街路樹等維持管理費の視点で、街路樹の根っこが地上に張り上がってくる根上がりの対策について、伺っていきたいと思います。そこだけではなくて、区内いろいろ見てそういう箇所がたくさんあると思うのですが、そういう根上がりに対してどういう整備をされているかということと、１カ所修繕というか整備をするのにだいたいどのぐらいの費用がかかるのか、教えてください。","respondent":"多並道路課長","answer":"かむろ坂の桜につきましても、今の委員のお話のとおり、地元から、老朽したことで倒木等の危険性がある、または、桜祭りをする上で今後の継続的な部分も含めて維持管理をというお話がありましたので、本年度、樹木調査を行いまして点検をいたしました。","voiceIndex":109,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"街路樹そのものの管理も含めて、また道路の整備というところでしっかりと推進していただきたいのと、今１カ所当たり、根っこを切ったり何だりというのを含めて１５万円ぐらいと伺いました。そういう意味では、長い目で見たときに、そういう工法は非常に効果的ではないかなと思うのですが、同様の工法を区内で実施された事例があれば教えてください。","respondent":"多並道路課長","answer":"委員から今お話のありました工法につきましては、目黒川で実施した事例があるということです。ただ、今後につきまして、今のかむろ坂の件も含めて、植替え等のときに、目黒川の状況、効果を見ながら、やっていくかどうかもその中で検討していきたいと思っているところです。","voiceIndex":111,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"今、目黒川と言っていただきましたが、私が調べた中ではおそらく２０１３年２月にやった南品川近くの目黒川に隣接する山手通りに面している、そこかと思うのですが、この工法が使われているのは区内で、民間含めると８カ所やっているそうなのです。次に住宅費について伺っていきたいと思います。住宅確保要配慮者でありますが、この把握は住宅課としてできているのでしょうか、教えてください。","respondent":"今井住宅課長","answer":"住宅確保要配慮者につきましては、ひとり暮らし、高齢者、障害者等、多岐にわたりますので、それぞれの所管で数字を確認して対応をしているところです。住宅課といたしましては、今、区営住宅等で障害者の方も利用できる、車いすの方も利用できる世帯の戸数などを把握しています。","voiceIndex":113,"id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"過去にも質問させていただきましたが、国の目標として平成３２年度までに全区市町村に１００％設置をと言われている居住支援協議会の設置を、これまで私も、また区議会公明党としても繰り返し求めてまいりました。これについては過日、平成３２年度という国の目標に遅れることなく設置を検討していきたいというご答弁もある中で、改めてその設置を求めたいと思いますが、検討状況を教えてください。","respondent":"今井住宅課長","answer":"品川区におきましても、今、まちづくりマスタープランの中の住宅の部分について、来年度検討を進める予定ですので、その中で、先ほど申しました高齢者地域支援課等と連携しながら、大きな形での居住支援協議会を検討する予定です。","voiceIndex":115,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"国で目標としている平成３２年、ご存じのとおり、東京オリンピック・パラリンピックが開催されるということで、１年でも早く設置をしていただきたいという思いで、あらゆる区民の方が一丸となって世界中の方をおもてなしできて、また競技開催区である品川区で観戦できるという、そういう希望が持てる住宅施策をぜひやっていただきたいと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"１６５ページ、可動式ホーム柵整備助成、１６１ページ、視覚障害者用誘導タイル、１７０ページの崖・擁壁実態調査委託について、お伺いいたします。視覚障害者の方から、危険な駅のホーム、また道路を安心して歩けるようにしてほしいという願いがいつも届いております。可動式ホーム柵整備助成の８８６万６,０００円、これはＪＲ大井町駅でしょうか。働きかけはどこまで進んでいるのか、お伺いします。","respondent":"中村都市計画課長","answer":"これも品川区のホームの安全対策ということでの働きかけの成果だと認識しておりまして、大井町駅につきましては既に設置されておりますけれども、２０１６年が中延駅、それから、その後の計画につきましては未定ですけれども、２０２０年までに確実に設置をしていただくように。","voiceIndex":119,"id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"旗の台駅はいかがでしょうか。心身障害者福祉会館がありますし、昭和大学病院の利用者も多い旗の台駅は、早急な設置をすべき駅であると思っていますが、どのような働きかけをされてきたのか、お伺いするのが１点です。駅の安全確認をぜひしていただきたい。そして、ホームドアの早期設置と設置されるまでの駅員の配置、ぜひ働きかけをしていただきたいと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"そういった中で、現状では、例えばエレベーターの設置ですと、大分設備も密集しているということと、それから、ホームの大きさにつきましては、これも新たな土地の確保が必要だということで、こういったところは周辺の状況に応じて、これを念頭に置きながら、チャンスを……。","voiceIndex":121,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"危険な場所なのでホームドアをつけていただきたいというところの設置なのです。エレベーターとかではないです。","respondent":"中村都市計画課長","answer":"東急が２０２０年までという計画の中で検討を行っているですけれども、旗の台駅の３番線、４番線が平成３０年度、それから、５番線、６番線につきましては平成３１年度以降に行っていくと聞いております。","voiceIndex":123,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"駅の安全点検、協議の場、働きかけをしてほしいという点はいかがでしょうか。ぜひ協議の場を持ってください。","respondent":"中村都市計画課長","answer":"ホームの安全対策として区にできることといたしましては、ホーム柵の設置を急いでいただくということ、それから、それまでの間、人的対応ということで、これも鉄道事業者に働きかけを行っているところで、今そういった人的対応をしていただいているところでもあります。","voiceIndex":125,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"点字ブロック、そして音響信号とエスコートゾーン、これをセットで設置を求めているところなのですが、該当箇所はたくさんある中で、今日は、１つ、武蔵小山駅周辺の開発に伴って、通勤の経路が上手に通れなくなって不便になったという方から、ぜひ２６号線沿いの点字ブロックとエスコートゾーンと音響信号をあわせて設置していただきたいという願いがずっと届いているのですが。","respondent":"中村都市計画課長","answer":"警察のほうでも、今、計画的に整備は進めていきたいというところがあると聞いておりますけれども、区といたしましてもなるべく早急にそういった対応をしていただくようにお願いをしているところであり、引き続き、またお願いしてまいります。","voiceIndex":127,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"避難、救助について、避難情報発信伝達の方法ですけれども、２０１４年、以前の台風のところはパトロールをしたり、ポスティングをしたり、説明会、本当にご苦労してやってこられたご報告を受けましたが、今回の調査の後どのように周知を行っていくのか伺います。地域の現況の理解を深めるために、以前６地域で行った説明会などを繰り返す、丁寧な周知が必要ではないかと思いますが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"それからあと、地域への今後の説明についてですが、調査結果につきましては、全体的な見せ方と、あとは所有者個別のお知らせの仕方を考えていきたいというところと、東京都が区域指定を行うに当たって、当然ながら。","voiceIndex":129,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域の方は本当に心配が多いと思いますので、相談に丁寧にしっかり乗っていただきたいと思います。災害は起こらないことが一番なのですが、避難をしなければならないような状況になったときに速やかに避難ができるよう、避難準備情報などがしっかりと伝わっていくことが大事であると思っています。避難したくてもできない人の対策といった意味では、どういうふうになっているのか、お伺いいたします。","respondent":"鈴木建築課長","answer":"避難を呼びかけるエリアの方々へのお知らせの仕方ですけれども、平成２６年度、この呼びかけを開始したときに、事前の説明会、それから毎年、台風前に直接的な戸別訪問を行っております。","voiceIndex":131,"id":"exchange-058"},{"speaker":"あべ委員","kind":"質問","question":"私からは、１５９ページ、１６１ページの自転車駐輪場、自転車通行帯等について、それから１６７ページのまちづくりイベント、情報発信等委託、そしてそれに関連して、１６８ページの大崎駅西口交通広場、それから１７０ページの親元近居支援事業について、お伺いしたいと思います。それについて、区はどのように把握されて、受けとめているかということをお伺いしたいと思います。","respondent":"桑波田交通安全担当課長、今井住宅課長","answer":"五反田駅近くの山手通りの関係ですけれども、こちらは放置自転車がまだあるということで区でも情報は得ておりますけれども、そういった要望があれば、第二建設事務所へ連絡しまして。ただし、今私どもでアンケートをとりますと、やはりもともと引っ越しする予定があるとか、もともと三世代で近居する予定があったということで、定住促進というところでアンケートの結果は出ていないところです。","voiceIndex":135,"id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"自転車のほうです。警視庁あるいは警察庁でも、基本的には自転車は車道を通るということが法的にも明確になっているところですので、あそこの歩道、そもそも走れないところを自転車通行帯と指定するよりは、駐輪場ということも視野に入れて活用を考えられたらと思うのですが、いかがでしょうか。まちづくりイベント、情報発信等委託についてなのですが、この委託の支出先と内訳について、教えてください。","respondent":"桑波田交通安全担当課長、今井住宅課長、稲田都市開発課長","answer":"山手通りにつきましては都道でありまして、品川区内だけではなく、渋谷、新宿、板橋ぐらいまでつながっている道路でありますので。第１期の募集が２５件でございましたが、現時点でも２５件以上を上回っている中で、抽選で落選された方もいる現状から、今後も事業の展開を見つつ。その内訳ですが、１つは、大崎駅西口バスターミナル関連情報発信施設等整備業務ということで、８１１万５,１２０円。","voiceIndex":138,"id":"exchange-060"},{"speaker":"あべ委員","kind":"質問・要望","question":"引き続き検討をお願いしたいと思います。この件は以上です。一般社団法人と聞いておりますけれども、一般社団法人というのは、営利を求めないというだけで、これは民間事業者であるわけですよね。そうすると、特定の民間事業者に区の委託を、相見積もりや入札などもなく、毎年出し続ける形が、これは区の仕事の出し方としてどうなのだろうかと思うのですが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"一般社団法人大崎エリアマネージメント、大崎・五反田エリアマネージメントについての問いですが、大崎地区６０ヘクタールの緊急整備地域の都市再生ビジョンの戦略５というのがございまして、継続的なまちの発展をやっていくというところもありまして、これに基づきまして。","voiceIndex":142,"id":"exchange-061"},{"speaker":"あべ委員","kind":"質問・要望","question":"みんなでまちを盛り上げるという、その目的は非常にいいと思いますし、そうやっていただきたいところなのですが、今この団体がやっているのは、区有施設の管理と昔からやっているイベントの継続なのです。このためだけにこの２つの会社があるというのは、いつまでもこのような形であってはいけないのではないか。１点だけ。区の労務管理チェックが行われているのかも教えてください。","respondent":"稲田都市開発課長","answer":"エリアマネージメントの活動が見えてこないですが、設立されてから進めてきております。今後もより一層発展していくと考えております。","voiceIndex":144,"id":"exchange-062"},{"speaker":"渡部委員","kind":"質問","question":"１６０ページとか１６５ページの道路の維持費とか公園の管理費のところで伺いたいのと、あと、都市計画総務費なのですが、先に聞きます。実は、聞こうかなと思って調べていたら、地域交通検討会が決算書で上がっていなくて、予算書だと３８５万円とかの経費が上がっていたかなと思います。今後、必要があれば開催されるのかなと思っているのですけれども、そのようなことでよろしいのでしょうか。","respondent":"中村都市計画課長","answer":"ご指摘のとおり、喫緊の課題がなかったためです。今後、必要に応じて開催してまいりたいと考えております。","voiceIndex":147,"id":"exchange-063"},{"speaker":"渡部委員","kind":"質問","question":"あくまでも総合的な行政であって、事業者であって、地域をどういうふうにしようかというところですから、そういうことも何かのときに話題にでもなればなと思っていただけですので、会がないので、これは意見します。先に進みます。１６０ページの道路維持費と１６５ページの公園の維持管理とかの件で聞きます。","respondent":"溝口公園課長","answer":"委員お話のあるある点検隊です。これにつきましては、平成２５年度で終了としておりますが、全く止めたわけではありませんで、みどりの関係のボランティアの制度がありますので、そちらに統合して、やっているです。","voiceIndex":149,"id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"公園に関しては、そうやって民間の活用が結構あったと記憶していまして、今でもいろいろ利用者からの問い合わせの中で修繕に当たることがあると思うのですけれども、これが例えば道路ですと、先ほども根上がりの話とかありましたけれども、こういうところが危ないですよとか、やはりこれも地域の方からの問い合わせで直すことはあると思うのですけれども。","respondent":"多並道路課長","answer":"今、委員からお話しありました、いわゆる地元の方からのお問い合わせ等のお話かと思いますけれども、平成２７年度の実績で申しますと、８４５件のお問い合わせがあり、そのお問い合わせに基づいて現地の処置をさせていただいているところです。","voiceIndex":151,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"行政側も、これはこういうふうに直しましたよというフィードバックができるということを考えると、行政と区民との協働の観点からも、地域をどんどんきれいにしていこうという観点からも、非常に有用だと思うのですが、このような取組みに関して、どのようにお考えでしょうか。費用対効果もあると思いますが、できれば取組んでいただければと思うのですが、いかがでしょうか。","respondent":"多並道路課長","answer":"国の大きな動きの中で、ＩＣＴを使いながら、また見える化というのが大きな動きでもありますので、政令指定都市でやっていることが多いのですけれども、そういう広域な自治体でありますが、いろいろやられている事例を見ながら、区としてもよりよい点検のあり方。","voiceIndex":153,"id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"成果報告書の１６９ページ、建築行政の中で、建物の地震後の対策についてお聞きしたいと思います。そして、指定されていない地域をどうお考えになっているのかということをお聞きします。それから３つ目は、１６５ページの特定整備路線沿道まちづくり推進費なのですが、これは現状としてどうなっていますか。まちづくりという観点から、どういう動きが区民の皆様方の中で起きているのかをお知らせください。","respondent":"鈴木建築課長、東野まちづくり立体化担当課長","answer":"私から、まず応急危険度判定について、ご回答いたします。特定整備路線沿道まちづくりということで、私からは主にまちづくりが進んでいる戸越公園周辺地区についてのご説明をします。","voiceIndex":157,"id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"東日本大震災もそうです。ほかの地域について、品川区独自でできないのですか。それから、まちづくりについてですが、戸越公園はすごく進んでいるとわかっているのですが、ほかのところはどうですか。それと、今いろいろ話題になっていますけれども、お金がかかるという部分では、東京都の財源は大丈夫ですか。その情報があれば、教えてください。","respondent":"鈴木建築課長、寺嶋木密整備推進課長、中村都市計画課長","answer":"それからエリアにつきましては、基本的には品川区は木密地域が非常に広いエリアにかかっておりますので、それ以外、似たようなところについては。特定整備路線沿道の進捗状況、あと支援内容ですけれども、先ほどまちづくり立体化担当課長からご説明したのが戸越公園の周辺ということですが。予算については、限られたものですが、国や都の補助金を最大限に活用していきたいと考えております。","voiceIndex":160,"id":"exchange-068"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点目は公園管理費で、歳入の質問の途中でご答弁が最後時間切れになってしまったので、天王洲公園野球場、スタンドの外のベンチについて、雨が降るとプールのようにたまってしまうというところで改善を求める声が上がっていたのですけれども、これがどのように改善されたのか。この９月、大変雨が多かったですけれども、支障がなかったのかどうか。そのあたりについてお伺いしたいと思います。","respondent":"溝口公園課長","answer":"それにつきましては、今年７月にしっかり直させていただいたところです。その後、公園を管理している、また、雨の日に巡回等で見ている中で、雨がたまっているという事実はありませんので、今回改修したことによって、雨がたまるという事象は解消されたと考えているものです。","voiceIndex":165,"id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問・要望","question":"続きまして、１６０ページ、道路安全施設費。これもずっと追いかけております交通安全対策ゾーン３０について、変化がちょっとありましたので、幾つかお伺いします。しかも、品川区全体のゾーン３０を幾つか見ましたが、なぜかそこだけついているというところで、そこについて情報があれば教えていただきたいと思います。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０のシンボルマークの件ですけれども、これは当初、モデル地区についてそういった新しい表示を公告するということでつけ始めましたが、警視庁に問い合わせをした結果、今まで整備されている都内のゾーン３０について新しく。","voiceIndex":167,"id":"exchange-070"},{"speaker":"あくつ委員","kind":"確認","question":"時間がないので、続けて質問します。以前にも質問したことがあるのですけれども、あそこはたしか地域の反対があって、そもそも２０キロ制限の道路があり、これを地域全体を３０キロにしてしまうと、制限速度が上がってしまうので矛盾してしまう、こんな反対運動があったと思うのですけれども、この点をどういうふうに解消されたのか、その辺の経緯について伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０の周知につきましては、これからまたいろいろなキャンペーン等もありますので、警察署と連携しながら、また区のホームページ等も使いながら周知を図っていきたいと考えております。","voiceIndex":169,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０キロを守っている車自体、なかなかないですけれども。警視庁に地域からの要望、地域はそもそもそれができないと思っていると思いますので、その道だけではなくて、全体が４ｍ以下の非常に狭い生活道路でできている地域ですから、ぜひそこのところをお声がけというか、協議をしていただきたいと思うのですが、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０の新たな設置の要望ですけれども、道路、または住宅等、周りの環境はやはり年月が経つと変わってくるものだと認識しております。新たな場所の要望ということであれば、そちらは品川警察の管内になると思いますので、その旨は伝えていきたいと考えております。","voiceIndex":171,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問","question":"運行管理のノウハウというのは、そもそも機能として持っているのかどうか。たしか私、前の導入のときの質問で申し上げましたが、浜松町のバスターミナルの中でやっていた世界貿易センタービルが入るからそういうノウハウがあるのだというお話がありましたけれども、例えばそういうノウハウを持った方が常駐されているのかどうか、その辺についてお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"大崎エリアマネージメントの現在の事務局職員は、事務局長を入れて５名、パート職員等を入れて全部で７名です。","voiceIndex":173,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"バス事業者に協力を求めているということでありました。高速バス業界では最大手で、その業界の会長をやっているとも伺っております。これが、前にも私、質問したことがあるのですけれども、全国で２３ですか、国土交通省の法律に基づいてできている一般バスターミナルのうち、ほとんどが株式会社がやっているのです。ここは区の見解を伺いたいと思うのですけれども、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"ただ、現在も東急バスや京成バス、先ほど言われましたけれども、一部、千葉交通等も入って運営しています。私どもの考えとしましては、一社独占でそのバスターミナルを使用するという区の考えは全くございません。","voiceIndex":175,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区のお考えは今わかりました。例えばこの前開業した、２５番目にできたバスタ新宿、規模が全然違いますけれども、あそこは最初からいきなり１０社以上入っているわけですよね。そういうところで、あらぬ誤解を受けぬように、ぜひそこは門戸を広く開いていただきたいということを重ねて申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問","question":"１６６ページのしながわ水族館のことを伺います。この委員会でも、それぞれの委員からいろいろ質疑があったかと思います。そんなことで、この決算、平成２７年度の来場者、増えていると聞いています。これまでの質疑でもありました。平成２７年度に限った来場者は、増えているかと思うのですが、その要因をお知らせください。実数をとるのは難しいけれども、その辺の感覚的なものも教えてください。","respondent":"溝口公園課長","answer":"しながわ水族館の平成２７年度の来館者数につきましては、５３万１,６４９人が実績で上がってきている数字です。","voiceIndex":179,"id":"exchange-076"},{"speaker":"渡辺委員","kind":"質問","question":"来館者数、少し前に決算特別委員会、予算特別委員会で聞いたとき、たしか５０万人の大台を超えていなかったような気がしたのですが、前年比では大幅に増えられたのかなという気がします。それと、この成果報告書にある項目で、区内ＰＲイベントと水族館おもてなし事業、これも主なものだけでいいので、どんな取組みで、どんな成果があったか、教えてください。","respondent":"溝口公園課長","answer":"平成２７年の実績として上がっているものですが、一つ大きなものとしては、水族館とパン屋がコラボしたご当地パンを決定するイベントを開催しております。そういったものを行いながら、平成２７年度も集客を図ってきたというのが実績として上がっているものです。","voiceIndex":181,"id":"exchange-077"},{"speaker":"渡辺委員","kind":"質問","question":"そもそもの設立の目標の１つに、教育施設であると。これは感想です。ですから、この２５周年、すごく心から応援すべきことだと思いますし、肝心なのは今後のことです。ちょうど１つ、桟橋という中で、各委員会や私ども会派でもよく研究をしているところなのですが、桟橋の活用、ただ桟橋だけではもったいないですし、人も来ない。その辺で、桟橋をどう活用していくのか、これが１つ。","respondent":"溝口公園課長","answer":"ですから、しながわ水族館だけでなく、しながわ区民公園に立地しているという特性を活かして、公園と一体となった形での集客力向上もあわせて検討していきたい。","voiceIndex":183,"id":"exchange-078"},{"speaker":"渡辺委員","kind":"質問","question":"そしてもう１点伺いたいのがアクセスです。ラッピングバスも含めて、非常に話題性も出るのではないか、複合的な効果があるのではないかという意味で、アクセスについての検討幅といいますか、それを伺えればと思います。この期間だったら、インパクトのある優待ができるような、そんな仕掛けがあってもいいのかなと思うので、この２点を伺いたいと思います。","respondent":"溝口公園課長","answer":"そういった諸条件、または売り上げ、または入館者数の動向、そういったものも含めまして、今後どういう形でさらに集客アップを図っていくのか、そういったところは引き続き、サンシャインとともに検討していきたいというふうに考えているものです。広く区民へのサービスです。","voiceIndex":185,"id":"exchange-079"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１６３ページの橋梁長寿命化修繕経費と、１６８ページの品川駅南地域周辺まちづくり事業と、天王洲地区まちづくり検討委託についてお伺いをいたします。その理由は、無電柱化と同じですけれども、１つは景観です。以上、３点の理由から、そうした老朽化した歩道橋は、修繕するのではなくて、いっそのこと横断歩道に変えるべきかと思われますけれども、その点についていかがお考えでしょうか。","respondent":"多並道路課長","answer":"いろいろな要因がある場合がありますので、そういう場合は、まず現場でその状況を見させていただきまして、撤去の要件として、東京都が基準を持っておりますので、それを準用する形で、例えば利用者の数だとか、近傍の状況、また、交通管理、いわゆる警視庁との協議とか。","voiceIndex":188,"id":"exchange-080"},{"speaker":"筒井委員","kind":"質問・要望","question":"様々な、そうした手続き的な条件とか、交通上の条件がありますけれども、ぜひとも変えるべきところは変えていっていただきたいと考えております。最近行った、変えている場所があるとお聞きしたのですけれども、具体的に、改めて最近、歩道橋から横断歩道に変えた場所と、今後、具体的にどこを行っていくのかということをお聞きしたいと思います。","respondent":"多並道路課長","answer":"要するに、歩道橋があるのですけれども、実質、そこの地域の方々が下を通るような形で、逆に危ない状況があるというお話があったもので、警視庁ともよく協議いたしまして、まず横断歩道を新たにそこの下に設置して、その後、来年度になりますけれども、撤去をするという形に。","voiceIndex":190,"id":"exchange-081"},{"speaker":"筒井委員","kind":"質問","question":"特に、品川駅南地域まちづくりビジョンの基本戦略１に、国内外からの来街者を迎え入れるということになっておりますけれども、この品川新駅に多くの来街者をとられてしまうという、こちら側に来ていただけないという恐れがありますので、ビジョンでも品川駅との連携等ありますけれども、さらに進めて、この品川新駅を抱き込んで、品川新駅との連携、港区との連携をかなり強化しまして、そうした町の活性化。","respondent":"東野まちづくり立体化担当課長","answer":"今後、品川駅南地域にあります品川浦ですとか、歴史景観を持ちました旧東海道、こういった固有の魅力を国外の方にも発信していけるようなまちづくりについて、取組んでいきたいというふうに考えてあります。","voiceIndex":194,"id":"exchange-082"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも、品川駅南地域と、時間がなかったので質問できませんでしたけれども、天王洲、ぜひとも品川区の持続的発展、活性化のためには非常に重要な地域だと考えておりますので、さらに品川区としても、行政としても、しっかりと推進のほうをお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１６５ページの特定整備路線沿道まちづくり推進費にかかわって、補助２９号線などの特定整備路線について伺います。東京都が強硬に事業を進めています。しかし、いまだに改めていないのではないでしょうか。改めて、強硬なやり方はやめるよう、東京都に求めていただきたいと思いますが、いかがでしょうか。なぜ繰り返されるのか、原因を伺います。","respondent":"中村都市計画課長","answer":"そういった様々な権利者様の状況に応じて、丁寧な対応、そして十分にきちんと理解をしっかりとしていただく、大切な財産の話ですので、そういったところを東京都のほうにもお願いをして、東京都のほうも当然、引き続き丁寧な対応を継続していくです。","voiceIndex":198,"id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"失礼のないように注意しているということですけれども、この息子さんの連絡先、一緒に伺いたい人もいらっしゃるというお話もありましたけれども、この方は、１人でずっと頑張ってきて、別に息子さんに聞いてほしいと、そういったことを言っているわけではありません。そして、この強硬な姿勢が繰り返されている原因を伺いましたので、しっかりと答弁いただきたいと思います。伺います。","respondent":"中村都市計画課長","answer":"そうは申しましても、大切な財産の話ですので、東京都のほうには、そういうお話もいただいているということはお伝えをして、東京都のほうはしっかり対応しますです。","voiceIndex":200,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"区では承っていないということですので、ぜひ、そういう状況も把握するように努めていただきたいと思います。そして、この強硬な姿勢が繰り返されている原因を伺いましたので、ぜひ、ご答弁いただきたい。そして、区民が都の対応に不安に思っているということを、都が認識しているかということもお聞きしましたので、改めて伺います。","respondent":"中村都市計画課長","answer":"区のほうからそういうお話をお伝えしたところ、東京都のほうも、そういったことであれば、さらに気をつけるようにしますというお話はいただいておりますが、ただ、その中で、お話をした後は、そういった認識を持たれる方もいるのだなという。","voiceIndex":202,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"東京都も気をつけていくということですけれども、具体的に何をしていくのか、やはり不安を与えないように、区からも強く求めていただきたいと思います。住み続けたいわけですから、相談したいわけではないのですね。６月の議会で私が聞いたときに、区は、事業に協力をいただく権利者の方々に対して不安を与えることがないよう求めていくと答弁されました。伺います。","respondent":"中村都市計画課長","answer":"区が東京都にお願いすることは、一部の方だけではなく、その権利者全ての方に丁寧な対応をしていただきたいというふうに考えております。","voiceIndex":204,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の考えはわかりました。都にもしっかりそのことを伝えていただいて、都が、そういう全ての人を対象にしてやっていくように求めていただきたいと思います。そして東京都が、改めてまた強硬な姿勢に出ているという、都の担当者の方が、態度が急変したということも聞いておりますので、その改めて変わった理由、都から聞いていれば伺います。","respondent":"中村都市計画課長","answer":"特に聞いてございません。","voiceIndex":206,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"このパンフレットに火事の写真がありますけれども、これは阪神・淡路大震災のときのものだと思いますが、当時は無風状態でしたが、それでもこの火災が発生したのは、２０ｍ道路がなかったからですか。火災発生時の主な原因を伺います。そして、このパンフレットは何枚配られて、幾らかかったのか、期間はいつからいつまでで、何世帯に配布したのか伺います。","respondent":"中村都市計画課長","answer":"火災の原因としてはそういった原因ですけれども、この道路があったかなかったかというところでは、延焼遮断帯としての幅広い道路がなかったために、延焼が広がったということはあるということで、今、東京都では、都内の延焼遮断帯形成のために特定整備路線を定めて。","voiceIndex":208,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"この火災の発生を防いでいくことが一番重要だと思います。このパンフレットの写真を見ると、１４階建てぐらいでしょうか、マンションよりもさらに２倍、３倍の高さまで炎が立ち上がっています。こうなってしまったら、上昇気流が発生し、６００ｍ、７００ｍの飛び火の可能性があります。道路ができても完全に延焼をとめることはできないと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"今、東京都が進める木密１０年プロジェクトの中では、この延焼遮断帯の形成だけでなく、街区単位での建物の不燃化、こういったものと合わせて効果が出るとしております。","voiceIndex":210,"id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"複数のことでやっていくということですけれども、木密地域が解消されれば、この延焼遮断帯は機能が無用になってしまいます。やはり、この火災の発生を防いでいく、このことが一番重要だと思います。この方は移動するのも大変な方で、この土地を離れたら、地域の絆も断たれ、孤立し、死に追いやられる可能性もあります。区民を路頭に迷わせるこの計画は撤回すべきです。改めて伺います。","respondent":"中村都市計画課長","answer":"区といたしましては、この品川区が災害に強い町となるよう、燃えない町、燃え広がらない町になるように、防災性の向上に引き続き努めていくために、東京都と連携して、特定整備路線を進めていきたいと考えております。","voiceIndex":212,"id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"品川の特定整備路線についても、地域の方からの反対など、町を壊すこの計画は、見直していくべきだと思います。東京都から、見直しについて、話があったかお聞きしたかったですけれども、ちょっと時間がないので、ぜひ、こういった情報もつかんでいただいて、見直していくようによろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-092"},{"speaker":"本多委員","kind":"質問","question":"成果報告書の１６１ページ、細街路拡幅整備事業、２つ目が１６７ページの都市開発費について、質問します。最初に細街路拡幅整備事業なのですが、４２条２項道路の４ｍ拡幅が、品川区全域でどのくらい進んでいるのか、現時点の状況をお知らせください。","respondent":"鈴木建築課長","answer":"細街路の事業は、昭和６３年から開始しています。これまで、累計延長９４.７kmでございまして、対象とする全延長に対して約３４.６％の進捗率です。","voiceIndex":216,"id":"exchange-093"},{"speaker":"本多委員","kind":"質問・要望","question":"長年、これに取組んでいただいて、議会でも十分議論を尽くしてきましたけれども、さらに進めていただきたいと思うのですが。その辺の状況をつかんでいるのか、また対応等、どうなっているかお聞かせください。","respondent":"鈴木建築課長","answer":"ただ、昭和６３年から行っている事業でございまして、平成５年、あるいは６年、７、８年、１０年、しっかり後退いただいた後に、例えば５、６年、１０年後にブロック塀をつくってしまったというところは、声としては届いておりまして、そういったところは日々のパトロール。","voiceIndex":218,"id":"exchange-094"},{"speaker":"本多委員","kind":"質問・要望","question":"確認次第、そういった指導を進めていただきたいと思います。それで昨今の、例えば４ｍに満たない所を拡幅してください、今までは建替えの時期にされておりましたけれども、ニーズがさらに強いと思うのですね。それを、すごく食いついてくる方に対しては、対応をしているケースもあるのではないでしょうかね。そういった、最近のそういう動向というのですかね。その辺の現状について、どうなのでしょう。","respondent":"鈴木建築課長","answer":"事業を開始した当時、私も１担当としてこの事業に携わりましたけれども、やはり路線として、当時は、後退したお宅が路線、あるかないか。建築主のところに訪ねていっても、なぜ自分だけが下がらなければいけないのだという声が、当時は多かったです。","voiceIndex":220,"id":"exchange-095"},{"speaker":"本多委員","kind":"質問","question":"引き続きよろしくお願いします。それで、細街路ではないのですが、こういう場合はどうかなというのを１つお聞きしますが、４２条２項道路も含みますし、４ｍをもう確保している道路も含みますが、例えば大きい敷地が建替えて、空地というか歩道ができました。だけれども、その先は行き止まりになってしまう。そういったところを促す、指導はできないと思うのですが、促すということはできないのでしょうか。","respondent":"鈴木建築課長","answer":"ただ、区としては、建替えだけではなく、いろいろな個別個別のケースに合わせて対応はしていきたいというふうに考えてあります。","voiceIndex":222,"id":"exchange-096"},{"speaker":"本多委員","kind":"質問","question":"わかりました、よろしくお願いします。次の質問に行きます。１６７ページの都市開発費、五反田地区コーディネート業務委託、この内容についてお知らせください。","respondent":"稲田都市開発課長","answer":"目黒川桜植樹に向けた検討、それから目黒川の周辺のコインパーキング提携に向けた整備計画の検討等を行っております。","voiceIndex":224,"id":"exchange-097"},{"speaker":"本多委員","kind":"質問・要望","question":"当然、その鉄道事業者、所有者で建てるのは自由な権利があるわけですから、行政としても所有者の建築主どおりに了解すると思うのですが。ただ、地域としては、これまでの経緯もあって、駅も含めて、西口・東口一体的に整備をという要望、意見もありましたので、その辺の区の見解をお聞かせください。","respondent":"稲田都市開発課長","answer":"こちらも付近とのまちづくり、周辺とのまちづくりと合わせた検討、それから西口との連絡等々についても一緒に検討しようというところで話をしてきたところだったのですけれども、今回、ＪＲのほうが。","voiceIndex":226,"id":"exchange-098"},{"speaker":"本多委員","kind":"質問・要望","question":"計画はわかりました。今後のまちづくりを進めていく中で、駅が先行して整備される、それを受け入れて、今後の整備をしていくという、地域のことが後退しないように、ぜひ今後とも進めていただきたいと思いますが、その点についてお願いいたします。","respondent":"稲田都市開発課長","answer":"五反田地域です「五反田駅周辺にぎわいゾーンまちづくりビジョン」というのもまとめております。現在、東口のほうでは、再開発に向けた勉強会等々の地区もあります。そういう中におきましては、駅を挟みながら、まちづくりに向けてやっていくという考えです。","voiceIndex":228,"id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に１つ要望して終わります。五反田駅の、目黒駅寄りに出入口を整備をしていただきたいと思いますので、申し入れをお願いしたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"１６８ページの不燃化１０年プロジェクト、ちょっと前後しますが１６４ページの水辺利活用についてお伺いしたいと思います。私もそういうことは、常日頃感じていた中で、先だっての建設委員会で、この駐輪場について、現状のいろいろな課題についての改築をしていくというようなことが報告されましたけれども、この改修について、どのような改修となっていくのかをお伺いしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"来年度は、大森駅水神口に地下の駐輪場ができますので、その後は上部のほうも合わせてそういったものに対応できるようにやっていく計画を立てておりますので、順次整備を進めていきたいと考えております。","voiceIndex":232,"id":"exchange-101"},{"speaker":"塚本委員","kind":"質問","question":"今の整備はやはり必要だなとも思うのですけれども、そういった、今までよりもちょっとスペースを、１台１台多目にとっていくということは、台数的に、今の収容台数が減ってしまうということが、ちょっと懸念、心配になるのですけれども、その辺というのはどういうふうになっていくのか。うまく現状の駐輪台数を確保できるような形で考えていただけるのかをお伺いします。","respondent":"桑波田交通安全担当課長","answer":"場所を広げることによって、駐輪台数は若干減るものと認識しております。それでも、駐輪場の場所によっては、まだ使っていないスペース等もありますので、そういった所も有効に活用しながら、なるだけ駐輪の数を減らさないようにしていきたいと思います。","voiceIndex":234,"id":"exchange-102"},{"speaker":"塚本委員","kind":"質問","question":"こういういろいろな通行のあり方というのは、この自転車レーンが整備されていく中で、横断歩道のそういった通行の自転車レーンがなくなっていったりする中で、どういうふうに整理していくというか、どういうあり方というのが望ましいというのですかね。こういうのをちょっとやはり、そろそろ新たにしっかり普及していく、啓発していくという必要があるかなというふうに感じておりますが、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"自転車につきましては、昨年、道路交通法が改正されまして、いろいろな罰則等も強化されておりますので、この辺はまたいろいろ警察署とも連携をとりながら、正しいルールのマナーの周知、もしくは違反をさせないような広報について努めていきたいと考えているところです。","voiceIndex":236,"id":"exchange-103"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっと細かいところ、私も勉強不足なところもあるので聞きたいのですが、自転車は、横断歩道、歩車分離のときに、歩行者の信号で渡るとき、これは本来は歩いて渡るものなのですか。それとも、乗って渡ってもいいのか。この辺というのはあまり厳密にするところではないのかもしれないのですけれども、一応、原則論としてはどうなのかを確認させていただきたいと思います。","respondent":"桑波田交通安全担当課長","answer":"横断歩道、青になれば、信号、車両の信号も青となっておりますので、青信号に従って、そのまま乗っていただいても結構です。失礼しました。歩車分離の場合は、こちらのほうは、押して渡っていただくようにお願いいたします。","voiceIndex":238,"id":"exchange-104"},{"speaker":"塚本委員","kind":"質問・要望","question":"一応、わかりました。ここの、不燃化１０年プロジェクトの中の除却費用、この執行率だけ見ると、予算に比べて４７％ということで、半分にちょっと届かないというような状況になっておりますけれども、この除却費用の状況、これについて今、この執行状況について、ご説明いただきたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"ただいま委員からご指摘いただきましたとおり、執行率は４７％となっておりまして、当初予算に比べまして約半分ということなので、大変厳しい状況だという認識は持ってあります。","voiceIndex":240,"id":"exchange-105"},{"speaker":"塚本委員","kind":"質問・要望","question":"非常にこれ、木密地域の不燃化というか、燃えにくい町にしていく上で大変大切な事業かと考えていますけれども、幾つか新しい事業というのですか、この平成２７年度、今までとは違う角度での除却というのも始まっているかなとも思うのですが、そういったところで何かありましたら、ご紹介いただければと思います。","respondent":"寺嶋木密整備推進課長","answer":"今後も引き続き、取組みを強化してまいりたいと考えております。","voiceIndex":242,"id":"exchange-106"},{"speaker":"塚本委員","kind":"意見","question":"今後とも一層の取組みをお願いしたいと思います。Ｔ.Ｙ.ＨＡＲＢＯＲだとか、目黒川のことですとか、こういったことを１つ１つ取り上げて、写真に写して、大変に評価をされておりました。今回、いよいよ舟運社会実験ということで、新たな取組みを開始するわけですが、今後のこの品川区の水辺の展望につきまして、ぜひお一言、最後にいただければと思います。","respondent":"和田河川下水道課長","answer":"注目されている景観を生かしてやっていきたいわけなのですけれども、舟運というところでお話ししますと、区としましては、区内の桟橋のみならず、区内の桟橋と結んだ多くのルートを事業者に開発していただいて、地元事業者を中心に。","voiceIndex":244,"id":"exchange-107"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、１６０ページの大井町駅イルミネーション、１６４ページ、河川、運河水質改善、１６６ページのしながわ水族館、時間があれば１６０ページの道路の維持管理について、それぞれお願いします。質問に入る前に、先ほど我が会派のあべ委員からの大崎駅西口のバスターミナルから成田に行く格安バスについて、区はどのような見解を持っているのかということを、まずご答弁いただければと思います。","respondent":"稲田都市開発課長","answer":"大崎駅西口バスターミナルから成田国際空港まで、１０月３１日開通するです。これにおきましては、このバスターミナルを活用して、成田空港からの旅客を大崎に引き込むというところで、大崎の観光、また品川区内部への観光というところで、非常に期待しています。","voiceIndex":247,"id":"exchange-108"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"できたら安全性についてもご答弁いただければと思いますので、よろしくお願いします。それと川の水質改善ですが、東京海洋大学で、使い捨てカイロを再利用してヘドロを分解しにおいを減らす鉄炭団子というのですかね、これを使った地域連携を始めたという報道がありまして。よろしくお願いします。","respondent":"多並道路課長、和田河川下水道課長、溝口公園課長","answer":"１６３件の方の意見としては、駅前がきれいに見えた、またその次として、明るくなったと、非常にご好評をいただいたところで。水質改善の実験についてのお話ですけれども、東京海洋大学のお話の実験については、これは目黒川ではなくて。","voiceIndex":249,"id":"exchange-109"},{"speaker":"石田（し）委員","kind":"意見","question":"イルミネーションですけれども、目黒区が目黒川で青の洞窟をやったときに、あまりの人の多さに中止になってしまったといった中で、やはり、町の活性化というのは、これは１つ目的としてあるのだと思うので。僕は、どうせやるのだったら、どーんとやらないと、なかなか注目も、来てくれた人はきれいだねというふうに言ってくれるかもしれないですけれども、ではそれを知ってくれる人がどこまでいるのか。","respondent":"溝口公園課長","answer":"引き続き、皆様に楽しんでいただけるような、また水族館に来てお食事をしてもらえる、そういったところのメニュー開発というのは、サンシャインのほうでいろいろ考えながらやっていくというふうに考えておりますので、品川区といたしましても。","voiceIndex":253,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"私は成果報告書の１６０ページ、道路維持費に関連をして、それから１６６ページ、しながわ水族館に関連をして質問します。先に道路維持のほうですけれども、これは品川区役所の入り口の件です。例えばゼブラゾーンを設けるとか、それからカーブミラーを設置をするとか、何らかの形で、所管する警察とも協議しながら対応すべきだと思うのですが、いかがでしょうか。ご答弁をお願いいたします。","respondent":"多並道路課長","answer":"その進捗の中では、平成３１年度には立体の工事が全部終わって、その後、道路整備という形になってきますけれども、その間、大井町線の立体の工事の中で、幾つか仮で脚を盛り変えながらやっていく形が出てきますので、今の委員のご指摘も含めながら。","voiceIndex":257,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問","question":"だから、長期的にはそういう対応でいいのかもしれないけれども、短期的に考えたならば、そういう、確か消防署の前にゼブラゾーンを設けた、ちょっと記憶があるのですけれども、それがあそこにできるかどうかは別問題としても、要はそういった形で区役所入口だということをわかってもらえるようにして、いつも車がある程度、空くスペースがあれば、非常にスムーズに入れると思うので、これは。","respondent":"多並道路課長","answer":"ただ、全体的な工事の中でもありますけれども、工事の中でやりながら、今の点も踏まえて、すぐできることは検討というところで、そういう形で進めていきたいと思っているところであります。","voiceIndex":259,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問・要望","question":"現場って、毎日見ているわけですよね。それから、前にも指摘をさせていただいたのですけれども、鈴ヶ森の大経寺のすぐ近くに陸橋があって、その下にホームレスの方々が、住んでいると言ったらいいのですかね、自転車を置いて、そこにいる。なので、品川区と協議をしていただいてやってもらった記憶があるので、ぜひそういうのをもう１回やっていただきたいと思うのですが、いかがでしょうか。","respondent":"多並道路課長","answer":"委員の今のご指摘のところ、国道敷も含めながらのところですけれども、国と連携を図りながら、しっかり対応していきたいと思っているところです。","voiceIndex":261,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問","question":"前にやっていただきましたように、ぜひよろしくお願いいたします。それからしながわ水族館です。「水族館ガール」、私は毎回見て、録画もして、すごく感動したのです。先ほど渡辺委員もお話しされていましたけれども、同じところで質問します。だからドラマの効果に乗って、そして集客力をアップすることは、決して間違ってはいないので、そのことの見解は、まずいかがでしょうか。お答えをください。","respondent":"溝口公園課長","answer":"様々な形で、今回、撮影に使っていただいた「水族館ガール」の効果、そういったものも使いながら、集客力、集客を図っていきたいというふうに考えているものです。","voiceIndex":263,"id":"exchange-114"},{"speaker":"伊藤委員","kind":"意見","question":"だから、確か入口に大きなイルカのモニュメントがありました。だから、これを、もっとわかりやすく、しかも、１年間を通して多くの方々に、ああ、この水族館はイルカもいるんだ、ペンギンもいるんだということをわかりやすくすれば、先ほどほかの委員から指摘があったようなわくわく感が広がって、そういう可能性が高くなっていくことは間違いないので、そのことの考えをお聞かせください。お願いいたします。","respondent":"溝口公園課長","answer":"見づらいということで、工夫はしていますが、さらに皆さんがわかりやすい、または記念写真を撮って有効なものになる、そういったものを目指して、さらに改善、どういう形ができるのか、検討していきたいというふうに考えているものです。","voiceIndex":265,"id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから今度、主演の松岡茉優さんが、１日館長として来館されることも聞きました。だから、こういうことのＰＲももっとすべきだと思うのですよ。恐らく、サンシャイン水族館と連携しているとは思うのだけれども、「水族館ガール」と合わせて松岡茉優さんが来る、それを多くの方々にＰＲをしていただいて、水族館に来ていただくきっかけをつくっていくというふうに検討すべきと思うのですが、いかがですか。","respondent":"溝口公園課長","answer":"それにつきましては、サンシャインとも連携して、今までも取組んでいるところではありますが、しっかり、こういうものをやっているということを広く知ってもらう、そういったところの観点で、さらにＰＲには努めていきたいというふうに考えているものです。","voiceIndex":267,"id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"款が違いますから提案だけしますけれども、例えばこういうイベントの情報というのも、前に話をさせていただいた、観光振興協議会等と連携をした上で、１つのデータベースに載せていけば、多くの方の目に触れて、結果として全ての方々がいい関係になるわけでありますから、それは連携して対応するようお願いいたします。やはり、もっと品川区が主体的に売り込んでいくべきだと思うのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"これまで２５年間培ってきたものも、実績とともに、皆さんにお披露目できる、そういった機会を、観光部署と連携しながら、表に出せるような機会、そういったものを検討していきたいというふうに考えているものです。","voiceIndex":269,"id":"exchange-117"},{"speaker":"伊藤委員","kind":"質問","question":"ほかの委員からもありましたけれども、しながわ水族館というのは品川区の観光にとって、とても大きな魅力ある施設ですよ。非常に駅から近いところですから、そういうところを十分活用して、品川区の観光行政に大きく貢献していく施設だと思うので、最後にこれからのしながわ水族館の方向性だけ、ちょっとお答えください。お願いいたします。","respondent":"溝口公園課長","answer":"ただ、一方で施設の老朽化、そういったものも進んでいくところではあります。入館者数の推移、そういったものもしっかり見極めながら、しながわ水族館の今後をどうあるべきかというものを、しっかり詰めて考えながら運営していきたいというふうに考えているものです。","voiceIndex":271,"id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"意見","question":"１５９ページ、交通安全啓発費か、道路安全施設費。それから、１６８ページの観光まちづくり整備事業の大崎駅西口交通広場整備工事についてです。先に、大崎駅西口交通広場整備工事の方をお尋ねします。昨年１２月から運営を開始し、今月の末には、先ほどもありましたが、成田空港へと直結する高速バスがスタートして、今後も利便性に注目が集まっていると。","respondent":"稲田都市開発課長","answer":"それを合わせますと１６５便が１０月３１日からは出発するという形になります。そのほかの予定ですが、東急バス、京急バスが、大崎駅西口バスターミナルから羽田空港までの便を、現在、国のほうへ路線認可を申請しているという情報を聞いております。","voiceIndex":274,"id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"かなり多くの便が出ていると、今、数字を伺いました。ところで、大井町というのは、いろいろな区のほうの方針で、品川区の中心という位置づけで、大井町活性化協議会という地域の方々も、知恵とお金を出し合って、私もいろいろ熱意あるお話を伺うことが多く、頭の下がる思いであります。たびたび、議会でも早期完了を求めていますが、いろいろなことがありまして、時間がかかるというふうに思われます。","respondent":"中村都市計画課長","answer":"したがいまして、この辺は、バス事業者と慎重に検討してまいりたいというふうに考えております。","voiceIndex":276,"id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、羽田のお話もありましたけれども、運転本数は概ね１時間に１本程度というふうに伺っています。そうすると、今、区民の方の利便性のお話をしたのですが、大崎と大井町を結ぶという限定の意味において、コミュニティバスというふうにお話ししたのですが、今度は大崎に着いたお客様が、今、１時間に１本というのはなかなか厳しい。もちろん、時間が合えば利用していただくのですが。改めてご見解を伺います。","respondent":"中村都市計画課長","answer":"先ほども申し上げましたが、バス事業者とその辺は協議をしなければいけない、また採算性の問題もありますし、そういったところからいきますと、慎重な検討が必要だというところで、引き続きそういった考えで、バス事業者のほうには。","voiceIndex":278,"id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それで、あそこは、品川郵便局の車や、あるいはきゅりあんの駐車場から出てきた方がＵターンするので、あそこは右折が非常に多いのですが、右折の信号はついていないということなのですが、ここについて、赤で曲がらなければいけないので、非常に危険な状況なのですが、そちらについて、安全性と円滑な運行のために、右折の信号をつけてほしいというご要望があるのですが、その件についていかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"きゅりあん前の信号の関係ですけれども、信号機については、各交通量、こういったものに勘案して、サイクルもしくは表示等を設置しています。今の場所につきましては、ちょっと現場のほうを見まして、対応させていただきたいと考えております。","voiceIndex":280,"id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１６５ページのやさしいまちづくり整備費に関連して、駅のバリアフリーについて、それと１７０ページの家具転倒防止器具について伺いたいと思います。これが、新馬場駅ですね。この要望の中で、区が管轄というか、区のやるべきところというところでは、入口の歩道の傾斜、それと駅入口付近の和式トイレ、この改善が現在どうなっているのか、検討などされているのか、伺いたいと思います。","respondent":"中村都市計画課長、溝口公園課長","answer":"エレベーターにつきましては、区も、駅のホームが長いという、こういった状況は、駅の成り立ちからそういった状況になっているというところで、これは鉄道事業者である京浜急行電鉄株式会社のほうも認識をしております。そういった中で、今回の委員ご指摘のトイレについても、その中でどのように取り扱っていくかということは考えていきたいというふうに考えているものです。","voiceIndex":284,"id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"北口と南口、同じ運賃なのにこれだけ格差があるということで、町のにぎわいにもマイナスになるということで、地域の皆さんは求めています。先ほどの、ほかの委員からの質問で、大井町線は２０２０年までにホームドアが全駅設置されるということです。京急はどういう状況なのかを伺いたいと思うのですが。区からの、こうしたホームドアについての働きかけもどのようになっているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"京急のほうにも、当然のことながら、このホームドアの設置についてはお願いをしています。","voiceIndex":287,"id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１つの駅にワンルート、バリアフリーがあると言われても、あそこは２つの駅というふうに考えてもおかしくないほど離れている駅ですので、ぜひバリアフリーを進めていただきたいし、鉄道をはじめ、品川区は便利だと、先ほどからお話もあります。利用が広がらない原因は、区はどのように考えているのでしょうか。昨年が１件ということで、今年は広げるための対策は打たれたのかどうか、伺いたいと思います。","respondent":"今井住宅課長","answer":"初めに、実績に関してですけれども、平成２７年、そして現時点でも１件ずつという状況です。私ども、やはり、高齢者、障害者の皆様につきましては、高齢者地域支援課で一定の事業がされているということ、そして、もう１つ住宅課で行っております、住改善の工事助成ですね。","voiceIndex":289,"id":"exchange-125"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、東日本大震災があって、翌年の平成２４年は、３６０件と爆発的に設置が増えているのです。こうした区民の関心の高まりというのを、やはり捉えていくべきではないかなと思うのですね。そして今回も、熊本の大震災もありました。チラシの工夫とともに、高齢者の制度と同じように中身を、購入と設置を同時に助成できる中身に変えていくべきなのではないかと思うのですが、いかがでしょうか。","respondent":"今井住宅課長","answer":"家具転倒防止の器具取付助成ですけれども、こちらは品川区内のいわゆる建設組合の４団体、身近な施工業者の方も紹介しておりまして、こちらの方が実際に、取付助成の場合も、見積もりに行ったときに、どういうふうな設置器具がいいかとか。","voiceIndex":291,"id":"exchange-126"},{"speaker":"たけうち委員","kind":"確認","question":"今、１５０円一律になっていて、１０時間とめようが３０分とめようが１５０円ということで、それについて、少し料金体系を、民間みたいに、短い時間だったら例えば安くするとかということも検討したらどうだという話があったと思うのですが、今回の改定されるという、改定というか、駐輪場を整備するに当たって、料金については何か検討されているのかというのを、１つ教えてください。教えてください。","respondent":"桑波田交通安全担当課長、多並道路課長、古巻防災課長","answer":"駐輪場の料金の関係ですけれども、また来年度に向けて、いろいろな整備だとか制度の改正等も検討していますが、料金については。歩道橋の撤去につきましては、委員の今お話がございました、上神明歩道橋かと思いますけれども、これについても、地元の調整を行って。ただ、ちょっとまだ件数等、見極めがついていない部分もありますので、ただ、柔軟に対応していきたいというふうに考えております。","voiceIndex":294,"id":"exchange-127"},{"speaker":"たけうち委員","kind":"確認","question":"確認させていただきました。それから自転車の駐輪場についても、前１回、料金の話があって、検討したけれどもやらないというふうになったかなと思ったのだけれども、まだ引き続き検討するということですね。少なくとも地元の負担があるから、地元は手を挙げないかもしれないけれども、区としてはそう思ったのかなと思ったので聞いたのだけれども、そうではないのですか。そこを教えてください。","respondent":"多並道路課長、古巻防災課長","answer":"商店街の件ですけれども、今のお問い合わせの件ですけれども、実際、ご協力いただける商店街ということで、リストアップでそういう区間になったのですけれども、それ以外の区道、商店街を含めて区道につきましては。感震ブレーカーの設置助成、来年度に向けてですけれども、エリアの拡大につきましては、先ほどご答弁させていただいたとおりですが、件数等含めまして、今後さらに普及促進が進むように。","voiceIndex":298,"id":"exchange-128"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。電線の地中化だけではなくて、町並みも。その辺は考えていく、もちろん負担の問題もあると思うのですけれども、ぜひ考えていただきたいなと要望します。その辺の整合性というのですか。ほかのものも一応使えるよということで、安くあっせんしているのだと思うのだけれども、その辺のところをちょっとお聞かせください。","respondent":"古巻防災課長","answer":"木密地域を中心にしました設置助成につきましては、分電盤タイプ、これが一番効果的な機器であるということで選定をいたしまして、助成対象とさせていただいているところですけれども、とはいっても、それなりにお値段もかかるというところもありまして、ある意味。","voiceIndex":301,"id":"exchange-129"},{"speaker":"松澤委員","kind":"質問・要望","question":"４項都市計画費３目公園新設改良費、１６６ページ、しながわ中央公園拡張整備に関連しましてと、５項建築費１目建築行政費、建築確認事務について、時間がありましたらもう１点お伺いしたいと思います。その支障になるということで、下神明駅から北に下ったところの古戸越（トゴエ）橋の欄干の撤去が計画され、工事が始まっていますけれども、この工事計画の全容をお知らせいただきたいと思います。","respondent":"多並道路課長","answer":"ただ、何とかそれを残せないかというところで、この工事の中で、ちょうど拡張整備の入口のそばのところに移設をできるということで、調整ができたもので、今ある古い橋を、そのままカットして、そのままの形を残しながら、拡張整備の入口のところに移設をして、その横に。","voiceIndex":304,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問・要望","question":"現況、坂下から見て右側、西側なのですね。ですから、あれは大変貴重なもので、今、鉄筋コンクリートがむき出しになったりするのですけれども、大変、地域では親しまれたものですので、恐らく前任者も、西側を道路にしたときでも、撤去できなかったのかなというふうに思っています。そんな意味では、そういうふうにしてくれるということですけれども、橋の欄干ですから、それがどういう形状で残るのか。","respondent":"多並道路課長","answer":"ちょうど公園の西側の入口を今度新しくつくるのですけれども、そこの入ったところの、ちょうど上ったところに、両方とも橋がそのまま現存、残るような形に移設をしたいと考えています。","voiceIndex":306,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問・要望","question":"建築確認事務のほうですけれども、これも毎回議論が出ますよね。民間が増えて、品川区の確認が少ないという話はよく出ますけれども、私どもが一番心配するのは、やはり確認件数が少ないと、それを見る職員の技量が落ちてしまうのではないかなということを心配して、いろいろな方が質問しているのですけれども。建築確認事務、これの内容について、ちょっとお知らせをいただきたいと思います。","respondent":"鈴木建築課長","answer":"民間審査機関においても、法体系の中で、その解釈が間違っていれば、区は取消権限もあります。そういった相談が年間２万４,０００件、１日１００件程度ございまして、その相談に対して、職員が日々しっかり考え、答えているというような状況です。","voiceIndex":308,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"しっかりやっていて、大丈夫ですよというお話を伺いました。もう１つ、違反建築取締というのがありますけれども、これは、昨年、どんな違反が多かったのかということと、１つぐらい、こんなにすごいのがありましたよというのがありましたらお聞きしたいと思います。","respondent":"鈴木建築課長","answer":"特に、物置を、改修と一緒にちょっと物置を広げてしまって、その部分は、本当につくれないよというところで、例えば行っているとか、そういったところです。","voiceIndex":310,"id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"私は、１６８ページ、都市防災まちづくり事業の全般についてお聞きしたいと思います。区民が真っ暗な中、避難するわけですが、避難路に今現在、誘導灯がないわけです、これで安全に区民は避難できるとお思いでしょうか。お聞かせください。人口密度が高い地域ごとに、情報を流し、音声がよく聞こえる行政防災無線が必要だと思いますが、ご見解をお聞かせください。","respondent":"古巻防災課長","answer":"防災行政無線に関しましては、今、聞こえにくいというようなお声があることも十分認識しておりますので、来年度以降、そういったところを含めまして、設置・更新の計画を立てているところです。","voiceIndex":313,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"私は、ここは人の命がかかっていると思うのですね。この間、本当に大規模停電があって、この真っ暗な中で、人がどうやって動くのですか。もう右往左往する。ああ、大地震だ、外へ逃げる。私はこれは、早くすべきだったと思います。なぜ今までやらなかったのか。だって、一斉に情報を流されたって、どうするのですか。それに気づいたのですが、その点についてもう１回ご見解をお聞かせください。","respondent":"古巻防災課長","answer":"そういった中で、防災行政無線は、広範囲に情報を広く伝えるということが主眼で設置を進めておりますけれども、それ以外にも、メールサービスでありますとか、ツイッターでありますとか、そういった情報の発信の手段、多様に組み合わせまして。","voiceIndex":315,"id":"exchange-135"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、そういう基本的なことはやはり考えて早急にやっていただきたいと思います。次に、東日本大震災、５年７ヶ月経ちました。平成２８年９月時点で、避難者数はいまだに１４万人いるのですよ、１４万人。この間に、避難所生活の長期化で、被災者の心身への負担により、震災関連死をされている方も３,０００人ぐらいいるという話です。なぜ避難者は、生活基盤の再現ができないとお考えですか。","respondent":"古巻防災課長","answer":"避難者に関しましては、被害の状況に応じまして、様々な状況があるかというふうに思います。ですので、東日本大震災におきましては、復興の遅れから避難が長期化している面があるかというふうに思っております。","voiceIndex":317,"id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"実際、我々は向こうへ行って聞いてみました、宮古市のほうへ。個人の住宅や家財に対しては、やはり、国や自治体からの、私は、給付は限定的だと、もうそれは正直に認めるべきではないですか。東京都だって、きちんと冊子に書いているではないですか。もう６年になりますよね、来年になったら。だけれども、こういう知識はやはりきちんと教えるというのは、私は自治体の使命だと思うのですが、いかがですか。","respondent":"古巻防災課長","answer":"これまでも東京都の被害想定に基づきまして、しっかりと防災対策を進めてまいりました。今後も、それに基づきまして、きちんと防災対策を進めまして、また普及啓発につきましても十分に行っていきたい、そのように考えております。","voiceIndex":319,"id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"私は、１５９ページ、屋外広告物取締事務、１６０ページ、街路灯管理費、１６１ページ、自転車走行レーン整備、時間があったら、目黒駅前地区再開発事業、１６７ページで伺いたいと思います。屋外広告物ですが、現在の状況を教えてください。そもそもこの取締事務の目的と内容を教えていただきたいと思います。その観点からもお話を伺えればと思います。","respondent":"安井土木管理課長、多並道路課長","answer":"従来は１週間ほど、除却しろという、チラシの部分だけとってという形があったのですけれども、９月３０日に法が改正になりまして、そういった対応をとれるようになりましたので。今の委員の、建て替える際の方法と、やり方という点ですけれども、これについては、もともと１９８０年代にあった結構古いものもあるので、まずは古いものから順番に、現在、担当が現場を確認し、選びながら。","voiceIndex":322,"id":"exchange-138"},{"speaker":"大倉委員","kind":"質問・要望","question":"その黒い物を剥がす。その上から、シリコンみたいな塗布剤を塗って、滑って張りつけなくする。かなり重点的に力を入れてやらないと効果が上がらないと思いますので、ぜひやっていただきたいと思います。こうした視点からも力強くやっていただきたいと思いますが、いかがでしょうか。この辺どうしてか、教えていただきたいと思います。","respondent":"安井土木管理課長、多並道路課長","answer":"そういったこともありますので。民事のほうは、やはり相手方が特定できないので、その辺のところが難しいというところになっているかと思います。先ほど、古いものと、ちょっと説明が足りなくて申し訳ございませんでした。古い、いわゆる街路灯が自立して立っているポールが古くなっているものを、優先的に建替えですね、新しく建て替えたいと。","voiceIndex":325,"id":"exchange-139"},{"speaker":"大倉委員","kind":"質問・要望","question":"街路灯は結構です。ぜひ、優先順位をつけて、効率のいい建替えを進めていっていただきたいと思います。屋外広告物は、特定できないから取り締まれないという、刑事でも民事でも難しいということでした。自転車走行レーンは時間がなくなってしまったので、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":328,"id":"exchange-140"},{"speaker":"南委員","kind":"質問","question":"１６６ページの公園新設改良費について伺います。したがって、都市公園法で決められている１人当たり５m2、これにはなかなか到達していないという状況があるのではないかなと、ちょっと思っているのですね。したがって、こういう法律に明記されている１人当たりの面積にどう近づこうとするのか、そのあたりの考え方、それをちょっと伺っておきたいと思います。","respondent":"溝口公園課長","answer":"そういった中で、最大限、今ある公園の活用も含めまして、しっかりと公園の維持管理、または誰もが使える、そして安全に、安心に使えるような、公園の日常管理から整備、そういったものを行っていきたいというふうに考えているものです。","voiceIndex":330,"id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"やはり、町をつくるには、緑豊かな町、ここが第一だと思いますので、そういう点をしっかり改めて確認をしていただいて、公園を整備する、そういうことに力を尽くしていただきたいというふうに思っています。あれだけ公園が整備されていても、小さな子どもを遊ばせておけない、心配だと。その点についての考え方というのをどう思うのか、伺います。","respondent":"溝口公園課長","answer":"そういった中では、広く、小さい子どもから大きな子ども、そういったものが公園を利用して遊べるような整備を進めてきているものです。今後も引き続き、同様の考えで、公園整備をしっかり進めていきたいというふうに考えているものです。","voiceIndex":332,"id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、進めていただきたいと。１m2ないですから。０.５６m2程度のこんな状況が、ずっと横ばい状況ですから、ちょっとひどすぎるなというふうに思います。それで、幾つかの公園、既に現存する公園で、１、２、ちょっと改善していただきたいと思っているのですが、例えば南大井６丁目にある大井坂下公園。喫煙所が。その点についてのご意見を伺いたいと思います。ちょっとその点、伺います。","respondent":"溝口公園課長","answer":"ですから、近くに民家、または近隣にマンションがある、そういった所ですと、なかなかスケボーパークの整備というのは難しいというふうに考えているものです。","voiceIndex":334,"id":"exchange-143"},{"speaker":"南委員","kind":"確認","question":"あれは、分煙とは言えません。もう囲いがあるだけで、どんどん吸ったたばこは上も下も全部素通しですから。それから、メーカーの確認はきちんとしていただくのはもちろんですけれども、現場をやはり見ていただいて、もし可能であれば、体験もしていただいたほうがいいのではないでしょうか。でも、一定外れたところも離れたところもありますので、場所の検討も含めてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":336,"id":"exchange-144"},{"speaker":"浅野委員","kind":"確認","question":"やはり、この共同溝ですか、そこに入れる機器ですとか、電線もたくさん入るかと思いますけれども、そういうことを考えると、２ｍちょっとぐらい、もうちょっとですかね、３ｍぐらいの道だったのですけれども、それぐらいだとやはり厳しいのかなと思いますが、その辺のさじ加減というのでしょうか、どのぐらいの幅があれば可能性が出てくるのか、教えていただければと思います。","respondent":"多並道路課長","answer":"商店街電線類地中化の件ですが、まず、２商店街以外の商店街という件ですが、先ほども、説明が悪くて申し訳ございません。これ以外が、整備が必要ではないという意味ではなくて、まずはその中で、今まで２商店街について進めてまいりましたと。","voiceIndex":338,"id":"exchange-145"},{"speaker":"浅野委員","kind":"質問・要望","question":"一定の幅というのが７ｍとなりますと、やはりかなりハードルが、商店街としては高いのかなというふうに思います。こういうことについては、２段階になるかもしれないですけれども、工事の連絡と、あと、大きな変化ですので、ぜひともこういう場合には、住民、近隣の方にお知らせをするという、こういうことをしっかりと徹底をしていただきたいと思いますが、いかがでしょうか。","respondent":"安井土木管理課長","answer":"植樹帯について、非常に地元に愛されていたというものだと思いますので、そういったところについても、そのチラシに合わせて、工事内容等も説明するような形で、丁寧な対応を心がけていくように指導してまいりたいと思います。","voiceIndex":340,"id":"exchange-146"},{"speaker":"浅野委員","kind":"質問","question":"今からでも遅くはないので、こういう経緯で樹木を１回抜いて、それで、新たにまた植えさせていただきましたという、ちょっと丁寧な対応をしていただければと思います。次に進みます。そのままなのかどうかとかいうことも踏まえまして、ちょっとこの安全性を含め、また高齢者のスペースということも鑑みながら、この基本設計を進めていっていただいていると思うのですが、この件についてはいかがでしょうか。","respondent":"溝口公園課長","answer":"大きく岩とかがあるところにつきましては、基本的にはそのまま残していきたいというふうに考えているところではありますが、地域の声、またそういったご利用者の声、そういったものも十分に反映しながら。","voiceIndex":342,"id":"exchange-147"},{"speaker":"浅野委員","kind":"質問・要望","question":"この中では、バリアフリー化の促進に関する国民理解、協力の促進などとなっているわけですけれども、この心のバリアフリーの推進ということについて、ちょっと具体的に教えていただきたいと思います。目に見えない取組みになっているかと思いますが、どのような形で啓発をしていくのか、具体的に教えていただければと思います。","respondent":"中村都市計画課長","answer":"そういった意味では、ハードの整備を進めるのはもちろんのこと、身障者の方に対する配慮、こういったものについても、心がけていただくように働きかけていきたいというふうに考えております。","voiceIndex":344,"id":"exchange-148"},{"speaker":"浅野委員","kind":"質問・要望","question":"研修会みたいな形でやられるかどうかは、ちょっとわかりませんけれども、やはり１人になるとなかなかできない部分であるとか、また恥ずかしいとか、そういうのもあるかもしれませんけれども、そういう啓発事業なども、ぜひとも時を追ってやっていただければなと、このように思いますので、この点よろしくお願いいたします。私も２回ほど、上げて通して出してあげたということもあります。車も同じです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":346,"id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"確認","question":"あそこの移転した後の土地、新しく消防署の東品川出張所ができましたので、東品川文化センターの脇にあるもともとの消防署の土地、これは、品川の中でいろいろなまちづくりを考えていく上で、品川区として取得するべきではないかなと思うのですが、その辺、東京都の所有ですから、これからの話になってくると思うのですが、その辺について区としてどうお考えになっていくか。","respondent":"多並道路課長、柏原企画調整課長","answer":"大井町駅の駅前中央通りの件ですが、大井町駅周辺地区のバリアフリー計画の中で、当該道路につきましては、平成３１年度にバリアフリーの工事を行うという計画になっているところです。その後、区のほうに照会が来るかどうかというところも、その後の流れになってくるのだと思いますが、引き続きその情報をとっていきたいというふうに思ってあります。","voiceIndex":348,"id":"exchange-150"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大井町のほうの確認は、先ほども心の問題というのもありましたけれども、私のほうでちょっと確認したかったのは、中央通り、確か歩道を広げるというような話が記憶にあったのですが、ここを平成３１年度に工事ということは、でき上がるのは平成３２年の３月ぐらいまでかかってしまうのかなという気がしているのですね。工事の関係ですからちょっとわかりませんが。ですから、できれば、交換でもできると一番。","respondent":"多並道路課長、柏原企画調整課長","answer":"ただ、実際には、これから設計や、やるに当たっても、地元のまちづくりの皆様だとか、あと地元のご意見や、あとオリンピックのこれからの動きなどというのを総合的に考えまして、設計する際、いろいろな状況に応じた形で。今、委員ご指摘いただきましたけれども、東品川文化センター、区の持っている建物の近隣、隣にある、それからその間にも土地があるということもありますので、隣地は借金してでもというような言葉もあるところではありますけれども。","voiceIndex":351,"id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大井のほうは要望なのですが、ここの場所と、立会道路の今バスが通っているところ、あの辺をうまく活用すれば、何かいろいろな形、今後、もっと先の話になると思うのですけれども、今後、展開としてはいろいろおもしろくできると思うので、その辺、大井の方との話し合い等、オリンピック前に事業を終わらせておいてもらいたいなというのが希望で、これも要望にさせてもらいます。","respondent":"和田河川下水道課長","answer":"それから目黒川の臭気、それから水質の関係の連携ですけれども、これは、平成１８年から大田区と連携しまして、いろいろな水質の実験などをやっております。","voiceIndex":354,"id":"exchange-152"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"目黒区ともまたさらに、これからもやっていただいて、浚渫というお話がありましたけれども、そのような形、多少でもできればなと思っています。ソフト部分と同様、ハードでも、イベントだけでなく、今後において、やはり予算的にもかかってくると思いますので、その辺もいろいろご検討していただいて、予算組みをしていただきたいなということも希望しておきますので、これは要望で終わらせてもらいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":356,"id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1428#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":119305,"voices":357}},{"id":"h28-20161017-4","meetingId":"h28-c-settlement","date":"2016年10月17日","dateIso":"2016-10-17","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を150件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開会いたします。 それでは、平成２７年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開会いたします。 それでは、平成２７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"おはようあります。よろしくお願いします。私からは、成果報告書の１７７ページ、埋蔵文化財調査費、同じく１７７ページ、子ども地域活動支援経費、１８０ページ、学校環境整備事業の中の校庭人工芝生化についてお伺いをいたします。初めに、埋蔵文化財調査費について質問をいたします。決算書を見ますと、１０件、試掘調査費等と書いてありますけれども、これは具体的にどういった内容なのか教えてください。","respondent":"品川庶務課長","answer":"１７７ページの文化財保護費、調査ですが、こちらは埋蔵文化財の調査です。地中に埋まっている文化財、こういったものに対して、建設等、そういう場合に、届出をしていただくことがあります。その場合、地中に埋蔵した文化財が埋まっていないかどうかの調査の件数です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今現在、埋蔵文化財包蔵地は２５カ所だと思うのですけれども、今、私が質問しました、１０件全部とは言いませんけれども、何かお宝があったのかとか、もしそういった、今回あったのかどうかお知らせいただきたいと思います。","respondent":"品川庶務課長","answer":"この調査の１０件ですけれども、全て調査の段階で終了しておりまして、特に大きなものは出てございません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは、例えば、神社の近所の注文住宅の掘削工事のときに、そういったものが出たとか、そういったところの解釈でよろしいのかどうかと、これは当然、建築課との連携もあると思うのですけれども、その辺も教えていただければ、よろしくお願いします。","respondent":"品川庶務課長","answer":"建築課と連携というところについては、基本的には業者が申請をしてきますので、特段連携等はないのですが、包蔵地とかの場合、こういったいろいろな事例について、調査をしなければいけないとか、そういった状況の中では。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今後もこの取組み、ぜひよろしくお願いいたします。次に、同じく１７７ページ、子ども地域活動支援経費についてお伺いいたします。これは、区内小学校児童についての町会・自治会等の行事参加の促進事業実施についてだと思うのですけれども、町会の行事参加等の参加カードがあると思うのですけれども、これは平成２７年度から始まった取組みだと考えています。","respondent":"品川庶務課長","answer":"今年から４・５・６年生については、欲しい方についてはカードを配るというような対応をしています。それから２つ目ですが、景品の見直しを行いました。","voiceIndex":10,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"先日、私も小学校の地域の親子運動会、今年で３７回でしたか、地域の親子運動会に私も役員として参加したのですけれども、ほかの町会の、私、声をかけられたのが、子どもからスタンプカードを持ってきたのですけれども、その辺の町会との温度差があるところがございまして、やはりよその町会も、町会長がどういうふうな啓発をしているのか、伝わっているのか、伝わっていないのか。","respondent":"品川庶務課長","answer":"本年度もこういう内容の改正とか、各連合町会の町会長会議を回りまして、今、説明を行っているところですので、今後も周知には努力していきたいと考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。続きまして、１８０ページ、学校環境整備事業の中の校庭人工芝生化についてお伺いいたします。今年度、この人工芝生化の件数は２件ということなのですけれども、その２件の学校名を教えてください。","respondent":"品川庶務課長","answer":"今年度進めている学校については、台場小学校、それから伊藤小学校です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これ、今、校庭人工芝生化は推進がいろいろされておられると思うのですけれども、当然、今をもって、例えば源氏前小学校とかも砂なのですけれども、砂ぼこりとか、そういった苦情がなければ、今の状態を、砂、サンドを保っていくのかどうか教えてください。","respondent":"品川庶務課長","answer":"ただ、昨今、土のグラウンドと人工芝のグラウンドとコストがさほど変わっていないというような状況も見えてきていますので、現在、これを研究しまして、どういう方向でいくか考えていきたいと考えています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"１７８ページ、品川図書館運営費、１７５ページのオリンピック・パラリンピック教育推進事業費についてお伺いをします。品川図書館の運営費ですが、品川図書館の自転車置き場について伺いたいと考えています。現在の自転車置き場が整備されてからどれぐらいの年数がたっているのか、また、自転車置き場のラックの耐用年数はどれぐらいなのかお伺いしたいと思います。","respondent":"木村品川図書館長","answer":"平成７年に品川図書館が建ちましてから２１年ですけれども、ずっとその当時から駐輪場を整備しています。昨年、塗装を行いまして、そういう形で運営をさせていただいてきております。ラックの耐用年数については、今調べております。少々お待ちください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"しかし、ここはやはり多くの方が使う図書館であります。安全で事故のないような体制が求められるのですが、もう既に２１年たっているということで、今後、使い勝手のいいタイプの置き場を新設されることを要望したいと思うのですけれども、いかがでしょうか。新たに整備される予定があるのかということもお伺いをさせていただきたいと思います。","respondent":"木村品川図書館長","answer":"改築の計画につきましては、その中で考えてまいりたいというふうに思っております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"さまざまご検討いただいて、早めに新しいタイプ、取りつけをお願いしたいと思います。続いて、オリ・パラ教育の推進事業についてお伺いいたします。今年度、平成２８年度も含めますと、全校になっているのかとも思うのですが、平成２７年度までの１６校の学校名を教えていただきたいと思います。そして、どのような内容で行われてきたのか、ご紹介をいただきたいと思います。","respondent":"熊谷指導課長","answer":"昨年度の成果ですけれども、主な取組みとして、特にスポーツを重視した取組みをこの２年間でやってまいりました。","voiceIndex":23,"id":"exchange-010"},{"speaker":"新妻委員","kind":"提案","question":"既に平成２８年度になりますと、全ての学校でこれが推進校になっているかと思いますが、そのことも確認をさせていただきたいと思います。そのことを海外に向けて子どもたちが発信をできたらいいのかなとも思うのですが、そのような日本の文化を知っていくという取組みにおいては、どのようにお考えか、お聞かせいただきたいと思います。","respondent":"熊谷指導課長","answer":"特に本年１月に策定されました実施方針では、「オリンピック・パラリンピックの精神」、「スポーツ」、「文化」、「環境」という要素の中でも、「文化」というものが非常に重要な柱となっております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思います。この１月に発表されております「東京都オリンピック・パラリンピック教育」実施方針の策定につきまして、その中でも基本的視点から、全ての子どもが大会にかかわるということ、そして日本人としての自覚と誇りというようなことも明記をされておりました。どうぞ推進をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、１７３ページ、いじめ防止対策費に含まれるのでしょうか、学校現場での人権、ＬＧＢＴについて取り上げたいのが１点。関連して品川区の人権啓発事業でも、最後の人権と言われているＬＧＢＴの位置づけを高めていただきたい、ふさわしい事業を実施していただきたいと、こう求めたところなんですが、ここから質問なのですが、十分な対応を考えていこうと考えていますとご答弁をいただきました。","respondent":"村尾教育総合支援センター長","answer":"基本的な考え方といたしましては、性同一性障害のある人々に対する偏見や差別、嫌がらせ等の言動に対し、さまざまな問題があるという中で、まず教員が性に対する理解を深め、性同一性障害のある児童・生徒に対して、さまざまな支援、またきめ細やかな対応ができるようにしていく。","voiceIndex":29,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よろしくお願いします。款を越えてしまうのですが、人権啓発事業のところで、もし答えられたら、後でいいので、今後の取組みを高めていただきたいといった前回の質問に対してのご答弁をいただけたらと思います。いじめや暴力を受けた結果、３２％が自殺を考えている。このような報告がされていますけれども、教職員の方々は、教育現場の実態をどれだけ知識として持っていらっしゃるのか伺います。","respondent":"島袋人権啓発課長、村尾教育総合支援センター長","answer":"時間がたっておりますことから、新たな人権課題としての取組みについて、今後、一般職員、教職員、管理職も含めた研修を計画しています。もし児童・生徒、また保護者から相談を受けた場合、現在、学校内においては早急にサポートチームを設置し、教職員間での情報共有、また関係の機関との連携を図りながら、その児童・生徒に対して適切な対応ができるよう、今。","voiceIndex":31,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"対応はいろいろしていただいているのは理解をするのですが、どれだけの知識を持っていらっしゃるのかという、やはりこれは正しい知識をより多くの方が持つことで、さまざまな信号を受けとめて対応できるということですので、より多くというか、世の中全体の人が理解を深めていく、そういった意味で、特に児童・生徒に対しては教職員の方々がどれだけ知識を持っているのか、この点を伺ったので。","respondent":"村尾教育総合支援センター長","answer":"研修につきましては、先ほどご答弁させていただいたとおり、教員対象の研修については、このＬＧＢＴ（性的マイノリティー）についての研修は、現在、昨年度から実施しているところです。教員が正しい認識を持つことは、子どもたちに対してとても大切にはなります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一番最初の質問では、学校図書館への関係図書の配置はまだだと。先にいきます。インクルーシブ教育のところなのですが、特別支援学級の父母の方々から要望が届いています。共同学習の充実を求めています。小学校、義務教育学校の中には、固定学級と普通学級の児童・生徒との交流学習の充実を求めています。インクルーシブ教育として、当然の要求と思いますが、ここの充実を求めますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"ただ、いつもどの授業でもできるかというと、やはり子どもたちの現状もありますし、それから、その学習の内容等、また方法等にもいろいろ課題がありますので、その中で、例えば音楽の授業を一緒に受けるとか。","voiceIndex":36,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"小さいころから、人間は一人ひとり違う。でも一緒にいることで、心と体で理解し合えると思います。なので、さまざまな機会を捉えて、教育現場は困難があると思いますけれども、教育環境への支援もしながら考えてほしい。学級の位置なのですが、学校の真ん中に置いて、全児童との交流が図れるような工夫をしていただきたいのですが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"当然、障害のある子どもたちにとって、その可能性を最大に伸ばす、また自立し、社会参加できるよう、各学校においても取組みは今後とも進めていこうというふうに考えておるところです。特別支援学級の配置につきましては、それぞれ各学校にありますので、また検討します。","voiceIndex":38,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１８４ページの学校施設建設費、１７７ページの文化財保護事業、以上２つに関連してお伺いをいたします。そこで、東品川四丁目の学区域の城南小学校、平成３１年に増改築をされる予定と聞いておりますけれども、この城南小学校、幼稚園、どのような校舎になるのか、これを簡略にお知らせください。３点目、これで東品川四丁目の学区域の人口増に対処できるものになるのかお知らせください。","respondent":"篠田学校計画担当課長","answer":"今回は普通教室数といたしましては、１８クラスを想定しておりますので、この中で、今後、人口推計の中で想定される子どもたちの増に対しては十分対応できるものというふうに考えております。","voiceIndex":41,"id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、東品川四丁目に限らず、今後も品川区各地域でマンションがどんどん建つことになると思いますけれども、今後もそういう状況に対応して、学校の増改築で対応していくという方針でしょうか。","respondent":"篠田学校計画担当課長","answer":"例えば、現状の施設で収まり切らないというようなことがあれば、まず一番最初の段階といたしましては、学校の内部で、例えばランチルーム等を改修して普通教室に転用するとか、そういった手立てを講じまして、それでもだめな場合には、新たな学校の改築といったものも含めて。","voiceIndex":43,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"はい、わかりました。ただ、ディベロッパーのマンション開発とかの建築発表を受けたら、増改築の準備に品川区としては入っているのでしょうか。今後もそうした状況が考えられますので、区としてもディベロッパーに対して、今、学校施設はこうした状況だとか、そうした相互の情報共有の連絡体制とかは作られているのでしょうか。","respondent":"篠田学校計画担当課長","answer":"各ディベロッパーなどからは、教育委員会のほうに建てますというような話で直接入ってくるわけではございませんので、区のほうに対してさまざまな届出がありますと、区の内部で情報等を共有しながら学校の改築の判断につなげているという状況です。","voiceIndex":45,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"品川区としても、そうした再開発とか建築の予定を聞いてから、事後的に対応されるのは非常に大変だと思いますので、こうしたことにならないように、早め早めにディベロッパーとの連絡体制もとっていくべきかと思いますけれども、その点、どうお考えでしょうか。","respondent":"篠田学校計画担当課長","answer":"なかなか教育委員会で直接ディベロッパーとやりとりをするというのは、なかなか難しい部分はあるのですけれども、引き続き、今度とも庁内各課との連携等も含めまして、後手に回らないような形での対応を進めてまいりたいと考えております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。よろしくお願いします。続けて、文化財保護事業についてお聞きいたしますけれども、現在、区内の指定文化財の数と、東京都が指定する品川区内の指定文化財数は、お幾つでしょうか。","respondent":"品川庶務課長","answer":"現在、品川区内で指定されている文化財の件数ですが、約１８０件ほどあります。その中で東京都が文化財指定をしているものが、約２０程度あります。","voiceIndex":49,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"各種書籍とか、インターネット等の媒体で、品川区は特徴がないだとか、イメージがないだとか、各種ランキングでも大体真ん中だとか、そうした言われようですので、品川区はせっかく１位なのですから、ぜひともＰＲをしていっていただきたいのですけれども、今の品川区のホームページを見ましたところ、指定文化財については、掲載されておりますけれども、かなりあっさりした紹介ぶりになっておりまして。","respondent":"品川庶務課長","answer":"こういった部分も今後検討して、オリンピック・パラリンピックに向けて、品川区の文化財、大いにＰＲしていきたいと、このように考えております。","voiceIndex":51,"id":"exchange-023"},{"speaker":"田中委員","kind":"確認","question":"１７２ページ、１項３目教育指導費、移動教室経費、いじめ等防止プログラム経費、１７６ページ、介助員等委託について伺います。移動教室について伺います。２０１５年第２回定例会で生活者ネットワークは、一般質問で、移動教室の行き先変更について伺いました。そこで伺いますが、校長会の校外活動会、あるいは校長会が行き先の変更を決定する権限があると読み取れますが、その認識でよろしいのでしょうか。","respondent":"有馬学務課長","answer":"最終的に起案をして決定をとるのは教育委員会の事務局のほうで決定をとります。その後、教育委員会につきましては、移動教室をこういう形で実施するということで、これは議案ではなくて報告事項ということで報告しているものです。","voiceIndex":55,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問","question":"決定権は教育委員会事務局にあるということで理解しました。この件に関して言えば、校長会の意向は大変大きいと考えるのですが、いかがでしょうか。","respondent":"有馬学務課長","answer":"実際に子どもたちを連れて現場へ行って指導していろいろ活動しているのは、学校現場です。その責任者が校長ですので、まずその校長の意見は最大限尊重するというのが教育委員会の立場です。","voiceIndex":57,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"内容について担当課長にお伺いしたところ、校外活動会、移動教室担当校長会では、議事録をとっていないと言われました。しかし、どこの会議体で決定あるいは確認、承認をしたかを後追いするためには、議事録のない会議はあり得ないと思うのです。いかがでしょうか。見解を伺います。そういった資料の作成を求めます。いかがでしょうか。","respondent":"有馬学務課長","answer":"その後、校長会の連絡会とか、そういうところで議題に上がれば、そこは校長連絡会の中での報告事項とか、そういうことで議事録は一般的には出てくるものということで考えているところです。","voiceIndex":59,"id":"exchange-026"},{"speaker":"田中委員","kind":"確認","question":"部会の判断とありますけれども、先ほどもちょっと言いましたけれども、決定と確認、承認がどこでされたのかというのは、とても大事なことだと思います。なので、議事録は残してほしいと思います。関連して、教育委員会会議録について伺います。教育委員会運営費には、教育委員会開催時の議事録作成費が含まれると思いますが、決算額を教えてください。","respondent":"品川庶務課長","answer":"教育委員会の議事録ですが、昨年度まで議事録は職員で作成しておりましたので、基本的には予算等かかってございません。ただ、今年度から議事録作成を委託しておりましてやっているというような状況です。","voiceIndex":61,"id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区の教育行政は、大きな変化や改革が行われており、その内容を決定する機関として、品川区の教育委員会は大変な重責を担っているとともに、説明責任も求められるものだと思います。他自治体や区民、教育にかかわる人たちの注目度も高いと思います。２３区中１６区は逐語録になっています。品川区は逐語録に変更することは検討されていないのでしょうか。","respondent":"品川庶務課長","answer":"昨年度まで、委員のおっしゃるとおり、要約を議事録として出しておりました。今年度４月から逐語録というような形で対応していくというような方向で進めているところです。","voiceIndex":63,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"前向きに検討してくださるとのことでよかったです。では、いじめ防止等プログラム経費について伺います。複数事業があることは知っていますが、その１つ、いじめ防止プログラムについて決算額を伺います。現在、大崎中学校、伊藤学園、八潮学園、豊葉の杜学園の７年生で実施されていると伺いました。各校のスクールバディの実態といじめ防止への効果について、教育委員会の評価を伺います。","respondent":"村尾教育総合支援センター長","answer":"現在、４校が実施し、いわゆるモデル校指定として当初はスタートいたしました。現在も少し増えながら、この学校で実際に進めているというような現状です。","voiceIndex":65,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"そう要望します。では、次に、教育現場への親の付き添いについて伺います。障害児を普通学級で学ばせたいという親御さんの団体と教育委員会で話し合いの場が今年の６月にもたれ、その中で、子どもの学校生活の中での保護者の付き添いは、これをさせないということを再確認したと伺いました。現状、親の付き添いが行われているという話を伺っていますが、その実態についてどのようにお考えでしょうか。","respondent":"村尾教育総合支援センター長","answer":"これまでも通級指導学級という名称であれば、やはり子どもたちをその学校に保護者が付き添って送り迎えをしていただくというのは条件ではございましたが、本年度から、本区においては、全ての小学校、それから義務教育学校の前期課程において、教員がそれぞれ各在籍校に行って。","voiceIndex":67,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"普通学級の親御さんのお話を伺ったので、もう１回、答弁をよろしくお願いします。","respondent":"村尾教育総合支援センター長","answer":"普通学級へ通っている知的等の障害のある子どもたちへの付き添いという部分です。これについては、現在、やはり登下校の安全等を含めて、やはりまだ学校が、例えばそこに対応するということはできておりません。","voiceIndex":69,"id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"６月に教育委員会との話し合いの場がもたれて、子どもの学校生活の中での保護者の付き添いは、これをさせないという確認がされたと私たちは聞いています。こういった現場の様子は区教委も当然お聞き及びと思います。学校現場でも、本当の意味での障害者差別の解消を一層進めていくことについて、見解を伺います。","respondent":"村尾教育総合支援センター長","answer":"会議等のものについては、改めてこちらのほうで確認をさせていただければと考えていますが、本区においても、インクルーシブ教育を含めて、子どもたちへの合理的配慮については、各学校でさまざまな形で進めていこうというふうに捉えているところです。","voiceIndex":71,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちの中にもともと障害のある子どもたちがいるという環境があれば、その後、障害者差別のことについて学ぶなどしなくても、自然にそういったことを学ぶことはできるのです。なので、ぜひ学校現場での本当の意味での障害者差別の解消を進めていくということを要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"１７６ページの国際理解教育でお伺いします。公教育における英語教育の充実を図って、真の国際人を育てていくという区としての強い意気込みを感じております。イングリッシュレッスン５００は好評で、今年度から４校に拡大したということですけれども、今後の方針と、各校に拡大するにはそれなりの人員や整備が必要かと思うのですけれども、そのあたりのお考えをお聞かせください。","respondent":"熊谷指導課長","answer":"教員からも非常に好評です。今後なのですけれども、イングリッシュレッスン５００ですが、現在、タブレットを使いまして、大崎中学校、浜川中学校で行っておりまして、１１月からは、荏原平塚学園、そして冨士見台中学校で、パソコン室を活用して行っていく予定です。","voiceIndex":75,"id":"exchange-034"},{"speaker":"沢田委員","kind":"質問・要望","question":"今、日本人学生で海外に留学したいという人数が年々減っているということです。これはまさに区の英語教育の使命だと思います。真の国際理解につながっていくことであると思いますので、ぜひとも事業の拡大をしていただきたいと思いますが、そのあたりのお考えをもう一度聞かせてください。","respondent":"熊谷指導課長","answer":"方法等、さまざま検討していく部分がありますので、それは検討事項として考えていきたいというふうに思っております。","voiceIndex":77,"id":"exchange-035"},{"speaker":"沢田委員","kind":"質問・要望","question":"１８０名、大変多くの方が希望したということで、これはどのように選考したのかお聞かせいただきたいと思います。それは後で聞かせてください。それで、そういった中で、先日、１０月１０日に東京青年会議所主催で、英語スピーチコンテストが開催されました。区長、両副区長にもいらしていただきました。","respondent":"熊谷指導課長","answer":"今年度につきましては、まず昨年度参加した子どもが今年も行きたいというふうに多数応募してきましたので、まずは行っていない子どもを優先ということで、９年、８年、７年の順でとったところです。","voiceIndex":79,"id":"exchange-036"},{"speaker":"沢田委員","kind":"質問・要望","question":"まさに学校と国際友好協会との海外研修での連携が行われていると思うのでけれども、この海外研修、オークランド等ありますけれども、どういった形で学校とこの海外研修が連携できているのか、できる限りこういった事業にも参加を促すような学校からの働きかけというのは、今どういうふうになっているのか教えてください。","respondent":"熊谷指導課長","answer":"学校とそういった部分で連携しながら、現在、平成２６年度からは、各中学校、原則１名の推薦ということと、平成２７年度からは、一次は作文と英語、二次は面接ということで、私どもも面接をしてふさわしい子どもを選んで送っているところです。","voiceIndex":81,"id":"exchange-037"},{"speaker":"つる委員","kind":"確認","question":"源氏前が４４年、ゆたかが４１年ということで、公共施設というか、コンクリートのあり方を含めて、この辺、大体中長期とか、その辺の考え方があれば、またそれを生かしていく部分もあるのですが、ざっくりで結構なので、この図書館、全体の公共施設という観点も含めてで結構なのですが、改築、改修の計画があったかどうか、念のため確認で教えてください。","respondent":"木村品川図書館長","answer":"現時点では、ご案内ございました大崎図書館の移転というところが控えております。その後の改修計画につきましては、現在、具体的なものとしてはまだございませんが、今後、そういう公共施設の改築、改修の計画に合わせて検討してまいるところであると考えております。","voiceIndex":84,"id":"exchange-038"},{"speaker":"つる委員","kind":"質問・要望","question":"図書館を減らしてほしくないという部分、全体の１０館を維持していただきたいし、さまざまな形で充実させていただきたいという、それが基本線なのですが、その上で、これは全体で結構なのですが、品川区の全図書館の来館者数と図書館利用カードの保持者数、それから昨年度の年間での貸出サービス利用者数、これを教えてください。","respondent":"木村品川図書館長","answer":"来館者、カード登録者、貸出数のお尋ねです。全てこれは平成２７年度ですが、延べ来館者数に関しましては約１００万人、それからカード登録をされている方は約１４万人、それから貸出数に関しましては、約３５０万点です。","voiceIndex":86,"id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"本の冊数とかでいくと３５０万ぐらいということなのですが、そのいわゆる１４万人のうち、これは意味のない数字で、押しなべて大体年間で１０冊とか、そういう計算になるのでしょうけれども、それはあまり意味のない数字だと思っていますので、この登録者数のうちで、どれだけの人がそういう多く借りている、いわゆるリピーターという表現なのかわかりませんが、その辺の数値はとれているものなのですか。","respondent":"木村品川図書館長","answer":"利用者によっての本冊数の多い少ないですけれども、数としては、そういう形での把握は今しておりませんけれども、実際にカウンターを見ておりますと、本当に点数ぎりぎりでいつも本をお借りになっている方もいらっしゃれば。","voiceIndex":88,"id":"exchange-040"},{"speaker":"つる委員","kind":"確認","question":"全体の話の部分なので、またそこについては改めて伺っていきたいと思います。次に、角度を変えて、図書館以外で受け取り、また返却ができるところの確認をしたいと思うのですが、障害をお持ちの方で配送サービスとか、そういうものをやったりとかは存じ上げておりますが、これからのサービスとして、大崎駅西口の取次サービス、それ以外のいわゆる図書館以外で受け取り、返却ができるところを教えてください。","respondent":"木村品川図書館長","answer":"現在は、今ご案内ありました駅前のサービスコーナーということでは、大井町、それから武蔵小山のサービスコーナー２カ所で図書の貸出、返却という形で受け付けております。","voiceIndex":90,"id":"exchange-041"},{"speaker":"つる委員","kind":"質問","question":"貸出配本、これは今、事務事業を見たら、団体貸出というふうになっていましたけれども、その説明と、実施先について教えてください。","respondent":"木村品川図書館長","answer":"団体貸出についてのお尋ねです。現在は、児童センター、それから保育園、幼稚園、あとは福栄会と昭和医大に、本を一定のサイクルで貸しているというような、そういうサービスを行っております。","voiceIndex":92,"id":"exchange-042"},{"speaker":"つる委員","kind":"質問","question":"いろいろなところでぽつぽつとやられている、いわゆる赤ちゃんタイムというのがあると思うのですが、それとかを含めて、０、１、２、３歳、公立の幼稚園とかにする場合は、３歳とかの場合は、在宅で育児をされている方などは、０、１、２、３歳もいわゆる午前中の時間とかも図書館を利用される機会はあると思うのですが、そういうことも含めて、子連れの方が安心して本を探せる、また親しむ。","respondent":"木村品川図書館長","answer":"０歳から３歳の子どもたちが安心して本に親しめる場所のお尋ねです。","voiceIndex":94,"id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"今、おはなし会とありました。それは基本的に図書館側として主催をいただいている、ＮＰＯなどにお願いをしたりとかということも含めてなのですが、いわゆる任意の保護者の方がグループをつくっていろいろ読み聞かせとかをやっていると思うのですが、これは図書館とかでやる場合は、どういう手続が必要ですか。","respondent":"木村品川図書館長","answer":"基本的には、今、図書館では、図書館が主催をするというような形でのおはなし会の開催という形になっておりますけれども、いわゆる自主的にやられているということでは、児童センター２５館の中の数館で、演者の方、地域の方が自主的にやられているというお話は聞いております。","voiceIndex":96,"id":"exchange-044"},{"speaker":"つる委員","kind":"確認","question":"子どもによって、年代によって、いろいろな本だとか、紙芝居とかあるのですが、結構大きい本があって、それ専用のところとかあって、大変便利なのですが、先ほど確認させていただいた図書館以外で本を貸し出したり、返却できる場所ということで、大井町と武蔵小山のサービスコーナー、非常に拡充されているのですが。","respondent":"木村品川図書館長","answer":"児童センターでの図書取次の実施に関するお問い合わせです。実際に子どもたちに対して読書を勧めるきっかけづくりというのは、区立図書館としては大変大事な仕事だと考えています。そのために、先ほどのような形でも展開しておるところです。","voiceIndex":98,"id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"ニーズはあると思います。児童センターに入れる世代の方々とか、いろいろな制約もあるのですが、非常にそこまでわざわざ持っていって、そこでおはなし会をやって、また図書館に返すというのは結構な労力だと思います。そういったところも含めて、ぜひ検討いただきたいと思います。北区のこども図書館については、ぜひ参考にしていただきたいと思います。対応をどういうふうにされているか教えてください。","respondent":"有馬学務課長","answer":"牛乳、そして乳製品というカテゴリーですけれども、今年度で、小学校で５８名、中学校の部分で６名、合計６４名がアレルギー症状があるということで、対応といたしましては、まず牛乳については完全除去いたします。除去対応です。","voiceIndex":100,"id":"exchange-046"},{"speaker":"つる委員","kind":"意見","question":"時間もなくなってきたのであれなのですが、今、牛乳のアレルギーを持っている児童・生徒に対する対応だとか、人数についてはわかりました。その中で、和食を提供する機会。米飯というときに、和食になるのかちょっと別ですけれども、いわゆる和食を提供している機会はどれだけありますか。","respondent":"有馬学務課長","answer":"品川区は、週３回から４回ということで米食を提供していて、和食を中心に出しているというのが特徴かです。","voiceIndex":102,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"昨年の一般質問で、再質問のところで参考にということで紹介させていただいた乳和食です。牛乳を使った和食ということであります。牛乳というのは、カルシウムを摂取するために、どういう和食のメニューのときでも出したりするわけだと思うのですが、その和食に合う牛乳の使い方というところで、乳和食があるのですが、これの活用についてお考えをお聞かせください。","respondent":"有馬学務課長","answer":"今、学校のほうでも、和食はユネスコで無形文化遺産に登録されたということで注目されていますけれども、一方で、塩分、お醤油とかみそを使うということで、その辺が少し問題だということになっています。これから牛乳の件につきましては研究していきたいと思います。","voiceIndex":104,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は、１８２ページの就学援助費について拡充を求めて質問します。初めに、新入学学用品費です。いわゆる入学準備金の支給時期についてですけれども、現在は、入学してからお知らせをもらい、４月までに申請をして、その後、第１回目の支給が７月下旬になっています。就学援助を受けていた方にお話を伺うと、やはり入学前の準備にお金がかかると。いかがでしょうか。","respondent":"有馬学務課長","answer":"実態といたしましては、生活保護のほうでは、この新入学用品というのは３月に支給されているということですので、要保護者の世帯の新入学用品につきましては、一般の就学援助の７月の段階ではなく、入学する前に支給されているです。","voiceIndex":107,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"要保護についてはそうなっているということですけれども、準要保護についても、やはり入学前から支給が必要だと思います。いかがでしょうか。","respondent":"有馬学務課長","answer":"所得要件は前年度の収入で見るということでして、これがどうしても３月の確定申告後、税額が決まるのが６月ということでございまして、早く出したいという気持ちもありますけれども、今の制度のもとでは、７月支給ということでご了解をいただいているです。","voiceIndex":109,"id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"以前に紹介した福岡市や栃木県日光市だけでなく、新潟市、青森市などでも行われています。これまで求めても、先ほどありました所得認定が６月である、あるいは入学するかわからない、よって支給は入学してからというご答弁ですけれども、来年度から入学前に支給を始める八王子市では、入学準備金については前年の所得で認定をして支給をしています。品川でできない理由は何か伺います。","respondent":"有馬学務課長","answer":"ということで、６年生のときの対象にすると、実際、中学１年生のときに本来ならもらえた人が外れてしまうというようなこともございまして、そういったことは６年生時点であげるよりも、きちんとした今の制度の運用の中で、しっかり中学１年生に入学した人。","voiceIndex":111,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"この紹介しました八王子市は、中学校でもそういった前から支給していくということをやっております。ほかのところでも６年生、先ほどありました検討されて支給しているところもありまして、もし基準から外れた場合でも、返還を求めるようなことはないというところでやっておりますので、やはり品川区としてもそういった柔軟な対応をやっていただきたいと思うのですが、いかがでしょうか。","respondent":"有馬学務課長","answer":"現在の申請数、相当な数に上っておりますし、今のところ、これを２回にわたって申請をし直すということは考えておりませんので、現行のままの形でいきたいと思ってあります。","voiceIndex":113,"id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"時遅く、子どもは既に亡くなっていました。子どもの貧困は、子どもの未来を奪います。こうした深刻な実態が品川区で起きないように、改めて入学前からの支給を求めたいと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"冒頭申し上げましたとおり、要保護世帯につきましては、きちんと３月のところで支給されているということもありますので、一定の配慮は今の制度でもなされているというふうな認識に立っております。","voiceIndex":115,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"一定の配慮をしていると言いますけれども、準要保護については、やはり入学した後となっている。そこもしっかりと入学前から支給していただくように、これは強く要望しておきます。次に、来年度の就学援助対象者の基準はどうなっているでしょうか。この間の生活保護の引き下げに連動させるべきではないと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"来年度の生活保護の基準との関係をどうするかですけれども、生保の基準は平成２５年度から３年間にわたって引き下げられたです。来年度につきましては、またこれから適宜適切に判断をしていくです。","voiceIndex":117,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"適宜検討していくということですので、ぜひ引き続き基準を引き下げずに、今、予算組みをしていると思いますので、引き下げずにいくことを強く要望いたします。各費目について伺います。実際にこれに記載のある予算額では、平成２７年度より平成２８年度は下がっています。この案は、平成２８年度に入って実施されたのか、区で支給額について変更はあったのか伺います。","respondent":"有馬学務課長","answer":"それで、今言ったように、まとめていくような計画があるのかですけれども、今のところ、区のほうでは、従来どおりの単価に基づいて支給をしていくという考えです。","voiceIndex":119,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"もし今後、国がこういったことをやっていくようであれば、やらないように求めていただきたいと思いますし、実施されても下げないようにしていっていただきたいと要望いたします。各費目の支給額についても、ちょっと安いのではないでしょうか。どちらの調査でも、現在の支給額の２倍以上です。入学時の実態を調査し、区の支給額を実態に合わせて見直しを求めますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"学校給食費につきましては実費となります。そのほか主なところでいきますと、修学旅行費６万円、卒業アルバム、小学校１万１,０００円、中学校が１万円と、大体そのぐらいです。","voiceIndex":121,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、額を言われたわけですけれども、やはり実態と合っていないというところで、しっかり区の実態も調査していただいて、それに合わせて見直しを行ってほしいと伺いましたので、ぜひそれを求めたいと思いますが、いかがでしょうか。加えて、制服代も、今、一律２万円ですけれども、やはりそれも実費に合わせて行っていただきたいと思います。いかがでしょうか。","respondent":"有馬学務課長","answer":"基本的には、先ほど申し上げましたけれども、社会情勢等を踏まえまして、平成２６年から平成２７年というふうな改定をしています。ということで、今言った標準服等も含めまして、適宜判断してまいりたいというふうに思います。","voiceIndex":123,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ実態調査をして拡大していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-058"},{"speaker":"あべ委員","kind":"質問","question":"私からは、１７７ページ、特別支援教育の中の特別支援教室整備、それから１７８ページの図書館資料、それからあとは、時間があれば、学校施設建設ならびにＩＣＴ活用についてもお伺いしたいと思います。特別支援教室なのですけれども、この整備を受けて、今年度よりスタートをしたと思います。今の対象人数と、教育委員会としてこの事業を現在のところどう評価しているかについて教えてください。","respondent":"村尾教育総合支援センター長","answer":"本年度から始まりました区の特別支援教室の実績ですけれども、小学校が全校で開始ということで、現在、２２４名の子どもたちが、この特別支援教室での学習等に取り組んでいるところです。","voiceIndex":127,"id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"昨年度までの通級で通っていた子どもたちから利用が増えたのかどうか、その数字も教えてください。それから、今、コミュニケーションの話が出ましたけれども、従前は介助員や支援員と担任との連携ということが１つの大きなポイントとなっていたと思いますけれども、今回、巡回の教員と担任の先生、そして介助員等の方々との連携というのは、どのようになっているのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"介助員、学習支援員については、それぞれの特別支援教室の担任がどのような対応をしているかをお互いに情報共有をすることで、その子にとって今必要な支援がどうなのか、また、今、成長している段階で手を放していい対応の部分はどういうところかということも含めながら。","voiceIndex":129,"id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"１.８倍に増えたということで、それだけ子どもたちにとっても使いやすいものになったのかなと思います。学校現場でも春の段階で相当混乱したというふうに聞いているのですけれども、その対応について、区教委としてはどのように今後お考えでしょうか。","respondent":"村尾教育総合支援センター長","answer":"今後もこの専門員の方々をうまく活用しながら、学校間の連携であったり、また、それ以外に臨床心理士も年間１０回巡回するということも含めまして、区としてこの子どもたちへの支援、それから指導の充実を図っていこうというふうに考えております。","voiceIndex":131,"id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"ただ、今後、他区でも専門員の需要が増えていくということ。それから、介助員と専門員ではかなり待遇の差があると感じております。それは時給換算だけではなくて、有給がある等々、非常に立場が違う中で、今後、介助員の不足がさらに進んでいくのではないか。そうすると、区教委として、この介助員の確保について、さらに積極的な施策を何か考えていく必要があるのではないかと思いますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"介助員も、今は業者委託という形をとっておりますけれども、そことの連携を図りながら、業務または待遇等の向上も図るとともに、また地域の中で、例えばボランティアという形で協力できる方がいらっしゃらないかどうかということも、現在視野に入れて検討を進めているところです。","voiceIndex":133,"id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"図書館資料についての質問に移ります。これが３分の１になっているというのは、これは資料収集の方針が抜本的に変わったということなのか、それとも本年度の予算でもやはり６,０００万円程度となっておりましたが、一時的なものなのか教えてください。","respondent":"木村品川図書館長","answer":"表現の仕方といたしまして、品川図書館、それから地区図書館、指定管理の運営経費、そこの中に入っておりまして、合算すると１億７,０００万円、例年そのぐらいのペースで購入しておるものです。","voiceIndex":135,"id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"全体では変わらないということで安心をいたしました。これは選書のシステム自体も変わったということなのでしょうか。それとも決算、予算の書き方だけが変わったということなのでしょうか。それを教えていただければと思います。次の質問もいたします。これを今後どのように考えていらっしゃるのか、あるいは、学区の見直し等も含めての対策を考えていらっしゃるのか教えてください。","respondent":"木村品川図書館長、篠田学校計画担当課長","answer":"平成２７年度から指定管理者制度を導入いたしまして、まず一次選定を指定管理者、中央館は委託をしていますが、委託の事業者がまず一次選定をする。それから二次選定を区の職員で全体調整をするというような仕組みに変えております。東海中学校に関しましては、建物自体が非常に古くなっているというのは確かに私どもも認識していますので、必要な対応はとるべきであろうとは考えているところではあるのですけれども。","voiceIndex":137,"id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"選書の仕組みを変えたことによるメリット、あるいはねらいがあれば教えてください。東海中学校のほうは、そうですね、一応理解いたしました。","respondent":"木村品川図書館長","answer":"利用者の方の層もいろいろ変わります。そういう部分で、蔵書構成に関しまして、各館の特色をより生かすというような意味で、そういう部分ではきめ細かいニーズに沿った選定ができているというふうに、それがメリットと感じております。","voiceIndex":140,"id":"exchange-065"},{"speaker":"あべ委員","kind":"質問","question":"ＩＣＴを活用した学習について、簡単にお伺いしたいと思います。タブレット配布などもされているわけですけれども、特に特別支援、ここではいわゆる学習だけではなく、例えば、読字障害の子に対して、それに適したアプリを使うといったような使い方も含めての利用となっているのかどうか教えてください。","respondent":"村尾教育総合支援センター長","answer":"特別支援教育でのタブレットの部分につきましては、今、委員おっしゃるとおり、学習支援関係の読み書き、また計算、さまざまなものに活用できるようなアプリで学習をしております。","voiceIndex":142,"id":"exchange-066"},{"speaker":"あべ委員","kind":"質問・要望","question":"特に学習障害を持ったお子さんに対して、タブレット等のアプリでかなり活用できるものが増えていると思います。前にもお願いしたと思うのですけれども、普通学級等においても、やはり学習障害の障害の特性によって授業の飲み込みがなかなか厳しいというようなお子さんに対しては、個々のニーズに応じてこうした機器を使うということも視野に入れていただきたいのですが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"通常学級におきましても、現在も既に読みがなかなか厳しいということに対しては、音声ペンを使ったものという、それはタブレットとは違うのですけれども、今後、そのような形、合理的配慮という視点からも必要になってくると思いますので、今後検討してまいります。","voiceIndex":144,"id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ積極的に検討していただければと思います。以前そういったことを導入するのに一番心配されたのが、やはりほかのお子さんと違うものを一人だけ持っていることが、何かといじめの対象になったりするのではないかというようなことが言われておりました。ぜひそういったことがないように、教室内での指導も含めて充実していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-068"},{"speaker":"渡部委員","kind":"質問","question":"東京がいい中で、城南地区がいい、その中でも品川区がいいというようなお話で、それでお話をしていますと、やはり保護者の目線でいろいろな学校、公立学校ですから、本当は画一的と言ったらおかしいのですけれども、いわゆる公立学校なのだけれども、品川の場合は、それぞれの学校の特色があってというので、物の本で読んだのか、人の話を聞いたのか、意外とと言いましょうか。","respondent":"有馬学務課長","answer":"しかしながら、４月に新たな校種として義務教育学校が設置されたということで、ここの取扱いについてきちんとＰＲしていこうということで、これは小学校１年生のときに入学して中学校へ上がるときにどうなるのか。","voiceIndex":149,"id":"exchange-069"},{"speaker":"渡部委員","kind":"質問","question":"これから選択行動とかがありまして、また例年のとおり、皆さん、地域の方々もそわそわしたり、さまざまなうわさが流れてくると思うのですけれども、実はこの後、インクルーシブ教育の関係で特別支援のことについて伺っていくのですけれども、そもそも基本的に今の年齢で来年度入学する予定の、小学校１年生に入学する予定のお子さんのいる家庭には、これを全戸配布されているわけですね。","respondent":"有馬学務課長","answer":"このパンフレットにつきましては、住民基本台帳をもとに、新入学となる全世帯に対して郵便で送っているです。","voiceIndex":151,"id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"各校特色がありますので、真剣に選ばれる、選ばれると言ったらおかしいですけれども、学校をどこにしようと考える方は、伺ったところですと、４校、５校回っている方もいるということですので、いい学校を見つけていただければと思うのですが、特別支援教育について伺っていこうと思います。先ほど、人数をほかの委員が伺っていたので聞きました。","respondent":"村尾教育総合支援センター長","answer":"本年度、劇的にこの特別支援教室の人数が増えた１つの要因といたしましては、先ほど来、説明もしておりますけれども、今まで子どもが学校に通っていて、そのために保護者の付き添いが必要であった。","voiceIndex":153,"id":"exchange-071"},{"speaker":"渡部委員","kind":"質問","question":"これからまた新年度、その翌年度という形で、この仕組み、制度が続くわけですから、これがまた当然周知をされてきますと、またこの数字は増えてくるのかなというふうに思っているところです。それで、先ほどの質問にもあって、東京都が専門員を月に１６日ということで、ただ、その学校自身が特別支援教室、巡回で来てもらうのは週１日、わかりました。","respondent":"村尾教育総合支援センター長","answer":"その中で子どもへの指導もある部分できるということであれば、介助員との内容なのですけれども、あくまでも専門員は、その特別支援教室に来ている子どもたちへの支援に入っていくということ、介助員は、その子が通常学級に戻ったときに。","voiceIndex":155,"id":"exchange-072"},{"speaker":"渡部委員","kind":"質問・要望","question":"私自身も、例えば他町会のことであれば、同時期に役員をやっていた方に、ちょっと町会長とつないでくれですとか、町会でこういうことというようなことで、意外とその連携がスムーズになっていたと確認をしているのですけれども、その辺の部分で、地域とのつながりという部分で、ＰＴＡとスクールコーディネーターとのかかわりあい、もしくはすみ分けとかというのはどういうふうにお考えでしょうか。","respondent":"熊谷指導課長","answer":"今回、学校地域コーディネーター、これは区の非常勤職員でありますけれども、校内に、職員室に机を置いて、その中で教員とつなぐ、地域とつなぐ中で、また保護者、ＰＴＡともつないでいくという中で、実際にＰＴＡの活躍する部分、また地域とのつなぎ。","voiceIndex":157,"id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"ただ、こういう仕組みができた以上、それがコーディネーターの仕事となるわけですね。その辺の線引きといいましょうか、では、今後はＰＴＡに頼まないでコーディネーターがそれをやっていくのか、逆に学校からコーディネーターを通ってＰＴＡにおりてくるのか、そうなると、そもそもの話が全く違うと思うのですけれども、僕、そういう関係がちょっと知りたかったので、教えていただければと思います。","respondent":"熊谷指導課長","answer":"ＰＴＡと町会をつなぐ立場でもあるということで、そういった意味も含めて、コーディネーターを置いていきたいというふうに考えております。","voiceIndex":159,"id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"わかったような、わからないようなというところでございまして、一生懸命理解しようとするのですけれども、なぜこの質問をしているかといいますと、いわゆる地域の理解がないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-075"},{"speaker":"あくつ委員","kind":"提案","question":"私からは、主に１７８ページ、品川図書館運営費、幾つかお伺いをします。図書館での障害者施設製品の販売について伺います。荏原図書館だけではもったいないので、ほかのところにも拡大したらいかがですかというふうにご提案しましたら、その後、展開も考えておられる、検討するというようなご答弁でしたが、進捗状況について伺います。","respondent":"木村品川図書館長","answer":"これから他館でも販売できるようにというところで、福祉施設と協議の上、拡大を検討していく予定です。","voiceIndex":163,"id":"exchange-076"},{"speaker":"あくつ委員","kind":"提案","question":"１つは、今回、先日の文教委員会で大崎図書館の移転に伴って、大崎駅の西口に図書の取次スペースを設置検討中であるとのご報告をいただきました。それはやはり図書館内で販売するということも１ついい取組みだと思うのですが、やはりまちのにぎわいの中にある、駅のにぎわいの中にある、そういう施設でそういうことをやるということも、１つ大きな意義があるのではないかと思うのですが、いかがでしょうか。","respondent":"木村品川図書館長","answer":"私どものほうでも、これから魅力ある図書館づくりというところで、内部でも検討チームをつくりまして、実際に二子玉川も見に行かせていただいております。そういう中では、ああいう拠点、魅力を存分に生かした形で、そういう形の展開は視野に入れているところです。","voiceIndex":165,"id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただ、残念ながらＷｉ－Ｆｉに関しては、ちょっとやはり出遅れている感がありますけれども、ここはぜひ、先ほど申し上げた趣旨から、図書館法には資料の収集とかもありますけれども、調査研究であるとか、あとはレクリエーションの機能を果たすというところもありますので、昭和２５年にできた法律ですから、そこまでインターネットとかは考えていなかったと思うのですけれども。","respondent":"木村品川図書館長","answer":"そういう意味では、スペース的な問題もありますので、そういう部分、慎重に運用ルールを整理しながら、もちろんセキュリティも確保しながら、研究課題として引き続き進めてまいりたいというふうに考えております。","voiceIndex":167,"id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、もう時間がないですけれども１点だけ。さまざま、確かに都立の先ほど申し上げた図書館などには、もともと公衆電話のボックス、公衆電話を取っ払ってしまって、そこで話ができるというものもあったりするそうですけれども、ぜひこの点についても、さまざま課題は多いとは思うのですけれども、こういう区民のご意見がありますので、ぜひ検討していただければと思いますが、いかがでしょうか。","respondent":"木村品川図書館長","answer":"電話ができるスペースというお尋ねです。委員もおっしゃいましたように、確かに難しいところがかなりあります。集中、静寂が求められる場所でもありますので、ただ、今、お声をいただいて、何か私どもでできることがあるのか、これから考えてまいりたいと思います。","voiceIndex":169,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"ましてや学校選択をしているものですから、自分の地域との関連性も当然出てきますので、シミュレーションを含めながら、どういうふうに避難をしていったらいいのかということを整理する必要があるのかなと考えています。その関係が１つ目。それから３つ目は、１８３ページの給食食材放射性物質検査ですが、これもう役割は終わっているのではないですかということでのご意見をお聞きしたいと思います。","respondent":"品川庶務課長、有馬学務課長","answer":"学校で行う避難所訓練ということで、そこの周知に関してということでのお話かと思いますが、こちらは保護者に学校を通じて連絡という体制は、少し校長会とも相談して、どういうふうに行っていくべきか、それから。要は、これはニーズの兼ね合いということがありまして、どこでやめるのか、この辺につきましては、また慎重に検討をしていきたいというふうに思っている事項です。","voiceIndex":172,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"ＰＴＡの方々の避難に対する意識です。そのお考えをお聞きします。そこもこういう教育環境の中でこういうふうに変えますというような説明の仕方は、順番になるのかどうかわかりませんけれども、しっかりと伝えていただきながら、理解を求めて子どもたちの教育環境の整備をしていただきたいと考えていますので、地域の方への説明を含めてお答えをお願いします。それはわかります。それぞれお願いします。","respondent":"品川庶務課長、有馬学務課長","answer":"それからあと、人工芝の導入にあたっては、地域に少し周知が足りなかったという経過もあるので、この辺についても検討してまいりたいと思います。さまざまな声を聞きながら判断してまいりたいと思います。","voiceIndex":175,"id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１７２ページの義務教育施設整備基金積立金について伺いたいと思います。平成２７年度末で、総額幾らになるのかということ。現在、何校改築が済んでいて、今後、改築する学校は、小学校、中学校、それぞれ何校残っているのか、そしてその計画はどのように立てられていくのかについてもお聞かせください。","respondent":"品川庶務課長、篠田学校計画担当課長","answer":"現在の義務教育施設整備基金の残額ですが、平成２８年度５月時点ですけれども、約１８０億円となっています。中学校につきましては６校残っている形になっていますので、こちらに関しましては、例えば学校の老朽度ですとか、あるいは就学人口の状況ですとか、もろもろさまざまな要因を踏まえまして、順次。","voiceIndex":179,"id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、もうこの小中学校は義務教育になるわけですね。憲法で保障された義務教育であるにもかかわらず、国がこれだけしか補助金を出さないというのは、あまりにも少なすぎるのではないかと思うのですけれども、国が責任を持つべきというところで、やはり補助金の割合や額を増やすよう求めるべきだと思うのですけれども、いかがでしょうかというのが１点です。","respondent":"品川庶務課長、篠田学校計画担当課長","answer":"１点目の補助金の要望というところなのですけれども、２３区で庶務課長会を開催しております。その中で毎年課題等を抽出しまして、東京都、それから国等へ意見を申し上げることをやっております。こちらの扱いですけれども、今回の学事制度審議会での課題の中に学校選択制というのが入ってくるような形で、今、私どもも考えておりますので。","voiceIndex":182,"id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補助金については、強力にこれからも増額を求めていっていただきたいと思います。そういうことからすると、前提そのものがずれていると思うのですけれども、そこら辺の認識はいかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"実際問題として、荏原地区で見ますと、西地区、東地区とも平成２０年度の答申時には人口が減少していくというふうに思われていたところですけれども、実際には、ほぼ横ばい水準で変わっていないというような状況ですので、答申で書かれているような形での学校のあり方。","voiceIndex":185,"id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところからすると、地域の住民の声も、それから就学前の子どもたちの保護者の声もきちんと聞きながら、地域とともにある学校づくりということで、丁寧な議論を行うということで書かれていますので、ぜひこういう視点でやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問","question":"成果報告書の１７４ページ、英語科についてと、１７５ページ、特色ある教育活動経費全般で伺います。これは新たな取組みも２０２０年のみならず、国際化の中で出てきているかと思うのですが、特に目を引いたのが、日本人としての自覚と誇り、これは本当に僕らが考えている以上に世界が日本や東京をどう見ているかという観点からすれば、一番ある意味欠けているかもしれない。","respondent":"熊谷指導課長","answer":"オリンピック・パラリンピック教育では、やはりオリンピック・パラリンピックの精神、スポーツ、文化、環境、大きな４つのテーマがありますけれども、それぞれ４×４と言いますけれども、４つのアクション、学ぶ、見る、する。","voiceIndex":189,"id":"exchange-086"},{"speaker":"渡辺委員","kind":"質問","question":"ただし、その１回が興味を持ったり、インパクトを与えてもらったりという中で、大事な一歩であり、継続して学ぶという手段で、１つ日本の伝統・文化に関連して、また、オリ・パラの発信力に役立つのではないかと、ごくごく当たり前なことを伺います。みんなでやる。それとあとは、本当に教育委員会がリードすべきと私は思うのですが、いかがでしょうかという意味で、昔の遊びで伺えればと思います。","respondent":"熊谷指導課長、村尾教育総合支援センター長","answer":"そういった遊びを通じて、昔遊びを通じて学んでいく日本の伝統のよさということもあります。これは絵本等で伝えていくのではなく、実際に体験していく、そういったことが非常に重要であるというふうに感じております。昔遊び、今現在、学校ではということもここでご説明できればと思いますが、小学生一、二年生に生活科というものがあります。","voiceIndex":191,"id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"というのは、特に児童センターでうまくプログラムに混ぜていたり、あるいは、地域センター、イベントで目にする、そういうときにやはり人の反応がすごくいいものですから、特に主役が子どもだという点で、学校で何か生かせないか、本当のプログラム、カリキュラムの中には厳しいけれども、いろいろな波及効果が見込めるのだなと思ったので、直接ではないのですが、全体として、あるいは。","respondent":"熊谷指導課長","answer":"現在、鮫浜小学校、浜川小学校、伊藤小学校、鈴ヶ森小学校、大原小学校、上神明小学校、浜川中学校、鈴ヶ森中学校、冨士見台中学校、日野学園、伊藤学園、八潮学園、荏原平塚学園、品川学園、豊葉の杜学園で拡大しています。","voiceIndex":194,"id":"exchange-088"},{"speaker":"渡辺委員","kind":"質問","question":"もう１つ、全般で英語教育という観点で聞かせてください。品川区の総合戦略の中で、数値目標もありました。この辺のねらい、平成３１年度の目標数値だと１５校全校ですよね。全区展開を目標に掲げて、この辺の英語科の取組みと、これは僕、大変究極の目標というか、最大限の目標だと思うので、この辺を詳しく伺いたいのと、もう１つ、体力向上事業もあわせて全区展開、全校展開だと思います。","respondent":"熊谷指導課長、村尾教育総合支援センター長","answer":"今、拡充を目指していきたいところでありますが、環境整備ですとか、さまざま課題も見えてまいりましたので、それの克服を考えているところです。そして３つ目には、本年度から実際には大きく取り組み始めましたけれども、ワンミニッツエクササイズということで、朝の時間であったり、また各家庭においてできるような、そういうものを位置づけ、子どもたちの体力向上とともに。","voiceIndex":196,"id":"exchange-089"},{"speaker":"塚本委員","kind":"質問","question":"初めに、１７７ページ、特別支援教室整備です。ここでモデル実施をされているというふうになっておりますけれども、このモデル実施においてわかったこと、そしてそれがこの平成２８年度からの全小学校への特別支援教室の展開に際して、どのように生かされたか、フィードバックされているのか、この辺をお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"昨年度、平成２７年度につきましては、拠点校を４校として、４校から実際に数名程度の子どもたちの在籍校に通って、指導内容、方法、形態等を研究した、その成果が本年度、平成２８年度。","voiceIndex":200,"id":"exchange-090"},{"speaker":"塚本委員","kind":"質問","question":"コミュニケーションということで、これもこれまでの質疑で、訪問指導員とは別に非常勤専門員が月１６日、各学校に１人ずつ配置されていて、その指導員と学校側の担任の間の連携に一役買うというのですか、そういうようなお話もあったと思うのですけれども、ここでお聞きしたいのは、まず、都から派遣される非常勤専門員の方が、資格的にというか、どういう方々であるのか、専門員としてどういう。","respondent":"村尾教育総合支援センター長","answer":"そうすると、担任のほうも、通常授業でいうと、なかなか個別にはすぐ対応はできない部分もあるのですけれども、今その子にとって特別支援教室で行っている指導のあり方を知っていることで、横に行って、もうちょっとフォロー的に学習の支援ができる、また、個別に宿題があったり。","voiceIndex":202,"id":"exchange-091"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。そこで、保護者の方と訪問される指導員の方、ここのコミュニケーションというのは、どのように考えているか、いろいろな形で、保護者側からはいろいろなことを聞きたいという場合があるのではないかなとも思うのですが、その辺についてはいかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"その子一人ひとりの個別指導計画がありますので、それに応じて、例えば１学期、この子についてはこういうような学習をしていきますということに対して、保護者の同意をいただいて、そして進めていくということで、その辺は今までの形が変わった分、保護者と担任。","voiceIndex":204,"id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"そこで、今現在、市民科は５つの領域、自己管理、人間関係形成、自治的活動、文化創造、将来設計という５つの領域と、１５の能力ということで体系化をされておりますが、これまで品川区でこの市民科をやられてくる中で、児童や生徒を取り巻く教育環境がいろいろ変化していく中で、いわゆる市民科の体系だった単元は、いろいろそのときに応じて適正化するというか。","respondent":"村尾教育総合支援センター長","answer":"委員ご指摘のとおり、市民科というのは、品川区の教育要領も含めて、中心として今までもやってまいりました。５領域１５能力という考え方に基づき、小学校、中学校がそれぞれの発達段階に応じて身につけるべき力を育んでいくというような考えで進めております。","voiceIndex":206,"id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"今ご答弁いただいたところで、そういうカリキュラム検討委員会ですか、そういうものを立ち上げながら、その時代に応じてということだったのですけれども、ちょっと過去の議事録などをこういう市民科関係のところで検索したりすると、最近、「生き抜く力」みたいなキーワードが結構議論の中で散見されておりまして、今。","respondent":"村尾教育総合支援センター長","answer":"本区の市民科の大きなつくり方としては、例えば自己管理から将来設計まで５領域あるのですけれども、低学年は自己管理が結構時限数が多く、８年生、９年生につきましては、将来設計、キャリア教育的な時間を多く取り上げているというようなところで、今。","voiceIndex":208,"id":"exchange-094"},{"speaker":"塚本委員","kind":"意見","question":"本当に品川区として、今年行われた品川区教育フォーラムなどでも、この市民科というのは１つの大きな柱として、品川区の教育としての特徴を表すものとして取り組まれているものだと思いますので、本当に子どもたちにとって、この「生き抜く力」、こういうものがしっかり身につく形で、今後とも取り組んでいただければと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":210,"id":"exchange-095"},{"speaker":"高橋（し）委員","kind":"意見","question":"１７４ページの学校公開経費、１７９ページ、学校ＩＣＴ活用経費、１８４ページ、学校施設建設費、時間があれば、中学校の部活動のことです。これを受けて、平成２８年度は実施設計ということになっているかと思うのですが、工事の着工とか竣工は結構ですので、この実施設計のほうの進捗状況についてお尋ねします。","respondent":"篠田学校計画担当課長","answer":"城南小学校の実施設計につきましては、この春に基本設計が終了しましたので、それに引き続き、実施設計を今年度取り組んでいるところです。","voiceIndex":212,"id":"exchange-096"},{"speaker":"高橋（し）委員","kind":"質問","question":"その実施設計の中で、委員会では図などを見せていただいたのですが、当初の予定とは変更を余儀なくされてきたという状況があるのではないかと思いますが、その辺についてのご説明をお願いします。","respondent":"篠田学校計画担当課長","answer":"基本設計の段階で、隣のお寺と学校の敷地との境界ぎりぎりのところに大きなイチョウの木が立っておりまして、学校のほうにもかなり張り出してきているというようなことがございましたので、当初の設計の時点でも、その木の保存に関しては。","voiceIndex":214,"id":"exchange-097"},{"speaker":"高橋（し）委員","kind":"質問","question":"木の保存に関連して設計のほうの変更がということなのですが、それは予算上で何か措置が必要になる設計の変更なのかということ。それから、工事はしていただいて、竣工時期でしょうか、そちらのほうの影響などはあるのでしょうか。","respondent":"篠田学校計画担当課長","answer":"予算上の対応ですけれども、設計がある程度進んできた段階で若干変更を加えているということで、当然、工数等変わってきていますので、その辺、何らかの対応が必要になってくる部分はあろうかと思いますが、その辺は、現在、調整中です。","voiceIndex":216,"id":"exchange-098"},{"speaker":"高橋（し）委員","kind":"質問","question":"予算上の措置や進捗状況については、逐一のご報告をお願いしたいと思います。それからあと、竣工については、在校生、また新入生等に影響のないように、よろしくお願いいたします。そして、中学校３年生は受験の時期ですので、中学校２年生（８年生）がプレゼンなどに参加すれば、プレゼンのそういった経験にもなるということがありますが、そういったことについてのお考えをお伺いします。","respondent":"有馬学務課長","answer":"今、委員からご提案のありました一斉にやるというのも１つの考え方であろうかと思います。今も近隣のところでは、調整をしながら、なるべく重ならないようにということで、校長同士の調整をしておりますけれども、１つの案としてこれから検討をしてみたいと思っているところです。","voiceIndex":218,"id":"exchange-099"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そうなると、今後、子どもたちが大人になったときに求められる能力、資質も、これは大きく変わってくるわけでありまして、その対応をするには、今から学校教育も大きく変わらなければいけないですし、教師の皆さんの存在も多くの変化がなされていくのではないかと思いますが、これからの時代に求められる子どもたちの資質と能力、そしてこれからの教育、また、教師のあり方について。","respondent":"有馬学務課長、村尾教育総合支援センター長、熊谷指導課長","answer":"新たな課題となるソーシャルメディアの活用につきましてですけれども、これは。２点目のこれからの情報化社会の中で子どもたちに求める力ということで、私どもとしては大きく３点、情報活用の実践力、きちんとした活用。成果検証につきましては、今後、品川教育検討委員会教科等検討部会で内容検証していくところです。","voiceIndex":224,"id":"exchange-100"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひその伸びた部分に関しては、さらに強化をしていただき、また、まだまだ足りないという部分があれば、それは今までにやっていた授業を見直しても、違うことをやってでもそちらも伸びていけるようなことを進んでやっていただければと思いますので、これは要望で終わりますが、ぜひこれからの時代に求められる教育の部分に関して、もう一度ご答弁いただければと思います。","respondent":"熊谷指導課長","answer":"ＳＮＳも含め、ＩＣＴ教育につきましては、今後、品川教育検討委員会の中でも内容面も含め検討していきたいというふうに考えております。","voiceIndex":228,"id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"１７４ページ、プラン２１推進事業と、１７６ページの特別支援教育費の２点で伺います。プラン２１のほうですが、教育フォーラムで、このプラン２１について、さまざまな成果が発表をされておりました。その４項目ですけれども、その他のことでも結構です。一体型と分離型について、何か成果に違い、傾向があるのかどうかということをお知らせいただきたいと思います。","respondent":"熊谷指導課長","answer":"ただ、保護者アンケートの中で、小学校との連携が充実していると答えたのは、一体型が９２.４％に対し、分離型が８２.４％ということで、一体型のほうが１０ポイント程度上回っておりました。","voiceIndex":232,"id":"exchange-102"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、この一体型と分離型の今の４項目でしたけれども、さらに比較検討できるような、今後、分離型のいわゆるそういう課題の解消を目指すということが１つの大きなテーマに当然なっていくわけですので、さらに詳細なデータと分析をする、そのデータが手元にあるのかどうかということも含めて、さらに研究、分析、データの収集を、私は行っていかないと、情緒的な主観的なということではなくて、客観的な。","respondent":"熊谷指導課長","answer":"それがまさに「品川教育ルネサンス～For Next Generation～」になってくると思います。これからまた学事制度審議会ですとか、品川教育検討委員会、立ち上がってまいりますけれども、その中で、そうした丁寧な対応をしていきたいというふうに思っています。","voiceIndex":234,"id":"exchange-103"},{"speaker":"若林委員","kind":"質問・要望","question":"特別支援教育については、個別の指導計画と、個別の教育支援計画という２つの計画が個々のニーズに応じて立てられているというふうに理解をしておりますので、この作成の状況を全体的にお聞かせをいただきたいのと、今般、教育再生実行会議の中で、この指導計画とか教育支援計画以外に、インクルーシブ教育を大きく進めるにあたって、同じような言い方になるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"これから区といたしましても、教育委員会、それから子ども未来部、保育課との連携も図りながら、それから国の方向性を確認しながら、それぞれ充実した子ども一人ひとりの教育的ニーズを把握し、できる支援を高めていく、そういうような考えです。","voiceIndex":236,"id":"exchange-104"},{"speaker":"若林委員","kind":"質問・要望","question":"そういたしますと、前に一般質問で取り上げましたけれども、庁内療育支援ネットワークが、今後、課長級で結成されて、情報共有シートの検討がまたさらに進められていく、こういういわゆる情報共有シートという性格のものを、品川区は今、先がけてやっているという認識でよろしければお答えをいただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-105"},{"speaker":"伊藤委員","kind":"確認","question":"私は、１７３ページ、いじめ防止対策について、それから１７４ページ、プラン２１推進事業に関連して質問します。当然、その両親は、Ａ君の背中を写真撮影をして、みみず腫れの写真を持って当該の学校に相談しに行きました。学校はＢ君を呼び出して状況を確認しましたけれども、当時の２人の関係に十分注意を払うことなく、Ｂ君の主張により、いじめはなかったと結論づけられました。お願いいたします。","respondent":"村尾教育総合支援センター長","answer":"今、委員のご指摘いただいた部分を含めまして、区といたしましては、まずいじめ防止という視点、まず軽微ないじめも決して見逃さないというような視点が１点目。２点目につきましては、教員は決して１人で抱え込むことなく、必ず情報を共有し、組織で対応していくこと。","voiceIndex":241,"id":"exchange-106"},{"speaker":"伊藤委員","kind":"意見","question":"部活動の人間関係、いろいろなところで注意を払っていかないと、今おっしゃったことの展開はできないと思うので、私としては、複数の教師がこういう問題に共通して対処していくとか、学校全体で問題を共有して対処していく仕組みがさらにとられていかないといけないと思うのですが、改めてお話をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"日々子どもたち同士が、さまざま豊かな人間関係をつくることの中で、やはりけんかもあると思います。そういうときにも、きちんと子どもたち同士が話ができる、そういうことが必要かなというふうに考えております。","voiceIndex":243,"id":"exchange-107"},{"speaker":"伊藤委員","kind":"質問","question":"一般的にいじめというのは、いじめる側が、いじめられるほうよりも体力や、さまざまな面で自分が優位であると認識することから始まるわけです。だけれども、一人ひとりの子どもの中に届く制度を展開していくときには、こういう赤ちゃんふれあい事業を通して、中学生の心に具体的にしみ入るような、そういう授業を展開していくといいと思うのですが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"ただ、一方、子どもたち一人ひとりの抱えている問題はあるにしても、やはりいじめということについては、決して許されないものであるという一線はしっかりしながら、子どもたち一人ひとり、しっかり育成を考えていこうというふうに考えております。","voiceIndex":245,"id":"exchange-108"},{"speaker":"伊藤委員","kind":"質問","question":"ＨＥＡＲＴＳを展開したりとか、学校風土の調査だとか全て必要なのだけれども、やはり原点に立ち返って、子ども一人ひとりが育ってきた背景を理解していただいて、相手を傷つけることはこんなことなのだということを直接、感性でわかってもらうことのほうが、私はより効果的だと思うのですが、いかがでしょうか。お願いいたします。","respondent":"村尾教育総合支援センター長、高山子ども育成課長","answer":"豊かな人間性、また社会性という部分につきましては、今後、私どもとしても学校からのいろいろなアイデアや、また、外部の力、外部の人材を活用して、子どもたちの心の育成を進めていければというふうに考えているところです。平成２７年度におきましては、１４の児童センターにおきまして、実施回数は合計４２回、実習生としまして１,７５６名の参加を見ているところです。","voiceIndex":247,"id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もしそれがそうであるならば、もう少し具体的にそれを展開していって、東京都と連携をした上で、さまざまな通信会社と提携をした上で、できるだけ個人が特定された場合ですけれども、その情報が当該学校にフィードバックされてくる、今まで目に見えなかったＳＮＳ上のいじめを具体的に情報の単位で拾って、当該学校にフィードバックをしていただいて。","respondent":"村尾教育総合支援センター長","answer":"そのため、今後もこのインターネット、いわゆる携帯電話やスマホによる対応については、研修、また子どもたちへの教育のほうは十分進めていこうと考えております。一方、教育的意義といたしましては、やはり監視よりもきちんとした育成も考えていかなければいけない。","voiceIndex":250,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただ、これだけＳＮＳのことが青少年の犯罪やらいろいろなことで騒がれるという状況の中ですから、もちろん品川区単独でできると思っていないので、ある意味、国をも含めた上で、総合的な対策をとって、情報が、難しいですよね、限定されるのは難しいです。過日、一般質問で、大井第一地区町会連合会の正式決定として、この地区に小中一貫校を建設してほしいという要望が出されたということを聞きました。","respondent":"篠田学校計画担当課長","answer":"これまでいわゆる小中一貫校として地域バランス等、さまざまな点に配慮して６校整備しましたけれども、今回、義務教育学校化されたということで、そういった考え方について、学事制度審議会の中で一定整理を図った上で、その先を検討していくべきものと考えているところです。","voiceIndex":252,"id":"exchange-111"},{"speaker":"南委員","kind":"質問・要望","question":"１８２ページの学校給食費をはじめとした教育費の父母負担軽減を求める質問をしたいと思います。今、ネットを開くと教育費の負担が重い、こういう記事が結構目について、軽減してほしいという声は広がる一方だと思います。各学校で父母負担でお願いしているものは、どのようなものがあるのか、それぞれの項目と年額にするとどのくらいになるのか、まず教えていただきたいと思います。","respondent":"有馬学務課長","answer":"それ以外には、ＰＴＡ会費、生徒会費等が個人の負担という形になっているものです。","voiceIndex":256,"id":"exchange-112"},{"speaker":"南委員","kind":"質問・要望","question":"それと、金額について伺ったのです。教えていただきたいと考えていますけれども、品川区が発表している就学援助費の単価表、ここを見ると、ここを参考にどのくらいのものがあって、どのくらいかかるかというのがおおよそつかめはするのですけれども、実際問題、どのくらいということを教育委員会自身も認識しておられるのかというところを確認したいと思って伺っておりますので、教えてください。","respondent":"有馬学務課長","answer":"あとは部活動の関係で言いますと、種目によって大分違いますので、そういったところでは個人が選んでいるスポーツなり文化系などによって差が出てくるものというふうに認識しております。","voiceIndex":258,"id":"exchange-113"},{"speaker":"南委員","kind":"質問・要望","question":"もろもろ入っていると思うのですけれども、これらは全部教育活動の中で発生する費用だという認識でいいのですか。その点についての認識も伺いたいと思います。そういう状況のときに、これらの教育費、父母負担がやはり当然８％分がかかってくるわけですし、とりわけ給食費なども食材にはかかってくると考えていますので、その点についての状況がどうなっているのか教えていただきたいと思います。","respondent":"有馬学務課長","answer":"８％分の影響ということですけれども、品川区は、先ほども言いましたけれども、財調単価を見ながら学年によって多少上乗せをしているというようなこともありまして、全体としては、そういった中で飲み込んでいるものというふうに認識しています。","voiceIndex":260,"id":"exchange-114"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ品川区も区長会等々、あるいは２３区の課長会等々、さまざまな機関で国にどういうふうに言っているかまで私は調べてこられなかったのですけれども、そういう方向性を要望として改善を求める、そういう姿勢は示していただきたいと考えています。これも私は非常に重たいというふうに印象を持つのですけれども、この点についての区の教育委員会の見解も伺いたいと思います。","respondent":"有馬学務課長","answer":"そんな中でも、就学援助でこの給食費はご存じのとおり支給をしているものでございまして、認定された４,６００人の方については、これは無償で提供している、区が負担をしているですので、十分品川区の施策としては。","voiceIndex":262,"id":"exchange-115"},{"speaker":"南委員","kind":"質問","question":"ごめんなさい、低所得者への配慮のところがあまりよくわからなかったのですけれども、もう１回教えてください。","respondent":"有馬学務課長","answer":"給食費を年間で５万円から６万円ぐらい負担していて、それが保護者にとって負担になるのではないかというご意見でしたけれども、実際に就学援助の支給品目の中に学校給食費が入っておりまして、全体では４,６００人、約２万人弱の生徒のうちの４,６００人については。","voiceIndex":264,"id":"exchange-116"},{"speaker":"南委員","kind":"質問","question":"就学援助はそういうことで給食費についても対応しているという話なのですが、私は、全体的に就学援助、低所得者の人への配慮はもちろん必要なことであって、やるべきだというふうに思っておりますし、また、品川区としては、第三子に対する補助もやっているという、給食費の補助を、第三子以降の方に対する補助もやっているということですから、それはそれとして、多子世帯への補助。","respondent":"有馬学務課長","answer":"多子家庭への補助ということで、これも就学援助よりもさらに所得要件を緩和して行っているものです。それから、無料化につきましては、施策がおそらく定住化とか少子化対策とかということで、目的が違ったところで行っているものというふうに認識しております。","voiceIndex":266,"id":"exchange-117"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１７７ページの文化財保護事業、１８０ページの校庭人工芝生化、ほかの委員から出たものとダブるかもしれませんけれども、ご容赦いただきたいと思います。養生を全部しなければいけないと、いろいろあった中で、課長のほうでは、しっかり地域に学校のほうでご説明をするのが本来の筋なのだというような感じのお話があったと思うのですけれども、それはどうなのですか。","respondent":"品川庶務課長","answer":"それから２点目です。校庭の人工芝ということで、こちらについては、今まで約１０校程度、学校の人工芝を進めてきたのですが、今まで導入をしたときに地域から反対の声がなかったというような経過が我々の認識としてもあったのかというところがあります。","voiceIndex":269,"id":"exchange-118"},{"speaker":"たけうち委員","kind":"質問・要望","question":"文化財については、そうすると、必要性は感じているのだけれども、まだ今は第一歩が踏み出せていないと、こういうふうに受けとめましたので、私は代表質問でやらせていただいて、観光部門のほうでは、今どういうふうにそれを進めようとしているのかちょっとわからないのですが、ぜひ連携をとっていただいて、もちろん外国人もそうなのですけれども、日本の我々もそうだし、もっと言えば。","respondent":"品川庶務課長","answer":"こういった状況を参考にしまして、今後の人工芝を進めていくにあたっては、仮に進めていくようになれば、地域との対応とか、そういった面についてはいろいろと考えていきたいと、このように思っております。","voiceIndex":271,"id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"１項教育総務費、４目社会教育費、１７７ページの文化財保護事業に関連して、今日は私で３人目になりますけれども、１つ。それと２点目です。３点目は、品川区学事制度審議会についてお伺いします。１点目の文化財保護事業に関連してですけれども、これは品川寺の梵鐘についてお伺いをしたいと思います。なぜなっていないのだろう。どうしてなのか、これについてお話を伺いたいと思います。","respondent":"品川庶務課長","answer":"この重要美術品というのは何かといいますと、文化財保護法が昭和２５年に制定されております。それよりも前に重要美術品等の保存に関する法律がございまして、これが文化財保護法ができたと同時に廃止となっております。","voiceIndex":274,"id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"その当時ですから国際連盟ですね。ですから、これが文化財に指定できないのですよ、確かに品川区のほうが格下ですと言われてもしようがないかなと思うのですけれども、そうではなくて、やはり何かこれを、この梵鐘にふさわしい栄誉というか名誉というか、これはやはり品川区でしっかりとすべきではないかと思うのです。それぐらいの価値があるものだと思うのですけれども、いかがでしょうか。","respondent":"品川庶務課長","answer":"この梵鐘の価値については、我々としても非常に高く評価をしているところではあります。ただ、先ほどの手続に関してのハードルが非常に高いというところもありますので、何か別の方法がないかどうかについては、少し研究をしていきたいと、このように思っております。","voiceIndex":276,"id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"よろしくお願いします。次へいきます。給食食材放射性物質検査についてです。これは西本委員が質問したのですけれども、答弁がよく聞こえませんでした。これは、民生費のほうと、子どもたちの保育園ですか、一緒にすると、年間６２０万円かかっているのですね。これは先ほどの答弁ですと、やってくれという方がいるからやめませんというふうに聞こえたのですけれども、もう一度答弁をお聞きしたいと思います。","respondent":"有馬学務課長","answer":"私が先ほど言ったのは、やめないほうがいいという声があるのでやめないと言ったわけではなくて、そういう声を聞きながら、適切に判断をしてまいりたいというようなことを答弁したものです。","voiceIndex":278,"id":"exchange-122"},{"speaker":"松澤委員","kind":"質問","question":"聞き直してよかったと思います。実はこれ、産地ではやはり農家が真剣になって検査して出しているのです。これがまた国もやり、都もやり、品川区もやる。私は安全な上に安全と言われるかもしれませんけれども、屋上屋を重ねているような気がするのです。２３区の中で、あるいは全国の中で、こういう食材の放射性物質検査、やめたところはまだないのでしょうか。その辺についてお聞きしたいと思います。","respondent":"有馬学務課長","answer":"全国の自治体を全部つぶさに調べたわけではありませんけれども、基本的には２３区の状況は把握しています。平成２８年度においても１５区実施はしております。その中でも年に５回、６回というふうに実施しているところは５区あります。","voiceIndex":280,"id":"exchange-123"},{"speaker":"松澤委員","kind":"質問・要望","question":"これ、国でも、韓国などが福島産の水産物は輸入しないとか、そんなことにもなっているのです。３点目、学事制度審議会についてですけれども、９月の第３回定例会で渡部議員が質問したのですけれども、いよいよ１０月２７日から審議会が始まります。これの審議項目、諮問項目がもうはっきり決まったのでしたらお教えいただきたいと思います。","respondent":"篠田学校計画担当課長","answer":"今度の学事制度審議会における審議項目につきましては、ただいま最終的に調整はしているところではありますけれども、基本的な方向性としましては、今後、将来の就学人口動向を踏まえまして、地域とともに小中一貫教育を一層推進していく上で望ましい学区域ですとか、学校選択制。","voiceIndex":282,"id":"exchange-124"},{"speaker":"松澤委員","kind":"意見","question":"時間がないので端的に言いますけれども、前回の答申のときに、学校規模については、区民にアンケートをとったら、３学級が望ましいというのが、２学級が望ましいより３倍以上あったというふうに書かれています。ほとんどが３学級がいい。やはりしっかりとした答申を出していただかないと、我々もこれから質疑のしようがありませんので、しっかりとした答申が出るように、ひとつよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":284,"id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"私は、１７３ページ、教育指導費全般についてお聞きしたいと思います。この間、福井の教育を視察してまいりました。ここでは公立学校の教員は、ほとんど全部と言っていいのですか、小中学校の両方の免許を保有していました。ですから、学習塾がほとんど見当たらないという状況でした。なぜ品川区では、このような取組みが、同じ日本の中でできないのでしょうか。ご見解をお聞かせください。","respondent":"熊谷指導課長","answer":"同じ日本の中でということでありますけれども、品川区と福井県でありますが、まず生活や家族構成、また、学校の数や規模など、また家庭環境なども大きく異なっている状況がありますので、単純に比較することは難しいのではないかというふうに思っております。","voiceIndex":286,"id":"exchange-126"},{"speaker":"須貝委員","kind":"確認","question":"学校教育とは何なのですか。だって、環境が違って、子どもと生徒、１対１ですよね、学校と。でも、そういう子が、私はここ１０年、プラン２１を見て、途中からですが、本当に変わっていないです。ですから、若干は底上げしたでしょう。でも、どこか目立つところはあるのですか。品川区。毎月ごとに理解度確認のためテストを実施して、そしてそれを子ども本人はもとより、親にきちんと教えているのです。","respondent":"熊谷指導課長","answer":"学力向上につきましては、ちなみにですけれども、委員ご指摘の福井県でありますけれども、福井と品川、そんなに大きく変わるのかということですが、平成２７年度、平成２８年度、全国学力・学習状況調査の結果が出ておりますけれども、ほとんど変わりません。","voiceIndex":288,"id":"exchange-127"},{"speaker":"須貝委員","kind":"質問・要望","question":"なぜ皆さん、塾へ行くのですか。実際、いいですか、塾へ行っていないお子さんが中３になりました。でも、子どもたちは高校を受験しなければいけないではないですか。品川区がやはり教育改革をこれだけやって全国に発信する気持ちがあるならば、きちんと学力だけは、学校は何のためにつくられたのですか。何ですか。でも、そこにはやはり基礎的な学力が絶対必要ではないですか。ここでお聞きします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"要は、まだ学力が身につかないのだと。でも、今、２年生から３年生、３年生から４年生、自然と上げています。でも、留年制度がありますね。ここでお聞きしたいのですが、留年をさせている子はいるのですか。そして、そういう子たちが学力が足りないと思ったら、しっかり追試をするなり、再試をするなり、実施して、子どもたちを将来きちんと支えるような仕組みづくりはあるのですか。","respondent":"熊谷指導課長","answer":"そのときに脱偏差値。子どもたちの夢や希望、そしてエスカレーターに乗せる教育ではない。子どもたちがしっかり考えて選びとっていく、それを自分の学力、そして夢、希望、それに準じたものを考えさせる、そういった教育に、進路指導に、そしてキャリア教育に変わってきたです。","voiceIndex":291,"id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"形はわかるのです。形はわかります。ですけれども、実際、以前も申し上げたことがあります。だって、過去問をやったら、わからないじゃないですか。子どもが教えてくれと言っても、いや、ちょっとわからない。それから、要は、いろいろな戸山とか青山とか、そういう自分のところで問題をつくっているところ、では、そこだって学校は教えられないではないですか。その点についてもう１回お聞かせください。","respondent":"熊谷指導課長","answer":"実際に、例えばということで、具体的にお名前を出されましたけれども、都立戸山高校ですとか、それから日比谷高校というような学校について、教員が教えられないのではないか、問題ができないのではないかというのは、それは教員に対して冒涜であります。","voiceIndex":293,"id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"だって、実際、教えていないではないですか。そんな教えていないのに教えられますよ、皆さんというのは、まず私は言ってはいけないと思うし、私立の問題など、できないのだから、やれるならきちんとやって、きちんと子どもたちを支えてやってください。次の質問にまいります。学校教育について、１７年前にプラン２１ができました。１０年前、小中一貫教育ができました。１０年したらこうなりました。","respondent":"熊谷指導課長","answer":"もちろん故きを温ね新しきを知る、過去を知るということも重要ですので、今回の「品川教育ルネサンス～For Next Generation～」につきましても、これまでやってきた教育改革プラン２１を否定するものではなく、さらに振り返って推進して発展させていく。","voiceIndex":295,"id":"exchange-131"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうふうにもしおっしゃるなら、なぜ、本当に疑問に思います。例えば、私立、私立小中学校、いろいろたくさんあります。そして、公立、全国にたくさんあります。こんなにしょっちゅう御旗を掲げている。私、これ、品川区の教育はどうなっているのだろう。僕はそういうところをやはり、ほかの人は言わないかもしれないけれども、僕はきちんと言って、教育を立派な教育にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-132"},{"speaker":"大倉委員","kind":"質問・要望","question":"１８２ページの学校給食費、１７３ページの教育指導費、不登校をちょっと教えてください。時間があれば、また伺います。学校給食費なのですが、食品ロスについて伺いたいと思います。食べ残しや調理残渣やその他、どういったことが増えているのか、減っているのかというところで教えていただければと思います。そうした取組みを行う中で、登校に至った件数や事例があれば教えてください。","respondent":"有馬学務課長、村尾教育総合支援センター長","answer":"金額については、この生ごみ処理にかかる費用としては、おおよそ１,２００万円ほどかかっているです。そこで学校とともに教育委員会のほうで、例えばアセスメントをしたり、必要に応じてはＨＥＡＲＴＳ等が家庭環境、家庭のほうに訪問する等の対応をとりながら、現在、早期発見と、早期の対応に努めている、そういう現状です。","voiceIndex":299,"id":"exchange-133"},{"speaker":"大倉委員","kind":"意見","question":"不登校については、合わせて２００名を超えるような不登校があるというところで、改善に至ったのは、昨年で小学生が１３名、中学生が２０名ということで、これは文科省の中高生を中心とした子どもの生活習慣づくりに対する検討委員会というところで、生活習慣が身についている子どものほうが学力が高かったり、不適切な睡眠は学習や運動能力に影響し、不登校。","respondent":"有馬学務課長、村尾教育総合支援センター長","answer":"ただ、学校によっては、食べ残しをなくそうというような取組みをやっているところもあると思いますので、栄養士等を通じてそういった取組みをまた進めていきたいというふうに思います。各学校において、生活リズムについては、やはり小学校１年生から中学生も含めて、きちんとした生活リズムを整えること、また、これは特に早寝早起き朝御飯ではありませんけれども。","voiceIndex":302,"id":"exchange-134"},{"speaker":"大倉委員","kind":"質問・要望","question":"しっかりと子どもたちとともに、啓発とこうした食品ロスに対する取組みを充実していっていただきたいと思います。不登校についても、家庭において指導していくということですが、学校側でもある程度、子どもたちの生活習慣について、現状を知っていくということも重要ではないかと思いますので、そこはぜひ研究していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、ページ数はちょっとわからなくて、学級規模、少人数学級の実施についてを伺いたいと思います。よろしくお願いします。少人数学級は国民の切実な教育要求です。国でこういったさまざま議論がある中、少人数学級が進むのか、とまるのか、こういった議論の中で、品川区として少人数学級の重要性や、今、３５人学級に取り組まれていますけれども、どのように考えているのか伺いたいと思います。","respondent":"有馬学務課長","answer":"そんな中で、区としては、１学年は法に基づいて３５人ですけれども、２年生と、いわゆる中１ギャップ対応ということで、ここは都の対応ということで、加配対応なりがされていて、２年生では３５人学級。","voiceIndex":307,"id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それともう１つ、聞き忘れてしまったのですけれども、小学校と中学校の全体の小中別で、１クラスの平均生徒数を教えていただきたいのです。お願いします。","respondent":"有馬学務課長","answer":"現在の１クラスの平均ですけれども、小学校全体で１クラスの平均人数は２９.８人です。中学校の部分につきましては３２.８人が１クラス平均になってあります。","voiceIndex":309,"id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、私たちは、３５人学級、さらに３０人学級まで進めていくべきだと求めているところなのですけれども、この小学校の１クラス平均生徒数２９.８人ということでしたけれども、ＯＥＣＤの先進国の平均では２１.３人です。道府県では、少人数学級を全学年で進めていくというふうになっているのですけれども、この３５人学級を全学年で進めていっていただきたいと思うのです。","respondent":"有馬学務課長","answer":"３５人、少人数学級にすべきですけれども、教育の質に関しましては、単に学級の人数で評価すべきではないというふうに考えております。","voiceIndex":311,"id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"多くのコストもかかりますし、学級も増やすということになれば、学校のクラス数、教室を増やしていかなければいけないというのは当然のことになってきますので、しかし、それを子どもたちのことを考えれば、最優先に進めていくのが教育条件の整備、少人数学級だと思うのですけれども、国や都に求めていただきたいと思うのですが、いかがでしょうか。","respondent":"有馬学務課長","answer":"我々としても、今後、予想される就学人口増に対してもしっかり受入れをしていかなければいけないという責任もありますので、その辺もしっかり考えあわせていかなければいけないことだというふうに思っているところです。","voiceIndex":313,"id":"exchange-139"},{"speaker":"浅野委員","kind":"確認","question":"最初に、このＩＣＴを活用した教育活動の研究に関連してということですが、２０２０年から小学校でプログラミングの教育が必修化される見通しとなったという報道を、５月ですか、見た記憶があります。教育委員会として有識者会議が行われていると思いますが、内容を確認して、必要な体制をとるなり、動きをするなりしていただければと思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"今後、実際には新たな教員をというよりは、担任が指導していくことが中心になりますけれども、やはり実際になかなかそこの指導は難しい部分もあります。","voiceIndex":316,"id":"exchange-140"},{"speaker":"浅野委員","kind":"確認","question":"そのような中で、品川区の学校の校舎が、このような地震に耐えられるかという、このような強度、耐震強度の調査など、検討はされたのかどうか、ひとつ教えていただければと思います。こちらもやはり大きな地震が、さらに熊本地震級のものが来たときに大丈夫かという、このような安全の確認はもう既にされているのか、また、今後行うのかということについて、現状をお知らせいただければと思います。","respondent":"小林施設整備課長、品川庶務課長","answer":"今の校舎の耐震の関係についてご答弁いたします。建築基準法に基づいて、今回、耐震を済ませておりますので、法律上、現状は大丈夫ということで答弁します。ただ、震度７の地震が何回も何回も続けば、どうなるのかということはわかりませんが、ある程度の地震の回数には耐えられるものと考えています。","voiceIndex":318,"id":"exchange-141"},{"speaker":"浅野委員","kind":"質問・要望","question":"どちらが安全か、一口では言えませんけれども、やはりチルドレンファーストとか、そういう言葉があるとおり、子どもを守るということをこれからも考えていっていただきたい。この件についてはしぶとくやっていきたいと考えていますけれども、ぜひとも検討していただきたいと思います。このような取組みについて、学校としての評価、そしてまた、同じように取り組んでいる学校があれば教えてください。","respondent":"村尾教育総合支援センター長","answer":"今回、それ以外としても、教育長表彰という制度を持っておりまして、やはり各学校で大きな賞等をとった場合については、賞を授与しながら、各学校を含め、区内の皆さんにも周知をしながら、より多く進めていこうというふうに考えているところです。","voiceIndex":323,"id":"exchange-142"},{"speaker":"鈴木（真）委員","kind":"質問","question":"質問者も最後になりました。よろしくお願いします。私は、教育総務費の中で、１７４ページ、教育総合支援センター、それから連合体育大会、品川のスポーツトライアル等経費、この辺に関して質問させてもらいます。","respondent":"村尾教育総合支援センター長","answer":"本区の体力向上のスポーツトライアルについてのご質問です。これにつきましては、各学校、体育主任会での説明をした上で、各学校、ぜひ休み時間等を含めて、子どもたちに運動する習慣づくりをということで、今、進めているところです。","voiceIndex":326,"id":"exchange-143"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"全体的に体力向上、レベルアップを進めていくという、これは進めていただきたい。これは前提なのですが、連合体育大会、９月２７日に実施されたというふうにお聞きしています。というのは、ケーブルテレビか何かで放送することはできないのでしょうか。４月１日の発行となっているのですが、決算の中でこの発行がどこに出てきているかわからなかったので、それを教えてください。","respondent":"村尾教育総合支援センター長、品川庶務課長","answer":"当日、本当にいろいろな保護者の応援もありまして、とても盛り上がっている大会ではあります。ご提案のケーブルテレビ等、さまざまな広報につきましては、少しこちらのほうでも検討させていただければというふうに考えております。「品川の教育」ですが、成果報告書１７７ページの文化財保護費の中に金額としては含まれた形で入ってあります。","voiceIndex":328,"id":"exchange-144"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"「品川の教育」、文化財保護費……。先ほど、我が会派の松澤委員からもお話がありましたけれども、品川寺の梵鐘というのがありましたけれど、こういう地域の話題は、児童・生徒も知らないですし、繰り返しになりますが、先生がやはりわかっていないので、こういうものを活用していただいて、その地域のことを知ってもらいたいなと思うのですが、いかがでしょうか。","respondent":"品川庶務課長","answer":"「品川の教育」ですが、配布先としまして、各学校、それから校長先生用と配布をしています。この中で学習の一部にでも取り入れていただけるように努力していただければというふうに思っております。それから、校長会のほうにもそのような声かけをしていきたいと考えています。","voiceIndex":331,"id":"exchange-145"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ぜひ品川の歴史的なものを引き継いでいってもらいたいと思います。それから、教育総合支援センターの件ですけれども、これは４月から開設して、成果を上げていらっしゃると思うのですが、何が気になるかというと、本庁舎から離れたところにあることで、連携がうまくとれているのか。もちろんとっているとは思うのですが、その辺が非常に気になるところなので、確認の意味でお願いします。","respondent":"村尾教育総合支援センター長","answer":"教育総合支援センターにおきましては、平成２７年度４月に開始いたしました。さまざまな教育的な課題を解決するということで、指導課を組織的には２つに分けてスタートしたということになります。","voiceIndex":333,"id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ連携を取り合って進めていっていただきたいと思います。教育大綱を見ていくと、区の長期基本計画との流れの中で、５つの都市像の中でどうつながっていくのかちょっとわからなかったので、「未来を創る子育て・教育都市」という部分が長計の中に出てきますけれども、そことこの教育大綱のつながりが、どういうふうに入ってくるのか、そこを確認させていただきたいのですが。","respondent":"柏原企画調整課長","answer":"長期基本計画、これは品川区の基本構想にもつながる部分ですけれども、その中の１つの大きな都市像ということで、区全体の施策を進める中で、「未来を創る子育て・教育都市」ということで、施策の大きな分野として切ったものがまず長期基本計画です。","voiceIndex":335,"id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほど、総合教育会議の中で詰めて、方針としては一般に出ていると思うのですが、都市像の下に基本方針が出てくるのです。基本方針がこの教育大綱と同じように見えてしまったので、項目が、例えば生涯学習とかいろいろ出てくる中で、そこが確認をしたかったのですが。","respondent":"柏原企画調整課長","answer":"その方針、長期基本計画でいろいろ方針が出ている部分について、この大綱の部分と整合性をとりながらというところで策定をさせていただいたですので、具体的にどう進めるかというところで、この長期基本計画との整合をとったというところが中身です。","voiceIndex":337,"id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もちろん整合性をとって流れをきちんとしていらっしゃると思うので、ちょっと自分が見た範囲でここがどうもすっきりしなかったので、ちょっと確認をさせてもらいました。それから、今日も教育費でいろいろな質疑が行われました。その辺、少しまとめて教育委員会の考えというか、教育長、もしよろしければ、品川の子どもに対してどのようにこれからやっていっていただくか、お考えをお聞きしたいと思います。","respondent":"中島教育長","answer":"警察との連携、また外部とのトラブル、そういった状況が多くある中で、この１０年の市民科の実施を中心とする重要なことに取り組み、また、さまざまな施策の中で大きく改善している状況もあろうかと考えております。","voiceIndex":339,"id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いろいろお話を伺って、ぜひ進めていっていただきたいし、基本方針に、たしか将来を生き抜く力ということもあったと思います。そのためにも品川の子どもたちのために、ぜひ頑張っていただきたいと思います。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":341,"id":"exchange-150"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1430#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":119474,"voices":342}}]);
